{
  "name": "ReagentFlow - Lab Stock Manager",
  "description": "An advanced laboratory reagent inventory management system featuring AI-powered label recognition, smart stock level alerts, and multi-department tracking.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type Presentation = 'Líquido' | 'Sólido' | 'Paquete';
export type Department = 'Fisicoquímico' | 'Microbiología' | 'Molecular';
export type UserRole = 'ANALISTA' | 'GERENTE';
export type TransactionType = 'IN' | 'OUT';

export interface Reagent {
  id: string;
  name: string;
  brand: string;
  presentation: Presentation;
  currentStock: number;
  minStock: number;
  department: Department;
  unit: string; // e.g., 'botellas', 'gramos', 'unidades'
  expiryDate: string; // ISO string or "N/A"
  isOrdered: boolean;
  lastUpdated: string;
}

export interface Transaction {
  id: string;
  reagentId: string;
  reagentName: string;
  type: TransactionType;
  quantity: number;
  unit: string;
  analyst: string;
  timestamp: string;
}

export interface AIAnalysisResult {
  name: string;
  brand: string;
  presentation: Presentation;
}

import { GoogleGenAI, Type } from "@google/genai";
import { AIAnalysisResult } from "../types";

const API_KEY = process.env.API_KEY || "";

export const analyzeReagentLabel = async (base64Image: string): Promise<AIAnalysisResult> => {
  const ai = new GoogleGenAI({ apiKey: API_KEY });

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: base64Image,
            },
          },
          {
            text: "Analiza esta etiqueta de reactivo de laboratorio. Extrae el nombre del reactivo, la marca y clasifica su presentación como 'Líquido', 'Sólido' o 'Paquete'. Responde únicamente en formato JSON."
          }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            name: { type: Type.STRING },
            brand: { type: Type.STRING },
            presentation: { 
              type: Type.STRING,
              description: "Must be 'Líquido', 'Sólido', or 'Paquete'"
            }
          },
          required: ["name", "brand", "presentation"]
        }
      }
    });

    const text = response.text || "{}";
    return JSON.parse(text) as AIAnalysisResult;
  } catch (error) {
    console.error("Error analyzing image with Gemini:", error);
    throw new Error("No se pudo analizar la imagen. Por favor, intenta de nuevo o ingresa los datos manualmente.");
  }
};

export const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => {
      const result = reader.result as string;
      // Remove data:image/jpeg;base64, prefix
      resolve(result.split(',')[1]);
    };
    reader.onerror = (error) => reject(error);
  });
};

export const formatDate = (dateString: string) => {
  if (dateString === "N/A") return "N/A";
  const date = new Date(dateString);
  return date.toLocaleDateString('es-ES', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric'
  });
};

export const formatDateTime = (dateString: string) => {
  const date = new Date(dateString);
  return date.toLocaleString('es-ES', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit'
  });
};

export const generateId = () => Math.random().toString(36).substr(2, 9);

import React, { useState, useEffect, useMemo } from 'react';
import { HashRouter as Router, Routes, Route, Link, Navigate, useLocation } from 'react-router-dom';
import { 
  BeakerIcon, 
  ArrowsRightLeftIcon, 
  QueueListIcon, 
  BellAlertIcon, 
  PlusCircleIcon, 
  MinusCircleIcon,
  UserCircleIcon,
  ArrowRightOnRectangleIcon,
  HomeIcon,
  ChevronRightIcon
} from '@heroicons/react/24/outline';

import { Reagent, Transaction, UserRole, Department, Presentation } from './types';
import InventoryView from './components/InventoryView';
import InputForm from './components/InputForm';
import OutputForm from './components/OutputForm';
import HistoryView from './components/HistoryView';
import AlertsView from './components/AlertsView';
import { generateId } from './utils';

const STORAGE_KEY_REAGENTS = 'reagentflow_inventory';
const STORAGE_KEY_TRANSACTIONS = 'reagentflow_transactions';

const App: React.FC = () => {
  const [role, setRole] = useState<UserRole | null>(null);
  const [reagents, setReagents] = useState<Reagent[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);

  // Load initial data
  useEffect(() => {
    const savedReagents = localStorage.getItem(STORAGE_KEY_REAGENTS);
    const savedTransactions = localStorage.getItem(STORAGE_KEY_TRANSACTIONS);

    if (savedReagents) setReagents(JSON.parse(savedReagents));
    if (savedTransactions) setTransactions(JSON.parse(savedTransactions));
  }, []);

  // Sync with LocalStorage
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY_REAGENTS, JSON.stringify(reagents));
  }, [reagents]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY_TRANSACTIONS, JSON.stringify(transactions));
  }, [transactions]);

  // Core Stock Update Logic
  const handleTransaction = (reagent: Partial<Reagent>, transactionData: Omit<Transaction, 'id' | 'timestamp' | 'reagentName'>) => {
    const timestamp = new Date().toISOString();
    let updatedReagents = [...reagents];
    let reagentId = transactionData.reagentId;

    if (transactionData.type === 'IN') {
      const existingIdx = updatedReagents.findIndex(r => r.id === reagentId);

      if (existingIdx > -1) {
        // Update existing
        const existing = updatedReagents[existingIdx];
        updatedReagents[existingIdx] = {
          ...existing,
          currentStock: existing.currentStock + transactionData.quantity,
          lastUpdated: timestamp,
          isOrdered: false // Reset alert if it was ordered
        };
      } else {
        // Create new
        const newReagent: Reagent = {
          id: reagentId || generateId(),
          name: reagent.name!,
          brand: reagent.brand!,
          presentation: reagent.presentation!,
          currentStock: transactionData.quantity,
          minStock: reagent.minStock || 0,
          department: reagent.department!,
          unit: transactionData.unit,
          expiryDate: reagent.expiryDate || 'N/A',
          isOrdered: false,
          lastUpdated: timestamp
        };
        updatedReagents.push(newReagent);
        reagentId = newReagent.id;
      }
    } else {
      // OUT transaction
      const existingIdx = updatedReagents.findIndex(r => r.id === reagentId);
      if (existingIdx > -1) {
        const existing = updatedReagents[existingIdx];
        updatedReagents[existingIdx] = {
          ...existing,
          currentStock: Math.max(0, existing.currentStock - transactionData.quantity),
          lastUpdated: timestamp
        };
      }
    }

    setReagents(updatedReagents);

    const newTransaction: Transaction = {
      ...transactionData,
      id: generateId(),
      reagentId,
      reagentName: updatedReagents.find(r => r.id === reagentId)?.name || 'Desconocido',
      timestamp
    };
    setTransactions([newTransaction, ...transactions]);
  };

  const updateMinStock = (reagentId: string, newMinStock: number) => {
    setReagents(prev => prev.map(r => r.id === reagentId ? { ...r, minStock: newMinStock } : r));
  };

  const markAsOrdered = (reagentId: string) => {
    setReagents(prev => prev.map(r => r.id === reagentId ? { ...r, isOrdered: true } : r));
  };

  if (!role) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-600 to-indigo-900 flex items-center justify-center p-4">
        <div className="bg-white rounded-2xl shadow-2xl p-8 w-full max-w-md text-center">
          <BeakerIcon className="w-16 h-16 text-indigo-600 mx-auto mb-4" />
          <h1 className="text-3xl font-bold text-slate-800 mb-2">ReagentFlow</h1>
          <p className="text-slate-500 mb-8">Control Inteligente de Inventario para Laboratorios</p>

          <div className="space-y-4">
            <button 
              onClick={() => setRole('ANALISTA')}
              className="w-full bg-white border-2 border-slate-200 hover:border-indigo-600 hover:text-indigo-600 text-slate-700 font-semibold py-4 px-6 rounded-xl transition-all flex items-center justify-between group"
            >
              <div className="flex items-center gap-3">
                <QueueListIcon className="w-6 h-6" />
                <span>Entrar como Analista</span>
              </div>
              <ChevronRightIcon className="w-5 h-5 opacity-0 group-hover:opacity-100 transition-opacity" />
            </button>

            <button 
              onClick={() => setRole('GERENTE')}
              className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-semibold py-4 px-6 rounded-xl transition-all flex items-center justify-between group shadow-lg"
            >
              <div className="flex items-center gap-3">
                <BellAlertIcon className="w-6 h-6" />
                <span>Entrar como Gerente</span>
              </div>
              <ChevronRightIcon className="w-5 h-5 opacity-50 group-hover:opacity-100 transition-opacity" />
            </button>
          </div>

          <div className="mt-8 text-xs text-slate-400">
            v1.2.0 &bull; Powered by Gemini AI
          </div>
        </div>
      </div>
    );
  }

  return (
    <Router>
      <div className="flex flex-col min-h-screen bg-slate-50">
        {/* Navigation */}
        <nav className="bg-white border-b border-slate-200 sticky top-0 z-30 shadow-sm">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex justify-between h-16">
              <div className="flex items-center gap-2">
                <BeakerIcon className="h-8 w-8 text-indigo-600" />
                <span className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-indigo-600 to-blue-500 hidden sm:block">ReagentFlow</span>
              </div>

              <div className="flex items-center gap-4">
                <div className="hidden md:flex items-center gap-6 mr-6">
                  <Link to="/" className="text-slate-600 hover:text-indigo-600 font-medium">Inventario</Link>
                  <Link to="/ingreso" className="text-slate-600 hover:text-indigo-600 font-medium">Ingresos</Link>
                  <Link to="/salida" className="text-slate-600 hover:text-indigo-600 font-medium">Salidas</Link>
                  <Link to="/historial" className="text-slate-600 hover:text-indigo-600 font-medium">Historial</Link>
                  {role === 'GERENTE' && (
                    <Link to="/alertas" className="flex items-center gap-1 text-slate-600 hover:text-red-600 font-medium">
                      Alertas
                      {reagents.filter(r => r.currentStock <= r.minStock && !r.isOrdered).length > 0 && (
                        <span className="bg-red-500 text-white text-[10px] px-1.5 py-0.5 rounded-full">
                          {reagents.filter(r => r.currentStock <= r.minStock && !r.isOrdered).length}
                        </span>
                      )}
                    </Link>
                  )}
                </div>

                <div className="flex items-center gap-2 bg-slate-100 px-3 py-1.5 rounded-full">
                  <UserCircleIcon className="w-5 h-5 text-slate-500" />
                  <span className="text-sm font-semibold text-slate-700">{role}</span>
                </div>

                <button 
                  onClick={() => setRole(null)}
                  className="p-2 text-slate-400 hover:text-red-600 transition-colors"
                  title="Salir"
                >
                  <ArrowRightOnRectangleIcon className="w-6 h-6" />
                </button>
              </div>
            </div>
          </div>
        </nav>

        {/* Mobile Nav */}
        <div className="md:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-slate-200 z-50 flex justify-around py-3">
          <Link to="/" className="flex flex-col items-center text-slate-400 active:text-indigo-600">
            <HomeIcon className="w-6 h-6" />
            <span className="text-[10px] mt-1">Inicio</span>
          </Link>
          <Link to="/ingreso" className="flex flex-col items-center text-slate-400 active:text-indigo-600">
            <PlusCircleIcon className="w-6 h-6" />
            <span className="text-[10px] mt-1">Ingreso</span>
          </Link>
          <Link to="/salida" className="flex flex-col items-center text-slate-400 active:text-indigo-600">
            <MinusCircleIcon className="w-6 h-6" />
            <span className="text-[10px] mt-1">Salida</span>
          </Link>
          <Link to="/historial" className="flex flex-col items-center text-slate-400 active:text-indigo-600">
            <QueueListIcon className="w-6 h-6" />
            <span className="text-[10px] mt-1">Historial</span>
          </Link>
          {role === 'GERENTE' && (
            <Link to="/alertas" className="flex flex-col items-center text-slate-400 active:text-indigo-600">
              <BellAlertIcon className="w-6 h-6" />
              <span className="text-[10px] mt-1">Alertas</span>
            </Link>
          )}
        </div>

        <main className="flex-grow max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 mb-20 md:mb-8">
          <Routes>
            <Route path="/" element={<InventoryView reagents={reagents} />} />
            <Route path="/ingreso" element={<InputForm reagents={reagents} onTransaction={handleTransaction} transactions={transactions} />} />
            <Route path="/salida" element={<OutputForm reagents={reagents} onTransaction={handleTransaction} />} />
            <Route path="/historial" element={<HistoryView transactions={transactions} />} />
            <Route 
              path="/alertas" 
              element={role === 'GERENTE' ? (
                <AlertsView 
                  reagents={reagents} 
                  markAsOrdered={markAsOrdered} 
                  onUpdateMinStock={updateMinStock}
                />
              ) : (
                <Navigate to="/" />
              )} 
            />
          </Routes>
        </main>
      </div>
    </Router>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Reagent } from '../types';
import { MagnifyingGlassIcon, FunnelIcon } from '@heroicons/react/24/outline';
import { formatDate } from '../utils';

interface Props {
  reagents: Reagent[];
}

const InventoryView: React.FC<Props> = ({ reagents }) => {
  const [search, setSearch] = useState('');
  const [deptFilter, setDeptFilter] = useState<string>('all');

  const filteredReagents = useMemo(() => {
    return reagents.filter(r => {
      const matchesSearch = r.name.toLowerCase().includes(search.toLowerCase()) || 
                            r.brand.toLowerCase().includes(search.toLowerCase());
      const matchesDept = deptFilter === 'all' || r.department === deptFilter;
      return matchesSearch && matchesDept;
    });
  }, [reagents, search, deptFilter]);

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-800">Inventario de Reactivos</h1>
          <p className="text-slate-500">Visualiza y gestiona todos los recursos disponibles.</p>
        </div>

        <div className="flex flex-col sm:flex-row gap-3">
          <div className="relative">
            <MagnifyingGlassIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
            <input 
              type="text"
              placeholder="Buscar reactivo..."
              className="pl-10 pr-4 py-2 bg-white border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none w-full sm:w-64 transition-all"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
          </div>

          <div className="relative">
            <FunnelIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
            <select 
              className="pl-10 pr-8 py-2 bg-white border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none appearance-none cursor-pointer transition-all"
              value={deptFilter}
              onChange={(e) => setDeptFilter(e.target.value)}
            >
              <option value="all">Todos los Deptos.</option>
              <option value="Fisicoquímico">Fisicoquímico</option>
              <option value="Microbiología">Microbiología</option>
              <option value="Molecular">Molecular</option>
            </select>
          </div>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-slate-50 border-b border-slate-200">
              <tr>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Reactivo</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Presentación</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Stock</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Departamento</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Vencimiento</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Estado</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredReagents.length > 0 ? (
                filteredReagents.map(reagent => {
                  const isLow = reagent.currentStock <= reagent.minStock;
                  return (
                    <tr key={reagent.id} className="hover:bg-slate-50 transition-colors">
                      <td className="px-6 py-4">
                        <div className="font-semibold text-slate-800">{reagent.name}</div>
                        <div className="text-xs text-slate-500">{reagent.brand}</div>
                      </td>
                      <td className="px-6 py-4 text-sm text-slate-600">{reagent.presentation}</td>
                      <td className="px-6 py-4">
                        <span className={`text-sm font-bold ${isLow ? 'text-red-600' : 'text-slate-800'}`}>
                          {reagent.currentStock} {reagent.unit}
                        </span>
                        <div className="text-[10px] text-slate-400">Min: {reagent.minStock}</div>
                      </td>
                      <td className="px-6 py-4">
                        <span className="inline-flex items-center px-2 py-1 rounded-md text-xs font-medium bg-slate-100 text-slate-700 border border-slate-200">
                          {reagent.department}
                        </span>
                      </td>
                      <td className="px-6 py-4 text-sm text-slate-600">
                        {formatDate(reagent.expiryDate)}
