export default InventoryView;

import React, { useState, useRef, useMemo } from 'react';
import { Reagent, Presentation, Department, Transaction } from '../types';
import { analyzeReagentLabel } from '../services/geminiService';
import { fileToBase64, generateId } from '../utils';
import { 
  CameraIcon, 
  SparklesIcon, 
  ArrowPathIcon,
  CheckCircleIcon,
  ExclamationCircleIcon
} from '@heroicons/react/24/solid';

interface Props {
  reagents: Reagent[];
  transactions: Transaction[];
  onTransaction: (reagent: Partial<Reagent>, data: any) => void;
}

const InputForm: React.FC<Props> = ({ reagents, transactions, onTransaction }) => {
  const [loading, setLoading] = useState(false);
  const [isExisting, setIsExisting] = useState(false);
  const [selectedReagentId, setSelectedReagentId] = useState('');

  // Form State
  const [formData, setFormData] = useState({
    name: '',
    brand: '',
    presentation: 'Líquido' as Presentation,
    quantity: 0,
    unit: '',
    expiryDate: '',
    department: 'Fisicoquímico' as Department,
    analystName: '',
    minStock: 0
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Auto-calculate suggested min stock based on usage history (average weekly use)
  const suggestedMinStock = useMemo(() => {
    if (!isExisting || !selectedReagentId) return 0;

    const reagentTransactions = transactions.filter(t => t.reagentId === selectedReagentId && t.type === 'OUT');
    if (reagentTransactions.length < 2) return 10; // Default if not enough data

    // Logic: Total consumed in the period / weeks in period
    const timestamps = reagentTransactions.map(t => new Date(t.timestamp).getTime());
    const minTime = Math.min(...timestamps);
    const maxTime = Math.max(...timestamps);
    const totalConsumed = reagentTransactions.reduce((acc, t) => acc + t.quantity, 0);

    const diffDays = Math.max(1, (maxTime - minTime) / (1000 * 60 * 60 * 24));
    const weeklyAvg = (totalConsumed / diffDays) * 7;

    return Math.ceil(weeklyAvg);
  }, [isExisting, selectedReagentId, transactions]);

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    try {
      const base64 = await fileToBase64(file);
      const analysis = await analyzeReagentLabel(base64);

      setFormData(prev => ({
        ...prev,
        name: analysis.name || '',
        brand: analysis.brand || '',
        presentation: analysis.presentation || 'Líquido'
      }));

      // Check if it exists in inventory to toggle mode
      const existing = reagents.find(r => 
        r.name.toLowerCase() === analysis.name.toLowerCase() && 
        r.brand.toLowerCase() === analysis.brand.toLowerCase()
      );

      if (existing) {
        setIsExisting(true);
        setSelectedReagentId(existing.id);
        setFormData(prev => ({ ...prev, unit: existing.unit, minStock: existing.minStock }));
      } else {
        setIsExisting(false);
      }
    } catch (error) {
      alert("Error analizando la etiqueta. Por favor ingresa los datos manualmente.");
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    onTransaction(
      {
        id: isExisting ? selectedReagentId : undefined,
        name: formData.name,
        brand: formData.brand,
        presentation: formData.presentation,
        department: formData.department,
        expiryDate: formData.expiryDate || 'N/A',
        minStock: formData.minStock || suggestedMinStock
      },
      {
        reagentId: isExisting ? selectedReagentId : undefined,
        type: 'IN',
        quantity: formData.quantity,
        unit: formData.unit,
        analyst: formData.analystName
      }
    );

    // Reset Form
    setFormData({
      name: '', brand: '', presentation: 'Líquido', quantity: 0, 
      unit: '', expiryDate: '', department: 'Fisicoquímico', 
      analystName: '', minStock: 0
    });
    setIsExisting(false);
    setSelectedReagentId('');
    alert("Ingreso registrado exitosamente.");
  };

  const handleExistingSelect = (id: string) => {
    setSelectedReagentId(id);
    const r = reagents.find(x => x.id === id);
    if (r) {
      setFormData(prev => ({
        ...prev,
        name: r.name,
        brand: r.brand,
        presentation: r.presentation,
        unit: r.unit,
        minStock: r.minStock
      }));
    }
  };

  return (
    <div className="max-w-3xl mx-auto">
