import React, { useState, useRef, useMemo } from 'react';
import { Reagent, Transaction } from '../types';
import { analyzeReagentLabel } from '../services/geminiService';
import { fileToBase64 } from '../utils';
import { 
  CameraIcon, 
  ArrowPathIcon,
  MinusCircleIcon,
  ExclamationTriangleIcon
} from '@heroicons/react/24/solid';

interface Props {
  reagents: Reagent[];
  onTransaction: (reagent: Partial<Reagent>, data: any) => void;
}

const OutputForm: React.FC<Props> = ({ reagents, onTransaction }) => {
  const [loading, setLoading] = useState(false);
  const [selectedReagentId, setSelectedReagentId] = useState('');
  const [formData, setFormData] = useState({
    quantity: 0,
    analystName: '',
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  const selectedReagent = useMemo(() => {
    return reagents.find(r => r.id === selectedReagentId);
  }, [reagents, selectedReagentId]);

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    try {
      const base64 = await fileToBase64(file);
      const analysis = await analyzeReagentLabel(base64);

      const found = reagents.find(r => 
        r.name.toLowerCase().includes(analysis.name.toLowerCase()) || 
        analysis.name.toLowerCase().includes(r.name.toLowerCase())
      );

      if (found) {
        setSelectedReagentId(found.id);
      } else {
        alert("No se encontró el reactivo en el inventario actual.");
      }
    } catch (error) {
      alert("Error al analizar la imagen.");
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedReagent) return;

    if (formData.quantity > selectedReagent.currentStock) {
      alert("Error: No puedes retirar más de lo que hay en stock.");
      return;
    }

    onTransaction(
      {},
      {
        reagentId: selectedReagentId,
        type: 'OUT',
        quantity: formData.quantity,
        unit: selectedReagent.unit,
        analyst: formData.analystName
      }
    );

    // Reset
    setSelectedReagentId('');
    setFormData({ quantity: 0, analystName: '' });
    alert("Consumo registrado correctamente.");
  };

  return (
    <div className="max-w-3xl mx-auto">
      <div className="bg-white rounded-2xl shadow-xl border border-slate-200 overflow-hidden">
        <div className="bg-rose-600 p-6 text-white flex justify-between items-center">
          <div>
            <h2 className="text-xl font-bold">Registro de Consumo (Salida)</h2>
            <p className="text-rose-100 text-sm">Disminuye el stock por uso en laboratorio.</p>
          </div>
          <MinusCircleIcon className="w-8 h-8 opacity-50" />
        </div>

        <div className="p-8">
          <div className="flex flex-wrap gap-4 mb-8">
             <button 
              type="button"
              onClick={() => fileInputRef.current?.click()}
              disabled={loading}
              className="flex-1 flex items-center justify-center gap-2 bg-rose-50 hover:bg-rose-100 text-rose-700 py-3 px-4 rounded-xl border border-rose-200 font-semibold transition-all"
            >
              {loading ? (
                <ArrowPathIcon className="w-5 h-5 animate-spin" />
              ) : (
                <CameraIcon className="w-5 h-5" />
              )}
              {loading ? "Reconociendo..." : "Foto del Envase"}
            </button>
            <input 
              type="file" 
              ref={fileInputRef} 
              className="hidden" 
              accept="image/*"
              onChange={handleImageUpload}
            />

            <div className="flex-1">
              <select 
                className="w-full bg-slate-50 border border-slate-200 py-3 px-4 rounded-xl text-slate-700 font-medium outline-none focus:ring-2 focus:ring-rose-500"
                value={selectedReagentId}
                onChange={(e) => setSelectedReagentId(e.target.value)}
              >
                <option value="">-- Seleccionar Reactivo --</option>
                {reagents.map(r => (
                  <option key={r.id} value={r.id}>
                    {r.name} ({r.currentStock} {r.unit} disponibles)
                  </option>
                ))}
              </select>
            </div>
          </div>

          {selectedReagent && (
            <form onSubmit={handleSubmit} className="space-y-6 animate-in fade-in duration-300">
              <div className="bg-slate-50 p-6 rounded-2xl border border-slate-100 grid grid-cols-2 md:grid-cols-4 gap-4">
                <div>
                  <p className="text-[10px] uppercase font-bold text-slate-400">Reactivo</p>
                  <p className="font-semibold text-slate-800">{selectedReagent.name}</p>
                </div>
                <div>
                  <p className="text-[10px] uppercase font-bold text-slate-400">Marca</p>
                  <p className="font-semibold text-slate-800">{selectedReagent.brand}</p>
                </div>
                <div>
                  <p className="text-[10px] uppercase font-bold text-slate-400">Presentación</p>
                  <p className="font-semibold text-slate-800">{selectedReagent.presentation}</p>
                </div>
                <div>
                  <p className="text-[10px] uppercase font-bold text-slate-400">En Stock</p>
                  <p className={`font-bold ${selectedReagent.currentStock <= selectedReagent.minStock ? 'text-rose-600' : 'text-emerald-600'}`}>
                    {selectedReagent.currentStock} {selectedReagent.unit}
                  </p>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-sm font-semibold text-slate-700">Cantidad a Retirar</label>
                  <div className="relative">
                    <input 
                      type="number"
                      required
                      min="1"
                      max={selectedReagent.currentStock}
                      className="w-full pl-4 pr-20 py-3 border border-slate-200 rounded-lg outline-none focus:ring-2 focus:ring-rose-500"
                      value={formData.quantity || ''}
                      onChange={e => setFormData({...formData, quantity: parseInt(e.target.value)})}
                    />
                    <span className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 font-medium">
                      {selectedReagent.unit}
                    </span>
                  </div>
                </div>

                <div className="space-y-2">
                  <label className="text-sm font-semibold text-slate-700">Analista Solicitante</label>
                  <input 
                    type="text"
                    required
                    placeholder="Tu nombre completo"
                    className="w-full px-4 py-3 border border-slate-200 rounded-lg outline-none focus:ring-2 focus:ring-rose-500"
                    value={formData.analystName}
                    onChange={e => setFormData({...formData, analystName: e.target.value})}
                  />
                </div>
              </div>

              {selectedReagent.currentStock <= selectedReagent.minStock && (
                <div className="bg-amber-50 p-4 rounded-xl border border-amber-200 flex gap-3">
                  <ExclamationTriangleIcon className="w-6 h-6 text-amber-500 shrink-0" />
                  <p className="text-sm text-amber-700 font-medium">
                    Atención: Este reactivo ya está por debajo de su stock mínimo. Se enviará una alerta automática a Gerencia al procesar esta salida.
                  </p>
                </div>
              )}

              <button 
                type="submit"
                className="w-full bg-rose-600 hover:bg-rose-700 text-white font-bold py-4 rounded-xl shadow-lg transition-all transform active:scale-[0.98]"
              >
                Registrar Salida
              </button>
            </form>
          )}

          {!selectedReagent && (
            <div className="py-20 text-center text-slate-400">
              <p>Selecciona un reactivo arriba o escanea su envase para comenzar.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default OutputForm;

