import React, { useMemo } from 'react';
import { Reagent } from '../types';
import { 
  BellAlertIcon, 
  ShoppingBagIcon, 
  CheckCircleIcon,
  ExclamationCircleIcon
} from '@heroicons/react/24/solid';

interface Props {
  reagents: Reagent[];
  markAsOrdered: (id: string) => void;
  onUpdateMinStock: (id: string, newMin: number) => void;
}

const AlertsView: React.FC<Props> = ({ reagents, markAsOrdered, onUpdateMinStock }) => {
  const lowStockReagents = useMemo(() => {
    return reagents.filter(r => r.currentStock <= r.minStock && !r.isOrdered);
  }, [reagents]);

  const orderedReagents = useMemo(() => {
    return reagents.filter(r => r.isOrdered);
  }, [reagents]);

  return (
    <div className="space-y-10">
      <div className="bg-red-50 border-l-4 border-red-500 p-6 rounded-r-xl">
        <div className="flex items-center gap-3 mb-2">
          <BellAlertIcon className="w-8 h-8 text-red-600" />
          <h1 className="text-2xl font-bold text-red-900">Panel de Alertas de Stock</h1>
        </div>
        <p className="text-red-700 font-medium">Estos reactivos necesitan reposición inmediata para evitar interrupciones en el laboratorio.</p>
      </div>

      <div className="space-y-6">
        <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2">
          <ExclamationCircleIcon className="w-5 h-5 text-red-600" />
          Necesitan Pedido ({lowStockReagents.length})
        </h2>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {lowStockReagents.length > 0 ? (
            lowStockReagents.map(r => (
              <div key={r.id} className="bg-white rounded-2xl shadow-md border border-red-100 overflow-hidden group">
                <div className="p-5">
                  <div className="flex justify-between items-start mb-4">
                    <div>
                      <h3 className="font-bold text-slate-800 text-lg">{r.name}</h3>
                      <p className="text-xs text-slate-500 uppercase tracking-widest">{r.brand}</p>
                    </div>
                    <span className="bg-red-100 text-red-700 text-[10px] font-bold px-2 py-1 rounded-full uppercase">Crítico</span>
                  </div>

                  <div className="space-y-3 mb-6">
                    <div className="flex justify-between text-sm">
                      <span className="text-slate-500">Stock Actual:</span>
                      <span className="font-bold text-red-600">{r.currentStock} {r.unit}</span>
                    </div>
                    <div className="flex justify-between text-sm">
                      <span className="text-slate-500">Stock Mínimo:</span>
                      <div className="flex items-center gap-2">
                        <input 
                          type="number" 
                          className="w-16 border-b border-slate-200 text-right focus:border-indigo-500 outline-none"
                          value={r.minStock}
                          onChange={(e) => onUpdateMinStock(r.id, parseInt(e.target.value))}
                        />
                        <span className="text-slate-500">{r.unit}</span>
                      </div>
                    </div>
                    <div className="h-1.5 w-full bg-slate-100 rounded-full overflow-hidden">
                      <div 
                        className="h-full bg-red-500" 
                        style={{ width: `${Math.min(100, (r.currentStock / r.minStock) * 100)}%` }}
                      ></div>
                    </div>
                  </div>

                  <button 
                    onClick={() => markAsOrdered(r.id)}
                    className="w-full flex items-center justify-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 rounded-xl transition-all shadow-indigo-200 shadow-lg"
                  >
                    <ShoppingBagIcon className="w-5 h-5" />
                    Marcar como Pedido
                  </button>
                </div>
                <div className="bg-slate-50 px-5 py-3 text-[10px] text-slate-400 font-medium">
                  ÚLTIMO MOVIMIENTO: {new Date(r.lastUpdated).toLocaleDateString()}
                </div>
              </div>
            ))
          ) : (
            <div className="col-span-full py-12 text-center bg-emerald-50 rounded-2xl border border-emerald-100">
              <CheckCircleIcon className="w-12 h-12 text-emerald-500 mx-auto mb-2" />
              <p className="text-emerald-800 font-bold">¡Todo en orden!</p>
              <p className="text-emerald-600 text-sm">No hay reactivos con stock crítico actualmente.</p>
            </div>
          )}
        </div>
      </div>

      {orderedReagents.length > 0 && (
        <div className="space-y-6 opacity-60 hover:opacity-100 transition-opacity">
          <h2 className="text-lg font-bold text-slate-500 flex items-center gap-2">
            <ShoppingBagIcon className="w-5 h-5" />
            Ya Pedidos ({orderedReagents.length})
          </h2>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            {orderedReagents.map(r => (
              <div key={r.id} className="bg-white p-4 rounded-xl border border-slate-200 flex justify-between items-center shadow-sm">
                <div>
                  <p className="font-bold text-slate-700 text-sm">{r.name}</p>
                  <p className="text-xs text-slate-400">Esperando stock...</p>
                </div>
                <div className="bg-indigo-50 text-indigo-600 p-2 rounded-lg">
                  <ArrowPathIcon className="w-5 h-5 animate-spin" />
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

