);

export default AlertsView;

import React, { useState, useEffect, useMemo } from 'react';
import { HashRouter as Router, Routes, Route, Link, Navigate, useLocation } from 'react-router-dom';
import { 
  BeakerIcon, 
  ArrowsRightLeftIcon, 
  QueueListIcon, 
  BellAlertIcon, 
  PlusCircleIcon, 
  MinusCircleIcon,
  UserCircleIcon,
  ArrowRightOnRectangleIcon,
  HomeIcon,
  ChevronRightIcon,
  LockClosedIcon,
  EyeIcon,
  EyeSlashIcon
} from '@heroicons/react/24/outline';

import { Reagent, Transaction, UserRole, Department, Presentation } from './types';
import InventoryView from './components/InventoryView';
import InputForm from './components/InputForm';
import OutputForm from './components/OutputForm';
import HistoryView from './components/HistoryView';
import AlertsView from './components/AlertsView';
import { generateId } from './utils';

const STORAGE_KEY_REAGENTS = 'reagentflow_inventory';
const STORAGE_KEY_TRANSACTIONS = 'reagentflow_transactions';
const STORAGE_KEY_PASSWORD = 'reagentflow_mg_pwd';

const App: React.FC = () => {
  const [role, setRole] = useState<UserRole | null>(null);
  const [reagents, setReagents] = useState<Reagent[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);

  // Auth state
  const [showAuthModal, setShowAuthModal] = useState(false);
  const [storedPassword, setStoredPassword] = useState<string | null>(localStorage.getItem(STORAGE_KEY_PASSWORD));
  const [authInput, setAuthInput] = useState('');
  const [authError, setAuthError] = useState('');
  const [showPassword, setShowPassword] = useState(false);

  // Load initial data
  useEffect(() => {
    const savedReagents = localStorage.getItem(STORAGE_KEY_REAGENTS);
    const savedTransactions = localStorage.getItem(STORAGE_KEY_TRANSACTIONS);

    if (savedReagents) setReagents(JSON.parse(savedReagents));
    if (savedTransactions) setTransactions(JSON.parse(savedTransactions));
  }, []);

  // Sync with LocalStorage
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY_REAGENTS, JSON.stringify(reagents));
  }, [reagents]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY_TRANSACTIONS, JSON.stringify(transactions));
  }, [transactions]);

  const handleTransaction = (reagent: Partial<Reagent>, transactionData: Omit<Transaction, 'id' | 'timestamp' | 'reagentName'>) => {
    const timestamp = new Date().toISOString();
    let updatedReagents = [...reagents];
    let reagentId = transactionData.reagentId;

    if (transactionData.type === 'IN') {
      const existingIdx = updatedReagents.findIndex(r => r.id === reagentId);

      if (existingIdx > -1) {
        const existing = updatedReagents[existingIdx];
        updatedReagents[existingIdx] = {
          ...existing,
          currentStock: existing.currentStock + transactionData.quantity,
          lastUpdated: timestamp,
          isOrdered: false
        };
      } else {
        const newReagent: Reagent = {
          id: reagentId || generateId(),
          name: reagent.name!,
          brand: reagent.brand!,
          presentation: reagent.presentation!,
          currentStock: transactionData.quantity,
          minStock: reagent.minStock || 0,
          department: reagent.department!,
          unit: transactionData.unit,
          expiryDate: reagent.expiryDate || 'N/A',
          isOrdered: false,
          lastUpdated: timestamp
        };
        updatedReagents.push(newReagent);
        reagentId = newReagent.id;
      }
    } else {
      const existingIdx = updatedReagents.findIndex(r => r.id === reagentId);
      if (existingIdx > -1) {
        const existing = updatedReagents[existingIdx];
        updatedReagents[existingIdx] = {
          ...existing,
          currentStock: Math.max(0, existing.currentStock - transactionData.quantity),
          lastUpdated: timestamp
        };
      }
    }

    setReagents(updatedReagents);

    const newTransaction: Transaction = {
      ...transactionData,
      id: generateId(),
      reagentId,
      reagentName: updatedReagents.find(r => r.id === reagentId)?.name || 'Desconocido',
      timestamp
    };
    setTransactions([newTransaction, ...transactions]);
  };

  const updateMinStock = (reagentId: string, newMinStock: number) => {
    setReagents(prev => prev.map(r => r.id === reagentId ? { ...r, minStock: newMinStock } : r));
  };

  const markAsOrdered = (reagentId: string) => {
    setReagents(prev => prev.map(r => r.id === reagentId ? { ...r, isOrdered: true } : r));
  };

  const handleAuthSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!storedPassword) {
      // Setup phase
      if (authInput.length < 4) {
        setAuthError('La contraseña debe tener al menos 4 caracteres');
        return;
      }
      localStorage.setItem(STORAGE_KEY_PASSWORD, authInput);
      setStoredPassword(authInput);
      setRole('GERENTE');
      setShowAuthModal(false);
      setAuthInput('');
    } else {
      // Login phase
      if (authInput === storedPassword) {
        setRole('GERENTE');
        setShowAuthModal(false);
        setAuthInput('');
        setAuthError('');
      } else {
        setAuthError('Contraseña incorrecta');
      }
    }
  };

  if (!role) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-600 to-indigo-900 flex items-center justify-center p-4">
        <div className="bg-white rounded-2xl shadow-2xl p-8 w-full max-w-md text-center">
          <BeakerIcon className="w-16 h-16 text-indigo-600 mx-auto mb-4" />
          <h1 className="text-3xl font-bold text-slate-800 mb-2">ReagentFlow</h1>
          <p className="text-slate-500 mb-8">Control Inteligente de Inventario para Laboratorios</p>

          <div className="space-y-4">
            <button 
              onClick={() => setRole('ANALISTA')}
              className="w-full bg-white border-2 border-slate-200 hover:border-indigo-600 hover:text-indigo-600 text-slate-700 font-semibold py-4 px-6 rounded-xl transition-all flex items-center justify-between group"
            >
              <div className="flex items-center gap-3">
                <QueueListIcon className="w-6 h-6" />
                <span>Entrar como Analista</span>
              </div>
              <ChevronRightIcon className="w-5 h-5 opacity-0 group-hover:opacity-100 transition-opacity" />
            </button>

            <button 
              onClick={() => setShowAuthModal(true)}
              className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-semibold py-4 px-6 rounded-xl transition-all flex items-center justify-between group shadow-lg"
            >
              <div className="flex items-center gap-3">
                <BellAlertIcon className="w-6 h-6" />
                <span>Entrar como Gerente</span>
              </div>
              <ChevronRightIcon className="w-5 h-5 opacity-50 group-hover:opacity-100 transition-opacity" />
            </button>
          </div>

          <div className="mt-8 text-xs text-slate-400">
            v1.2.0 &bull; Powered by Gemini AI
          </div>
        </div>

        {/* Auth Modal */}
        {showAuthModal && (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300">
            <div className="bg-white rounded-2xl shadow-2xl w-full max-w-sm overflow-hidden animate-in zoom-in-95 duration-200">
              <div className="bg-slate-50 p-6 border-b border-slate-100 flex items-center gap-3">
                <div className="bg-indigo-100 p-2 rounded-lg">
                  <LockClosedIcon className="w-6 h-6 text-indigo-600" />
                </div>
                <div>
                  <h3 className="font-bold text-slate-800">
                    {storedPassword ? 'Acceso de Gerencia' : 'Configurar Acceso'}
                  </h3>
                  <p className="text-xs text-slate-500">
                    {storedPassword ? 'Ingrese su contraseña maestra' : 'Cree una contraseña para el rol de Gerente'}
                  </p>
                </div>
              </div>
              <form onSubmit={handleAuthSubmit} className="p-6 space-y-4">
                <div className="relative">
                  <input 
                    autoFocus
                    type={showPassword ? "text" : "password"}
                    placeholder={storedPassword ? "Contraseña" : "Nueva contraseña"}
                    className={`w-full pl-4 pr-12 py-3 border rounded-xl outline-none focus:ring-2 transition-all ${authError ? 'border-red-500 focus:ring-red-200' : 'border-slate-200 focus:ring-indigo-200'}`}
                    value={authInput}
                    onChange={(e) => {
                      setAuthInput(e.target.value);
                      if (authError) setAuthError('');
                    }}
                  />
                  <button 
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600"
                  >
                    {showPassword ? <EyeSlashIcon className="w-5 h-5" /> : <EyeIcon className="w-5 h-5" />}
                  </button>
                </div>
                {authError && <p className="text-red-600 text-xs font-medium pl-1">{authError}</p>}
                <div className="flex gap-3 pt-2">
                  <button 
                    type="button"
                    onClick={() => {
                      setShowAuthModal(false);
                      setAuthInput('');
                      setAuthError('');
                    }}
                    className="flex-1 px-4 py-3 text-slate-500 font-semibold hover:bg-slate-100 rounded-xl transition-colors"
                  >
                    Cancelar
                  </button>
                  <button 
                    type="submit"
                    className="flex-[2] bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 rounded-xl shadow-lg transition-all"
                  >
                    {storedPassword ? 'Ingresar' : 'Guardar y Entrar'}
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}
      </div>
    );
  }

  return (
    <Router>
      <div className="flex flex-col min-h-screen bg-slate-50">
        {/* Navigation */}
        <nav className="bg-white border-b border-slate-200 sticky top-0 z-30 shadow-sm">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex justify-between h-16">
              <div className="flex items-center gap-2">
                <BeakerIcon className="h-8 w-8 text-indigo-600" />
                <span className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-indigo-600 to-blue-500 hidden sm:block">ReagentFlow</span>
              </div>

              <div className="flex items-center gap-4">
                <div className="hidden md:flex items-center gap-6 mr-6">
                  <Link to="/" className="text-slate-600 hover:text-indigo-600 font-medium">Inventario</Link>
                  <Link to="/ingreso" className="text-slate-600 hover:text-indigo-600 font-medium">Ingresos</Link>
                  <Link to="/salida" className="text-slate-600 hover:text-indigo-600 font-medium">Salidas</Link>
                  <Link to="/historial" className="text-slate-600 hover:text-indigo-600 font-medium">Historial</Link>
                  {role === 'GERENTE' && (
                    <Link to="/alertas" className="flex items-center gap-1 text-slate-600 hover:text-red-600 font-medium">
                      Alertas
                      {reagents.filter(r => r.currentStock <= r.minStock && !r.isOrdered).length > 0 && (
                        <span className="bg-red-500 text-white text-[10px] px-1.5 py-0.5 rounded-full">
                          {reagents.filter(r => r.currentStock <= r.minStock && !r.isOrdered).length}
                        </span>
                      )}
                    </Link>
                  )}
                </div>

                <div className="flex items-center gap-2 bg-slate-100 px-3 py-1.5 rounded-full">
                  <UserCircleIcon className="w-5 h-5 text-slate-500" />
                  <span className="text-sm font-semibold text-slate-700">{role}</span>
                </div>

                <button 
                  onClick={() => setRole(null)}
                  className="p-2 text-slate-400 hover:text-red-600 transition-colors"
                  title="Salir"
                >
                  <ArrowRightOnRectangleIcon className="w-6 h-6" />
                </button>
              </div>
            </div>
          </div>
        </nav>

        {/* Mobile Nav */}
        <div className="md:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-slate-200 z-50 flex justify-around py-3">
          <Link to="/" className="flex flex-col items-center text-slate-400 active:text-indigo-600">
            <HomeIcon className="w-6 h-6" />
            <span className="text-[10px] mt-1">Inicio</span>
          </Link>
          <Link to="/ingreso" className="flex flex-col items-center text-slate-400 active:text-indigo-600">
            <PlusCircleIcon className="w-6 h-6" />
            <span className="text-[10px] mt-1">Ingreso</span>
          </Link>
          <Link to="/salida" className="flex flex-col items-center text-slate-400 active:text-indigo-600">
            <MinusCircleIcon className="w-6 h-6" />
            <span className="text-[10px] mt-1">Salida</span>
          </Link>
          <Link to="/historial" className="flex flex-col items-center text-slate-400 active:text-indigo-600">
            <QueueListIcon className="w-6 h-6" />
            <span className="text-[10px] mt-1">Historial</span>
          </Link>
          {role === 'GERENTE' && (
            <Link to="/alertas" className="flex flex-col items-center text-slate-400 active:text-indigo-600">
              <BellAlertIcon className="w-6 h-6" />
              <span className="text-[10px] mt-1">Alertas</span>
            </Link>
          )}
        </div>

        <main className="flex-grow max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 mb-20 md:mb-8">
          <Routes>
            <Route path="/" element={<InventoryView reagents={reagents} />} />
            <Route path="/ingreso" element={<InputForm reagents={reagents} onTransaction={handleTransaction} transactions={transactions} />} />
            <Route path="/salida" element={<OutputForm reagents={reagents} onTransaction={handleTransaction} />} />
            <Route path="/historial" element={<HistoryView transactions={transactions} />} />
            <Route 
              path="/alertas" 
              element={role === 'GERENTE' ? (
                <AlertsView 
                  reagents={reagents} 
                  markAsOrdered={markAsOrdered} 
                  onUpdateMinStock={updateMinStock}
                />
              ) : (
                <Navigate to="/" />
              )} 
            />
          </Routes>
        </main>
      </div>
    </Router>
  );
};

export default App;

export type Presentation = 'Líquido' | 'Sólido' | 'Paquete';
export type Department = 'Fisicoquímico' | 'Microbiología' | 'Molecular';
export type UserRole = 'ANALISTA' | 'GERENTE';
export type TransactionType = 'IN' | 'OUT';

export interface Reagent {
  id: string;
  name: string;
  brand: string;
  presentation: Presentation;
  currentStock: number; // Total in baseUnit
  minStock: number; // Total in baseUnit
  department: Department;
  baseUnit: string; // e.g., 'mL', 'L', 'g', 'kg', 'unidades'
  containerType: string; // e.g., 'Frascos', 'Botellas', 'Sobres', 'N/A'
  quantityPerContainer: number; // e.g., 500 (if 500mL per bottle)
  expiryDate: string; // ISO string or "N/A"
  isOrdered: boolean;
  lastUpdated: string;
}

export interface Transaction {
  id: string;
  reagentId: string;
  reagentName: string;
  type: TransactionType;
  quantity: number; // amount in baseUnit
  displayQuantity: number; // amount as entered (e.g., 10 bottles)
  displayUnit: string; // unit as entered (e.g., 'Frascos')
  analyst: string;
  timestamp: string;
}

export interface AIAnalysisResult {
  name: string;
  brand: string;
  presentation: Presentation;
}

import React, { useState, useRef, useMemo } from 'react';
import { Reagent, Presentation, Department, Transaction } from '../types';
import { analyzeReagentLabel } from '../services/geminiService';
import { fileToBase64, generateId } from '../utils';
import { 
  CameraIcon, 
  SparklesIcon, 
  ArrowPathIcon,
  PlusIcon
} from '@heroicons/react/24/solid';

interface Props {
  reagents: Reagent[];
  transactions: Transaction[];
  onTransaction: (reagent: Partial<Reagent>, data: any) => void;
}

const BASE_UNITS_LIQUID = ['mL', 'L'];
const BASE_UNITS_SOLID = ['g', 'kg'];
const BASE_UNITS_PKG = ['unidades'];

const InputForm: React.FC<Props> = ({ reagents, transactions, onTransaction }) => {
  const [loading, setLoading] = useState(false);
  const [isExisting, setIsExisting] = useState(false);
  const [selectedReagentId, setSelectedReagentId] = useState('');
  const [showNewUnitInput, setShowNewUnitInput] = useState(false);
  const [customUnit, setCustomUnit] = useState('');

  // Form State
  const [formData, setFormData] = useState({
    name: '',
    brand: '',
    presentation: 'Líquido' as Presentation,
    containerType: 'Frascos',
    quantityEntered: 0, // e.g. 10
    quantityPerContainer: 1, // e.g. 500
    baseUnit: 'mL',
    expiryDate: '',
    department: 'Fisicoquímico' as Department,
    analystName: '',
    minStock: 0
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  const unitsForPresentation = useMemo(() => {
    if (formData.presentation === 'Líquido') return BASE_UNITS_LIQUID;
    if (formData.presentation === 'Sólido') return BASE_UNITS_SOLID;
    return BASE_UNITS_PKG;
  }, [formData.presentation]);

  const totalBaseQuantity = useMemo(() => {
    return formData.quantityEntered * formData.quantityPerContainer;
  }, [formData.quantityEntered, formData.quantityPerContainer]);

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    try {
      const base64 = await fileToBase64(file);
      const analysis = await analyzeReagentLabel(base64);

      const newBaseUnit = analysis.presentation === 'Líquido' ? 'mL' : (analysis.presentation === 'Sólido' ? 'g' : 'unidades');

      setFormData(prev => ({
        ...prev,
        name: analysis.name || '',
        brand: analysis.brand || '',
        presentation: analysis.presentation || 'Líquido',
        baseUnit: newBaseUnit
      }));

      const existing = reagents.find(r => 
        r.name.toLowerCase() === analysis.name.toLowerCase() && 
        r.brand.toLowerCase() === analysis.brand.toLowerCase()
      );

      if (existing) {
        setIsExisting(true);
        setSelectedReagentId(existing.id);
        setFormData(prev => ({ 
          ...prev, 
          baseUnit: existing.baseUnit, 
          containerType: existing.containerType,
          quantityPerContainer: existing.quantityPerContainer,
          minStock: existing.minStock 
        }));
      } else {
        setIsExisting(false);
      }
    } catch (error) {
      alert("Error analizando la etiqueta.");
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    const finalBaseUnit = showNewUnitInput ? customUnit : formData.baseUnit;

    onTransaction(
      {
        id: isExisting ? selectedReagentId : undefined,
        name: formData.name,
        brand: formData.brand,
        presentation: formData.presentation,
        department: formData.department,
        expiryDate: formData.expiryDate || 'N/A',
        minStock: formData.minStock,
        containerType: formData.containerType,
        quantityPerContainer: formData.quantityPerContainer,
        baseUnit: finalBaseUnit
      },
      {
        reagentId: isExisting ? selectedReagentId : undefined,
        type: 'IN',
        quantity: totalBaseQuantity,
        displayQuantity: formData.quantityEntered,
        displayUnit: formData.containerType,
        analyst: formData.analystName
      }
    );

    // Reset
    setFormData({
      name: '', brand: '', presentation: 'Líquido', containerType: 'Frascos',
      quantityEntered: 0, quantityPerContainer: 1, baseUnit: 'mL', 
      expiryDate: '', department: 'Fisicoquímico', analystName: '', minStock: 0
    });
    setIsExisting(false);
    setSelectedReagentId('');
    setShowNewUnitInput(false);
    setCustomUnit('');
    alert("Ingreso registrado exitosamente.");
  };

  return (
    <div className="max-w-3xl mx-auto">
      <div className="bg-white rounded-2xl shadow-xl border border-slate-200 overflow-hidden">
        <div className="bg-indigo-600 p-6 text-white flex justify-between items-center">
          <div>
            <h2 className="text-xl font-bold">Registro de Ingreso Detallado</h2>
            <p className="text-indigo-100 text-sm">Control exacto por volumen/peso.</p>
          </div>
          <SparklesIcon className="w-8 h-8 opacity-50" />
        </div>

        <div className="p-8">
          <div className="flex flex-wrap gap-4 mb-8">
            <button 
              type="button"
              onClick={() => fileInputRef.current?.click()}
              disabled={loading}
              className="flex-1 flex items-center justify-center gap-2 bg-indigo-50 hover:bg-indigo-100 text-indigo-700 py-3 px-4 rounded-xl border border-indigo-200 font-semibold transition-all"
            >
              {loading ? <ArrowPathIcon className="w-5 h-5 animate-spin" /> : <CameraIcon className="w-5 h-5" />}
              {loading ? "Analizando..." : "Escanear Etiqueta (AI)"}
            </button>
            <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleImageUpload} />

            <select 
              className="flex-1 bg-slate-50 border border-slate-200 py-3 px-4 rounded-xl text-slate-700 font-medium outline-none"
              value={isExisting ? selectedReagentId : 'new'}
              onChange={(e) => {
                const val = e.target.value;
                if (val === 'new') {
                  setIsExisting(false);
                  setSelectedReagentId('');
                } else {
                  setIsExisting(true);
                  const r = reagents.find(x => x.id === val);
                  if(r) {
                    setSelectedReagentId(val);
                    setFormData(prev => ({
                      ...prev, name: r.name, brand: r.brand, presentation: r.presentation,
                      baseUnit: r.baseUnit, containerType: r.containerType, 
                      quantityPerContainer: r.quantityPerContainer, minStock: r.minStock
                    }));
                  }
                }
              }}
            >
              <option value="new">+ Nuevo Reactivo</option>
              {reagents.map(r => <option key={r.id} value={r.id}>{r.name} - {r.brand}</option>)}
            </select>
          </div>

          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-sm font-semibold text-slate-700">Nombre del Reactivo</label>
                <input type="text" required disabled={isExisting} className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500 disabled:bg-slate-100" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
              </div>
              <div className="space-y-2">
                <label className="text-sm font-semibold text-slate-700">Marca</label>
                <input type="text" required disabled={isExisting} className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500 disabled:bg-slate-100" value={formData.brand} onChange={e => setFormData({...formData, brand: e.target.value})} />
              </div>

              <div className="space-y-2">
                <label className="text-sm font-semibold text-slate-700">Presentación</label>
                <select disabled={isExisting} className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500 disabled:bg-slate-100" value={formData.presentation} onChange={e => setFormData({...formData, presentation: e.target.value as Presentation})}>
                  <option value="Líquido">Líquido</option>
                  <option value="Sólido">Sólido</option>
                  <option value="Paquete">Paquete</option>
                </select>
              </div>

              <div className="space-y-2">
                <label className="text-sm font-semibold text-slate-700">Tipo de Envase</label>
                <input type="text" required placeholder="Frascos, Botellas, etc." className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500" value={formData.containerType} onChange={e => setFormData({...formData, containerType: e.target.value})} />
              </div>

              <div className="space-y-2">
                <label className="text-sm font-semibold text-slate-700">¿Cuántos {formData.containerType}?</label>
                <input type="number" required min="1" className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500" value={formData.quantityEntered || ''} onChange={e => setFormData({...formData, quantityEntered: parseInt(e.target.value) || 0})} />
              </div>

              <div className="space-y-2">
                <label className="text-sm font-semibold text-slate-700">Contenido por {formData.containerType}</label>
                <div className="flex gap-2">
