import React, { useState, useRef, useMemo } from 'react';
import { Reagent, Transaction } from '../types';
import { analyzeReagentLabel } from '../services/geminiService';
import { fileToBase64 } from '../utils';
import { 
  CameraIcon, 
  ArrowPathIcon,
  MinusCircleIcon,
  ExclamationTriangleIcon
} from '@heroicons/react/24/solid';

interface Props {
  reagents: Reagent[];
  onTransaction: (reagent: Partial<Reagent>, data: any) => void;
}

const OutputForm: React.FC<Props> = ({ reagents, onTransaction }) => {
  const [loading, setLoading] = useState(false);
  const [selectedReagentId, setSelectedReagentId] = useState('');
  const [outputMode, setOutputMode] = useState<'CONTAINER' | 'QUANTITY'>('CONTAINER');
  const [formData, setFormData] = useState({
    containers: 0,
    amount: 0,
    analystName: '',
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  const selectedReagent = useMemo(() => reagents.find(r => r.id === selectedReagentId), [reagents, selectedReagentId]);

  const totalAmountToWithdraw = useMemo(() => {
    if (!selectedReagent) return 0;
    return outputMode === 'CONTAINER' 
      ? formData.containers * selectedReagent.quantityPerContainer 
      : formData.amount;
  }, [outputMode, formData, selectedReagent]);

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setLoading(true);
    try {
      const base64 = await fileToBase64(file);
      const analysis = await analyzeReagentLabel(base64);
      const found = reagents.find(r => r.name.toLowerCase().includes(analysis.name.toLowerCase()) || analysis.name.toLowerCase().includes(r.name.toLowerCase()));
      if (found) setSelectedReagentId(found.id);
      else alert("Reactivo no encontrado.");
    } catch (error) { alert("Error al analizar."); } finally { setLoading(false); }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedReagent) return;
    if (totalAmountToWithdraw > selectedReagent.currentStock) {
      alert("No hay suficiente stock.");
      return;
    }

    onTransaction({}, {
      reagentId: selectedReagentId,
      type: 'OUT',
      quantity: totalAmountToWithdraw,
      displayQuantity: outputMode === 'CONTAINER' ? formData.containers : formData.amount,
      displayUnit: outputMode === 'CONTAINER' ? selectedReagent.containerType : selectedReagent.baseUnit,
      analyst: formData.analystName
    });

    setSelectedReagentId('');
    setFormData({ containers: 0, amount: 0, analystName: '' });
    alert("Salida registrada.");
  };

  return (
    <div className="max-w-3xl mx-auto">
      <div className="bg-white rounded-2xl shadow-xl border border-slate-200 overflow-hidden">
        <div className="bg-rose-600 p-6 text-white flex justify-between items-center">
          <div>
            <h2 className="text-xl font-bold">Registro de Consumo Exacto</h2>
            <p className="text-rose-100 text-sm">Descuento por unidades o cantidad parcial.</p>
          </div>
          <MinusCircleIcon className="w-8 h-8 opacity-50" />
        </div>

        <div className="p-8">
          <div className="flex flex-wrap gap-4 mb-8">
            <button type="button" onClick={() => fileInputRef.current?.click()} disabled={loading} className="flex-1 flex items-center justify-center gap-2 bg-rose-50 hover:bg-rose-100 text-rose-700 py-3 px-4 rounded-xl border border-rose-200 font-semibold transition-all">
              {loading ? <ArrowPathIcon className="w-5 h-5 animate-spin" /> : <CameraIcon className="w-5 h-5" />}
              {loading ? "Reconociendo..." : "Foto del Envase"}
            </button>
            <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleImageUpload} />

            <div className="flex-1">
              <select className="w-full bg-slate-50 border border-slate-200 py-3 px-4 rounded-xl text-slate-700 font-medium outline-none" value={selectedReagentId} onChange={(e) => setSelectedReagentId(e.target.value)}>
                <option value="">-- Seleccionar Reactivo --</option>
                {reagents.map(r => <option key={r.id} value={r.id}>{r.name} ({r.currentStock} {r.baseUnit} disponibles)</option>)}
              </select>
            </div>
          </div>

          {selectedReagent && (
            <form onSubmit={handleSubmit} className="space-y-6">
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4 p-4 bg-slate-50 rounded-xl border border-slate-200">
                <div className="text-center">
                  <p className="text-[10px] uppercase text-slate-400 font-bold">Total Stock</p>
                  <p className="font-bold text-slate-800">{selectedReagent.currentStock} {selectedReagent.baseUnit}</p>
                </div>
                <div className="text-center border-l border-slate-200">
                  <p className="text-[10px] uppercase text-slate-400 font-bold">Contenedor</p>
                  <p className="font-bold text-slate-800">{selectedReagent.containerType}</p>
                </div>
                <div className="text-center border-l border-slate-200">
                  <p className="text-[10px] uppercase text-slate-400 font-bold">Contenido</p>
                  <p className="font-bold text-slate-800">{selectedReagent.quantityPerContainer} {selectedReagent.baseUnit}</p>
                </div>
                <div className="text-center border-l border-slate-200">
                  <p className="text-[10px] uppercase text-slate-400 font-bold">Estimado</p>
                  <p className="font-bold text-indigo-600">{(selectedReagent.currentStock / selectedReagent.quantityPerContainer).toFixed(1)} ud.</p>
                </div>
              </div>

              <div className="flex bg-slate-100 p-1 rounded-xl">
                 <button type="button" onClick={() => setOutputMode('CONTAINER')} className={`flex-1 py-2 rounded-lg text-sm font-bold transition-all ${outputMode === 'CONTAINER' ? 'bg-white shadow text-indigo-600' : 'text-slate-500'}`}>Por {selectedReagent.containerType}</button>
                 <button type="button" onClick={() => setOutputMode('QUANTITY')} className={`flex-1 py-2 rounded-lg text-sm font-bold transition-all ${outputMode === 'QUANTITY' ? 'bg-white shadow text-indigo-600' : 'text-slate-500'}`}>Por Cantidad Exacta</button>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-sm font-semibold text-slate-700">Cantidad a retirar</label>
                  <div className="relative">
                    {outputMode === 'CONTAINER' ? (
                      <input type="number" required min="1" className="w-full pl-4 pr-24 py-3 border rounded-lg focus:ring-2 focus:ring-rose-500" value={formData.containers || ''} onChange={e => setFormData({...formData, containers: parseInt(e.target.value) || 0})} />
                    ) : (
                      <input type="number" required step="0.01" min="0.01" className="w-full pl-4 pr-24 py-3 border rounded-lg focus:ring-2 focus:ring-rose-500" value={formData.amount || ''} onChange={e => setFormData({...formData, amount: parseFloat(e.target.value) || 0})} />
                    )}
                    <span className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 font-bold">
                      {outputMode === 'CONTAINER' ? selectedReagent.containerType : selectedReagent.baseUnit}
                    </span>
                  </div>
                  <p className="text-[10px] text-slate-400">Total equivalente: {totalAmountToWithdraw} {selectedReagent.baseUnit}</p>
                </div>

                <div className="space-y-2">
                  <label className="text-sm font-semibold text-slate-700">Analista</label>
                  <input type="text" required placeholder="Tu nombre" className="w-full px-4 py-3 border rounded-lg focus:ring-2 focus:ring-rose-500" value={formData.analystName} onChange={e => setFormData({...formData, analystName: e.target.value})} />
                </div>
              </div>

              {selectedReagent.currentStock - totalAmountToWithdraw <= selectedReagent.minStock && (
                <div className="bg-amber-50 p-4 rounded-xl border border-amber-200 flex gap-3"><ExclamationTriangleIcon className="w-6 h-6 text-amber-500 shrink-0" /><p className="text-sm text-amber-700">Stock crítico detectado después de esta operación.</p></div>
              )}

              <button type="submit" className="w-full bg-rose-600 hover:bg-rose-700 text-white font-bold py-4 rounded-xl shadow-lg transition-all active:scale-[0.98]">Registrar Salida</button>
            </form>
          )}
        </div>
      </div>
    </div>
  );
};

export default OutputForm;

