import React, { useState, useRef, useMemo } from 'react';
import { Reagent, Presentation, Department, Transaction } from '../types';
import { analyzeReagentLabel } from '../services/geminiService';
import { fileToBase64, generateId } from '../utils';
import { 
  CameraIcon, 
  SparklesIcon, 
  ArrowPathIcon,
  PlusIcon
} from '@heroicons/react/24/solid';

interface Props {
  reagents: Reagent[];
  transactions: Transaction[];
  onTransaction: (reagent: Partial<Reagent>, data: any) => void;
}

const BASE_UNITS_LIQUID = ['mL', 'L'];
const BASE_UNITS_SOLID = ['g', 'kg'];
const BASE_UNITS_PKG = ['unidades'];

const InputForm: React.FC<Props> = ({ reagents, transactions, onTransaction }) => {
  const [loading, setLoading] = useState(false);
  const [isExisting, setIsExisting] = useState(false);
  const [selectedReagentId, setSelectedReagentId] = useState('');
  const [showNewUnitInput, setShowNewUnitInput] = useState(false);
  const [customUnit, setCustomUnit] = useState('');

  // Form State
  const [formData, setFormData] = useState({
    name: '',
    brand: '',
    presentation: 'Líquido' as Presentation,
    containerType: 'Frascos',
    quantityEntered: 0, // e.g. 10
    quantityPerContainer: 1, // e.g. 500
    baseUnit: 'mL',
    expiryDate: '',
    department: 'Fisicoquímico' as Department,
    analystName: '',
    minStock: 0
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  const unitsForPresentation = useMemo(() => {
    if (formData.presentation === 'Líquido') return BASE_UNITS_LIQUID;
    if (formData.presentation === 'Sólido') return BASE_UNITS_SOLID;
    return BASE_UNITS_PKG;
  }, [formData.presentation]);

  const totalBaseQuantity = useMemo(() => {
    return formData.quantityEntered * formData.quantityPerContainer;
  }, [formData.quantityEntered, formData.quantityPerContainer]);

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    try {
      const base64 = await fileToBase64(file);
      const analysis = await analyzeReagentLabel(base64);

      const newBaseUnit = analysis.presentation === 'Líquido' ? 'mL' : (analysis.presentation === 'Sólido' ? 'g' : 'unidades');

      setFormData(prev => ({
        ...prev,
        name: analysis.name || '',
        brand: analysis.brand || '',
        presentation: analysis.presentation || 'Líquido',
        baseUnit: newBaseUnit
      }));

      const existing = reagents.find(r => 
        r.name.toLowerCase() === analysis.name.toLowerCase() && 
        r.brand.toLowerCase() === analysis.brand.toLowerCase()
      );

      if (existing) {
        setIsExisting(true);
        setSelectedReagentId(existing.id);
        setFormData(prev => ({ 
          ...prev, 
          baseUnit: existing.baseUnit, 
          containerType: existing.containerType,
          quantityPerContainer: existing.quantityPerContainer,
          minStock: existing.minStock 
        }));
      } else {
        setIsExisting(false);
      }
    } catch (error) {
      alert("Error analizando la etiqueta.");
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    const finalBaseUnit = showNewUnitInput ? customUnit : formData.baseUnit;

    onTransaction(
      {
        id: isExisting ? selectedReagentId : undefined,
        name: formData.name,
        brand: formData.brand,
        presentation: formData.presentation,
        department: formData.department,
        expiryDate: formData.expiryDate || 'N/A',
        minStock: formData.minStock,
        containerType: formData.containerType,
        quantityPerContainer: formData.quantityPerContainer,
        baseUnit: finalBaseUnit
      },
      {
        reagentId: isExisting ? selectedReagentId : undefined,
        type: 'IN',
        quantity: totalBaseQuantity,
        displayQuantity: formData.quantityEntered,
        displayUnit: formData.containerType,
        analyst: formData.analystName
      }
    );

    // Reset
    setFormData({
      name: '', brand: '', presentation: 'Líquido', containerType: 'Frascos',
      quantityEntered: 0, quantityPerContainer: 1, baseUnit: 'mL', 
      expiryDate: '', department: 'Fisicoquímico', analystName: '', minStock: 0
    });
    setIsExisting(false);
    setSelectedReagentId('');
    setShowNewUnitInput(false);
    setCustomUnit('');
    alert("Ingreso registrado exitosamente.");
  };

  return (
    <div className="max-w-3xl mx-auto">
      <div className="bg-white rounded-2xl shadow-xl border border-slate-200 overflow-hidden">
        <div className="bg-indigo-600 p-6 text-white flex justify-between items-center">
          <div>
            <h2 className="text-xl font-bold">Registro de Ingreso Detallado</h2>
            <p className="text-indigo-100 text-sm">Control exacto por volumen/peso.</p>
          </div>
          <SparklesIcon className="w-8 h-8 opacity-50" />
        </div>

        <div className="p-8">
          <div className="flex flex-wrap gap-4 mb-8">
            <button 
              type="button"
              onClick={() => fileInputRef.current?.click()}
              disabled={loading}
              className="flex-1 flex items-center justify-center gap-2 bg-indigo-50 hover:bg-indigo-100 text-indigo-700 py-3 px-4 rounded-xl border border-indigo-200 font-semibold transition-all"
            >
              {loading ? <ArrowPathIcon className="w-5 h-5 animate-spin" /> : <CameraIcon className="w-5 h-5" />}
              {loading ? "Analizando..." : "Escanear Etiqueta (AI)"}
            </button>
            <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleImageUpload} />

            <select 
              className="flex-1 bg-slate-50 border border-slate-200 py-3 px-4 rounded-xl text-slate-700 font-medium outline-none"
              value={isExisting ? selectedReagentId : 'new'}
              onChange={(e) => {
                const val = e.target.value;
                if (val === 'new') {
                  setIsExisting(false);
                  setSelectedReagentId('');
                } else {
                  setIsExisting(true);
                  const r = reagents.find(x => x.id === val);
                  if(r) {
                    setSelectedReagentId(val);
                    setFormData(prev => ({
                      ...prev, name: r.name, brand: r.brand, presentation: r.presentation,
                      baseUnit: r.baseUnit, containerType: r.containerType, 
                      quantityPerContainer: r.quantityPerContainer, minStock: r.minStock
                    }));
                  }
                }
              }}
            >
              <option value="new">+ Nuevo Reactivo</option>
              {reagents.map(r => <option key={r.id} value={r.id}>{r.name} - {r.brand}</option>)}
            </select>
          </div>

          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-sm font-semibold text-slate-700">Nombre del Reactivo</label>
                <input type="text" required disabled={isExisting} className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500 disabled:bg-slate-100" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
              </div>
              <div className="space-y-2">
                <label className="text-sm font-semibold text-slate-700">Marca</label>
                <input type="text" required disabled={isExisting} className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500 disabled:bg-slate-100" value={formData.brand} onChange={e => setFormData({...formData, brand: e.target.value})} />
              </div>

              <div className="space-y-2">
                <label className="text-sm font-semibold text-slate-700">Presentación</label>
                <select disabled={isExisting} className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500 disabled:bg-slate-100" value={formData.presentation} onChange={e => setFormData({...formData, presentation: e.target.value as Presentation})}>
                  <option value="Líquido">Líquido</option>
                  <option value="Sólido">Sólido</option>
                  <option value="Paquete">Paquete</option>
                </select>
              </div>

              <div className="space-y-2">
                <label className="text-sm font-semibold text-slate-700">Tipo de Envase</label>
                <input type="text" required placeholder="Frascos, Botellas, etc." className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500" value={formData.containerType} onChange={e => setFormData({...formData, containerType: e.target.value})} />
              </div>

              <div className="space-y-2">
                <label className="text-sm font-semibold text-slate-700">¿Cuántos {formData.containerType}?</label>
                <input type="number" required min="1" className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500" value={formData.quantityEntered || ''} onChange={e => setFormData({...formData, quantityEntered: parseInt(e.target.value) || 0})} />
              </div>

              <div className="space-y-2">
                <label className="text-sm font-semibold text-slate-700">Contenido por {formData.containerType}</label>
                <div className="flex gap-2">
                  <input type="number" required step="0.01" className="flex-grow px-4 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500" value={formData.quantityPerContainer || ''} onChange={e => setFormData({...formData, quantityPerContainer: parseFloat(e.target.value) || 0})} />
                  {!showNewUnitInput ? (
                    <select className="w-28 px-2 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500" value={formData.baseUnit} onChange={e => {
                      if(e.target.value === 'ADD_NEW') setShowNewUnitInput(true);
                      else setFormData({...formData, baseUnit: e.target.value});
                    }}>
                      {unitsForPresentation.map(u => <option key={u} value={u}>{u}</option>)}
                      <option value="ADD_NEW">+ Nueva</option>
                    </select>
                  ) : (
                    <div className="flex items-center gap-1 w-28">
                       <input type="text" placeholder="Ud." className="w-full px-2 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500" value={customUnit} onChange={e => setCustomUnit(e.target.value)} />
                       <button type="button" onClick={() => setShowNewUnitInput(false)} className="text-red-500">×</button>
                    </div>
                  )}
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-sm font-semibold text-slate-700">Stock Mínimo ({showNewUnitInput ? customUnit : formData.baseUnit})</label>
                <input 
                  type="number" 
                  required 
                  min="0" 
                  step="0.01"
                  className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500" 
                  value={formData.minStock || ''} 
                  onChange={e => setFormData({...formData, minStock: parseFloat(e.target.value) || 0})} 
                />
              </div>

              <div className="space-y-2">
                <label className="text-sm font-semibold text-slate-700">Vencimiento</label>
                <input type="date" className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500" value={formData.expiryDate} onChange={e => setFormData({...formData, expiryDate: e.target.value})} />
              </div>

              <div className="space-y-2">
                <label className="text-sm font-semibold text-slate-700">Departamento</label>
                <select className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500" value={formData.department} onChange={e => setFormData({...formData, department: e.target.value as Department})}>
                  <option value="Fisicoquímico">Fisicoquímico</option>
                  <option value="Microbiología">Microbiología</option>
                  <option value="Molecular">Molecular</option>
                </select>
              </div>

              <div className="space-y-2 md:col-span-1">
                <label className="text-sm font-semibold text-slate-700">Analista Responsable</label>
                <input type="text" required className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500" value={formData.analystName} onChange={e => setFormData({...formData, analystName: e.target.value})} />
              </div>
            </div>

            <div className="bg-slate-50 p-4 rounded-xl border border-slate-200">
               <div className="flex justify-between items-center">
                  <span className="text-slate-500 text-sm">Total a ingresar al inventario:</span>
                  <span className="font-bold text-indigo-600 text-lg">{totalBaseQuantity} {showNewUnitInput ? customUnit : formData.baseUnit}</span>
               </div>
            </div>

            <button type="submit" className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-4 rounded-xl shadow-lg transition-all active:scale-[0.98]">
              Confirmar Ingreso Exacto
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

export default InputForm;

import React, { useMemo } from 'react';
import { Reagent } from '../types';
import { 
  BellAlertIcon, 
  ShoppingBagIcon, 
  CheckCircleIcon,
  ExclamationCircleIcon
} from '@heroicons/react/24/solid';

interface Props {
  reagents: Reagent[];
  markAsOrdered: (id: string) => void;
  onUpdateMinStock: (id: string, newMin: number) => void;
}

const AlertsView: React.FC<Props> = ({ reagents, markAsOrdered, onUpdateMinStock }) => {
  const lowStockReagents = useMemo(() => {
    return reagents.filter(r => r.currentStock <= r.minStock && !r.isOrdered);
  }, [reagents]);

  const orderedReagents = useMemo(() => {
    return reagents.filter(r => r.isOrdered);
  }, [reagents]);

  return (
    <div className="space-y-10">
      <div className="bg-red-50 border-l-4 border-red-500 p-6 rounded-r-xl">
        <div className="flex items-center gap-3 mb-2">
          <BellAlertIcon className="w-8 h-8 text-red-600" />
          <h1 className="text-2xl font-bold text-red-900">Panel de Alertas de Stock</h1>
        </div>
        <p className="text-red-700 font-medium">Estos reactivos necesitan reposición inmediata para evitar interrupciones en el laboratorio.</p>
      </div>

      <div className="space-y-6">
        <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2">
          <ExclamationCircleIcon className="w-5 h-5 text-red-600" />
          Necesitan Pedido ({lowStockReagents.length})
        </h2>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {lowStockReagents.length > 0 ? (
            lowStockReagents.map(r => (
              <div key={r.id} className="bg-white rounded-2xl shadow-md border border-red-100 overflow-hidden group">
                <div className="p-5">
                  <div className="flex justify-between items-start mb-4">
                    <div>
                      <h3 className="font-bold text-slate-800 text-lg">{r.name}</h3>
                      <p className="text-xs text-slate-500 uppercase tracking-widest">{r.brand}</p>
                    </div>
                    <span className="bg-red-100 text-red-700 text-[10px] font-bold px-2 py-1 rounded-full uppercase">Crítico</span>
                  </div>

                  <div className="space-y-3 mb-6">
                    <div className="flex justify-between text-sm">
                      <span className="text-slate-500">Stock Actual:</span>
                      <span className="font-bold text-red-600">{r.currentStock} {r.baseUnit}</span>
                    </div>
                    <div className="flex justify-between text-sm">
                      <span className="text-slate-500">Stock Mínimo:</span>
                      <div className="flex items-center gap-2">
                        <input 
                          type="number" 
                          className="w-16 border-b border-slate-200 text-right focus:border-indigo-500 outline-none"
                          value={r.minStock}
                          onChange={(e) => onUpdateMinStock(r.id, parseFloat(e.target.value))}
                        />
                        <span className="text-slate-500">{r.baseUnit}</span>
                      </div>
                    </div>
                    <div className="h-1.5 w-full bg-slate-100 rounded-full overflow-hidden">
                      <div 
                        className="h-full bg-red-500" 
                        style={{ width: `${Math.min(100, (r.currentStock / r.minStock) * 100)}%` }}
                      ></div>
                    </div>
                  </div>

                  <button 
                    onClick={() => markAsOrdered(r.id)}
                    className="w-full flex items-center justify-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 rounded-xl transition-all shadow-indigo-200 shadow-lg"
                  >
                    <ShoppingBagIcon className="w-5 h-5" />
                    Marcar como Pedido
                  </button>
                </div>
                <div className="bg-slate-50 px-5 py-3 text-[10px] text-slate-400 font-medium">
                  ÚLTIMO MOVIMIENTO: {new Date(r.lastUpdated).toLocaleDateString()}
                </div>
              </div>
            ))
          ) : (
            <div className="col-span-full py-12 text-center bg-emerald-50 rounded-2xl border border-emerald-100">
              <CheckCircleIcon className="w-12 h-12 text-emerald-500 mx-auto mb-2" />
              <p className="text-emerald-800 font-bold">¡Todo en orden!</p>
              <p className="text-emerald-600 text-sm">No hay reactivos con stock crítico actualmente.</p>
            </div>
          )}
        </div>
      </div>

      {orderedReagents.length > 0 && (
        <div className="space-y-6 opacity-60 hover:opacity-100 transition-opacity">
          <h2 className="text-lg font-bold text-slate-500 flex items-center gap-2">
            <ShoppingBagIcon className="w-5 h-5" />
            Ya Pedidos ({orderedReagents.length})
          </h2>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            {orderedReagents.map(r => (
              <div key={r.id} className="bg-white p-4 rounded-xl border border-slate-200 flex justify-between items-center shadow-sm">
                <div>
                  <p className="font-bold text-slate-700 text-sm">{r.name}</p>
                  <p className="text-xs text-slate-400">Esperando stock...</p>
                </div>
                <div className="bg-indigo-50 text-indigo-600 p-2 rounded-lg">
                  <ArrowPathIcon className="w-5 h-5 animate-spin" />
                </div>
              </div>
            ))}
