};

export default InputForm;

import React, { useState, useEffect, useMemo } from 'react';
import { HashRouter as Router, Routes, Route, Link, Navigate } from 'react-router-dom';
import { 
  BeakerIcon, 
  QueueListIcon, 
  BellAlertIcon, 
  PlusCircleIcon, 
  MinusCircleIcon,
  UserCircleIcon,
  ArrowRightOnRectangleIcon,
  HomeIcon,
  ChevronRightIcon,
  LockClosedIcon,
  EyeIcon,
  EyeSlashIcon,
  Cog6ToothIcon
} from '@heroicons/react/24/outline';

import { Reagent, Transaction, UserRole, Department } from './types';
import InventoryView from './components/InventoryView';
import InputForm from './components/InputForm';
import OutputForm from './components/OutputForm';
import HistoryView from './components/HistoryView';
import AlertsView from './components/AlertsView';
import ConfigView from './components/ConfigView';
import { generateId } from './utils';

const STORAGE_KEY_REAGENTS = 'reagentflow_inventory';
const STORAGE_KEY_TRANSACTIONS = 'reagentflow_transactions';
const STORAGE_KEY_MG_PASSWORD = 'reagentflow_mg_pwd';

const App: React.FC = () => {
  const [role, setRole] = useState<UserRole | null>(null);
  const [reagents, setReagents] = useState<Reagent[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);

  // Auth state
  const [pendingRole, setPendingRole] = useState<UserRole | null>(null);
  const [showAuthModal, setShowAuthModal] = useState(false);
  const [mgPassword, setMgPassword] = useState<string | null>(localStorage.getItem(STORAGE_KEY_MG_PASSWORD));

  const [authInput, setAuthInput] = useState('');
  const [authError, setAuthError] = useState('');
  const [showPassword, setShowPassword] = useState(false);

  // Load initial data
  useEffect(() => {
    const savedReagents = localStorage.getItem(STORAGE_KEY_REAGENTS);
    const savedTransactions = localStorage.getItem(STORAGE_KEY_TRANSACTIONS);
    if (savedReagents) setReagents(JSON.parse(savedReagents));
    if (savedTransactions) setTransactions(JSON.parse(savedTransactions));
  }, []);

  // Sync with LocalStorage
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY_REAGENTS, JSON.stringify(reagents));
  }, [reagents]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY_TRANSACTIONS, JSON.stringify(transactions));
  }, [transactions]);

  const handleTransaction = (reagent: Partial<Reagent>, transactionData: Omit<Transaction, 'id' | 'timestamp' | 'reagentName'>) => {
    const timestamp = new Date().toISOString();
    let updatedReagents = [...reagents];
    let reagentId = transactionData.reagentId;

    if (transactionData.type === 'IN') {
      const existingIdx = updatedReagents.findIndex(r => r.id === reagentId);
      if (existingIdx > -1) {
        const existing = updatedReagents[existingIdx];
        updatedReagents[existingIdx] = {
          ...existing,
          brand: reagent.brand || existing.brand, // Actualizar marca si el analista la cambió
          currentStock: existing.currentStock + transactionData.quantity,
          lastUpdated: timestamp,
          isOrdered: false
        };
      } else {
        const newReagent: Reagent = {
          id: reagentId || generateId(),
          name: reagent.name!,
          brand: reagent.brand!,
          presentation: reagent.presentation!,
          currentStock: transactionData.quantity,
          minStock: reagent.minStock || 0,
          department: reagent.department!,
          baseUnit: reagent.baseUnit || 'ud',
          containerType: reagent.containerType || 'Frasco',
          quantityPerContainer: reagent.quantityPerContainer || 1,
          expiryDate: reagent.expiryDate || 'N/A',
          isOrdered: false,
          lastUpdated: timestamp
        };
        updatedReagents.push(newReagent);
        reagentId = newReagent.id;
      }
    } else {
      const existingIdx = updatedReagents.findIndex(r => r.id === reagentId);
      if (existingIdx > -1) {
        const existing = updatedReagents[existingIdx];
        updatedReagents[existingIdx] = {
          ...existing,
          currentStock: Math.max(0, existing.currentStock - transactionData.quantity),
          lastUpdated: timestamp
        };
      }
    }
    setReagents(updatedReagents);
    const newTransaction: Transaction = {
      ...transactionData,
      id: generateId(),
      reagentId: reagentId!,
      reagentName: updatedReagents.find(r => r.id === reagentId)?.name || 'Desconocido',
      timestamp
    };
    setTransactions([newTransaction, ...transactions]);
  };

  const updateMinStock = (reagentId: string, newMinStock: number) => {
    setReagents(prev => prev.map(r => r.id === reagentId ? { ...r, minStock: newMinStock } : r));
  };

  const markAsOrdered = (reagentId: string) => {
    setReagents(prev => prev.map(r => r.id === reagentId ? { ...r, isOrdered: true } : r));
  };

  const openLogin = (roleType: UserRole) => {
    if (roleType === 'ANALISTA') {
      setRole('ANALISTA');
    } else {
      setPendingRole(roleType);
      setShowAuthModal(true);
      setAuthInput('');
      setAuthError('');
    }
  };

  const handleAuthSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (pendingRole === 'GERENTE') {
      if (!mgPassword) {
        if (authInput.length < 4) {
          setAuthError('La contraseña debe tener al menos 4 caracteres');
          return;
        }
        localStorage.setItem(STORAGE_KEY_MG_PASSWORD, authInput);
        setMgPassword(authInput);
        setRole('GERENTE');
        setShowAuthModal(false);
      } else {
        if (authInput === mgPassword) {
          setRole('GERENTE');
          setShowAuthModal(false);
        } else {
          setAuthError('Contraseña de Gerente incorrecta');
        }
      }
    }
  };

  const updatePasswords = (newMg?: string) => {
    if (newMg) {
      localStorage.setItem(STORAGE_KEY_MG_PASSWORD, newMg);
      setMgPassword(newMg);
    }
  };

  if (!role) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-600 to-indigo-900 flex items-center justify-center p-4">
        <div className="bg-white rounded-2xl shadow-2xl p-8 w-full max-w-md text-center">
          <BeakerIcon className="w-16 h-16 text-indigo-600 mx-auto mb-4" />
          <h1 className="text-3xl font-bold text-slate-800 mb-2">ReagentFlow</h1>
          <p className="text-slate-500 mb-8">Control Inteligente de Inventario</p>
          <div className="space-y-4">
            <button 
              onClick={() => openLogin('ANALISTA')}
              className="w-full bg-white border-2 border-slate-200 hover:border-indigo-600 hover:text-indigo-600 text-slate-700 font-semibold py-4 px-6 rounded-xl transition-all flex items-center justify-between group"
            >
              <div className="flex items-center gap-3"><QueueListIcon className="w-6 h-6" /><span>Entrar como Analista</span></div>
              <ChevronRightIcon className="w-5 h-5 opacity-0 group-hover:opacity-100 transition-opacity" />
            </button>
            <button 
              onClick={() => openLogin('GERENTE')}
              className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-semibold py-4 px-6 rounded-xl transition-all flex items-center justify-between group shadow-lg"
            >
              <div className="flex items-center gap-3"><BellAlertIcon className="w-6 h-6" /><span>Entrar como Gerente</span></div>
              <ChevronRightIcon className="w-5 h-5 opacity-50 group-hover:opacity-100 transition-opacity" />
            </button>
          </div>
          <div className="mt-8 text-[10px] text-slate-400 uppercase tracking-widest">v1.4.0 &bull; Analista Libre Acceso</div>
        </div>

        {showAuthModal && (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
            <div className="bg-white rounded-2xl shadow-2xl w-full max-w-sm overflow-hidden animate-in zoom-in-95 duration-200">
              <div className="bg-slate-50 p-6 border-b border-slate-100 flex items-center gap-3">
                <div className="bg-indigo-100 p-2 rounded-lg"><LockClosedIcon className="w-6 h-6 text-indigo-600" /></div>
                <div>
                  <h3 className="font-bold text-slate-800">Acceso Gerente</h3>
                  <p className="text-xs text-slate-500">
                    {!mgPassword ? 'Cree su contraseña maestra' : 'Ingrese su clave de acceso'}
                  </p>
                </div>
              </div>
              <form onSubmit={handleAuthSubmit} className="p-6 space-y-4">
                <div className="relative">
                  <input autoFocus type={showPassword ? "text" : "password"} placeholder="Contraseña"
                    className={`w-full pl-4 pr-12 py-3 border rounded-xl outline-none focus:ring-2 transition-all ${authError ? 'border-red-500 focus:ring-red-200' : 'border-slate-200 focus:ring-indigo-200'}`}
                    value={authInput} onChange={(e) => setAuthInput(e.target.value)} />
                  <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400">
                    {showPassword ? <EyeSlashIcon className="w-5 h-5" /> : <EyeIcon className="w-5 h-5" />}
                  </button>
                </div>
                {authError && <p className="text-red-600 text-xs font-medium">{authError}</p>}
                <div className="flex gap-3 pt-2">
                  <button type="button" onClick={() => setShowAuthModal(false)} className="flex-1 py-3 text-slate-500 font-semibold hover:bg-slate-100 rounded-xl">Cancelar</button>
                  <button type="submit" className="flex-[2] bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 rounded-xl shadow-lg">Entrar</button>
                </div>
              </form>
            </div>
          </div>
        )}
      </div>
    );
  }

  return (
    <Router>
      <div className="flex flex-col min-h-screen bg-slate-50">
        <nav className="bg-white border-b border-slate-200 sticky top-0 z-30 shadow-sm">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex justify-between h-16">
              <div className="flex items-center gap-2">
                <BeakerIcon className="h-8 w-8 text-indigo-600" />
                <span className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-indigo-600 to-blue-500 hidden sm:block">ReagentFlow</span>
              </div>
              <div className="flex items-center gap-4">
                <div className="hidden md:flex items-center gap-6 mr-6">
                  <Link to="/" className="text-slate-600 hover:text-indigo-600 font-medium">Inventario</Link>
                  <Link to="/ingreso" className="text-slate-600 hover:text-indigo-600 font-medium">Ingresos</Link>
                  <Link to="/salida" className="text-slate-600 hover:text-indigo-600 font-medium">Salidas</Link>
                  <Link to="/historial" className="text-slate-600 hover:text-indigo-600 font-medium">Historial</Link>
                  {role === 'GERENTE' && (
                    <>
                      <Link to="/alertas" className="flex items-center gap-1 text-slate-600 hover:text-red-600 font-medium">Alertas</Link>
                      <Link to="/config" className="text-slate-600 hover:text-indigo-600"><Cog6ToothIcon className="w-6 h-6" /></Link>
                    </>
                  )}
                </div>
                <div className="flex items-center gap-2 bg-slate-100 px-3 py-1.5 rounded-full">
                  <UserCircleIcon className="w-5 h-5 text-slate-500" />
                  <span className="text-sm font-semibold text-slate-700">{role}</span>
                </div>
                <button onClick={() => setRole(null)} className="p-2 text-slate-400 hover:text-red-600 transition-colors"><ArrowRightOnRectangleIcon className="w-6 h-6" /></button>
              </div>
            </div>
          </div>
        </nav>

        <main className="flex-grow max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 mb-20 md:mb-8">
          <Routes>
            <Route path="/" element={<InventoryView reagents={reagents} />} />
            <Route path="/ingreso" element={<InputForm reagents={reagents} onTransaction={handleTransaction} transactions={transactions} />} />
            <Route path="/salida" element={<OutputForm reagents={reagents} onTransaction={handleTransaction} />} />
            <Route path="/historial" element={<HistoryView transactions={transactions} />} />
            <Route path="/alertas" element={role === 'GERENTE' ? <AlertsView reagents={reagents} markAsOrdered={markAsOrdered} onUpdateMinStock={updateMinStock} /> : <Navigate to="/" />} />
            <Route path="/config" element={role === 'GERENTE' ? <ConfigView updatePasswords={updatePasswords} currentMg={mgPassword} /> : <Navigate to="/" />} />
          </Routes>
        </main>
      </div>
    </Router>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Reagent } from '../types';
import { MagnifyingGlassIcon, FunnelIcon, BeakerIcon } from '@heroicons/react/24/outline';
import { formatDate } from '../utils';

interface Props {
  reagents: Reagent[];
}

const InventoryView: React.FC<Props> = ({ reagents }) => {
  const [search, setSearch] = useState('');
  const [deptFilter, setDeptFilter] = useState<string>('all');

  const groupedReagents = useMemo(() => {
    const groups: Record<string, {
      name: string;
      department: string;
      presentation: string;
      totalStock: number;
      minStock: number;
      baseUnit: string;
      containerType: string;
      quantityPerContainer: number;
      expiryDate: string;
      lastUpdated: string;
      brands: { brand: string; stock: number; id: string }[];
    }> = {};

    reagents.forEach(r => {
      const key = `${r.name.toLowerCase()}-${r.department}`;
      if (!groups[key]) {
        groups[key] = {
          name: r.name,
          department: r.department,
          presentation: r.presentation,
          totalStock: r.currentStock,
          minStock: r.minStock,
          baseUnit: r.baseUnit,
          containerType: r.containerType,
          quantityPerContainer: r.quantityPerContainer,
          expiryDate: r.expiryDate,
          lastUpdated: r.lastUpdated,
          brands: [{ brand: r.brand, stock: r.currentStock, id: r.id }]
        };
      } else {
        groups[key].totalStock += r.currentStock;
        groups[key].brands.push({ brand: r.brand, stock: r.currentStock, id: r.id });
        // Actualizar con la fecha de vencimiento más próxima si es relevante
        if (r.expiryDate !== 'N/A' && (groups[key].expiryDate === 'N/A' || new Date(r.expiryDate) < new Date(groups[key].expiryDate))) {
          groups[key].expiryDate = r.expiryDate;
        }
        if (new Date(r.lastUpdated) > new Date(groups[key].lastUpdated)) {
          groups[key].lastUpdated = r.lastUpdated;
        }
        // El stock mínimo se sincroniza (usamos el mayor definido para seguridad)
        groups[key].minStock = Math.max(groups[key].minStock, r.minStock);
      }
    });

    return Object.values(groups).filter(g => {
      const matchesSearch = g.name.toLowerCase().includes(search.toLowerCase()) || 
                            g.brands.some(b => b.brand.toLowerCase().includes(search.toLowerCase()));
      const matchesDept = deptFilter === 'all' || g.department === deptFilter;
      return matchesSearch && matchesDept;
    });
  }, [reagents, search, deptFilter]);

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-800">Inventario Consolidado</h1>
          <p className="text-slate-500">Stock total sumando todas las marcas disponibles.</p>
        </div>

        <div className="flex flex-col sm:flex-row gap-3">
          <div className="relative">
            <MagnifyingGlassIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
            <input 
              type="text"
              placeholder="Buscar por nombre o marca..."
              className="pl-10 pr-4 py-2 bg-white border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none w-full sm:w-64 transition-all"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
          </div>

          <div className="relative">
            <FunnelIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
            <select 
              className="pl-10 pr-8 py-2 bg-white border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none appearance-none cursor-pointer"
              value={deptFilter}
              onChange={(e) => setDeptFilter(e.target.value)}
            >
              <option value="all">Todos los Deptos.</option>
              <option value="Fisicoquímico">Fisicoquímico</option>
              <option value="Microbiología">Microbiología</option>
              <option value="Molecular">Molecular</option>
            </select>
          </div>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-slate-50 border-b border-slate-200">
              <tr>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Reactivo</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Marcas en Stock</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Stock Consolidado</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Vencimiento Prox.</th>
                <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Estado</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {groupedReagents.map(group => {
                const isLow = group.totalStock <= group.minStock;
                return (
                  <tr key={`${group.name}-${group.department}`} className="hover:bg-slate-50 transition-colors">
                    <td className="px-6 py-4">
                      <div className="font-semibold text-slate-800">{group.name}</div>
                      <div className="text-[10px] text-slate-400 font-bold uppercase tracking-tighter">{group.department} • {group.presentation}</div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex flex-wrap gap-1">
                        {group.brands.map((b, idx) => (
                          <span key={idx} className="inline-flex items-center px-2 py-0.5 rounded text-[10px] font-medium bg-slate-100 text-slate-600 border border-slate-200">
                            {b.brand}: {b.stock}{group.baseUnit}
                          </span>
                        ))}
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <span className={`text-sm font-bold ${isLow ? 'text-red-600' : 'text-slate-800'}`}>
                        {group.totalStock} {group.baseUnit}
                      </span>
                      <div className="text-[10px] text-slate-400 font-bold">MÍNIMO: {group.minStock} {group.baseUnit}</div>
                    </td>
                    <td className="px-6 py-4 text-sm text-slate-600">{formatDate(group.expiryDate)}</td>
                    <td className="px-6 py-4">
                      {isLow ? (
                        <span className="px-2 py-1 rounded-full text-[10px] font-bold bg-red-100 text-red-700 border border-red-200 uppercase tracking-widest">Pedir Reposición</span>
                      ) : (
                        <span className="px-2 py-1 rounded-full text-[10px] font-bold bg-emerald-100 text-emerald-700 border border-emerald-200 uppercase tracking-widest">Suficiente</span>
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default InventoryView;

import React, { useState, useRef, useMemo } from 'react';
import { Reagent, Presentation, Department, Transaction } from '../types';
import { analyzeReagentLabel } from '../services/geminiService';
import { fileToBase64, generateId } from '../utils';
import { 
  CameraIcon, 
  SparklesIcon, 
  ArrowPathIcon,
  PlusIcon
} from '@heroicons/react/24/solid';

interface Props {
  reagents: Reagent[];
  transactions: Transaction[];
  onTransaction: (reagent: Partial<Reagent>, data: any) => void;
}

const BASE_UNITS_LIQUID = ['mL', 'L'];
const BASE_UNITS_SOLID = ['g', 'kg'];
const BASE_UNITS_PKG = ['unidades'];

const InputForm: React.FC<Props> = ({ reagents, transactions, onTransaction }) => {
  const [loading, setLoading] = useState(false);
  const [isExisting, setIsExisting] = useState(false);
  const [selectedReagentId, setSelectedReagentId] = useState('');
  const [showNewUnitInput, setShowNewUnitInput] = useState(false);
  const [customUnit, setCustomUnit] = useState('');

  // Form State
  const [formData, setFormData] = useState({
    name: '',
    brand: '',
    presentation: 'Líquido' as Presentation,
    containerType: 'Frascos',
    quantityEntered: 0,
    quantityPerContainer: 1,
    baseUnit: 'mL',
    expiryDate: '',
    department: 'Fisicoquímico' as Department,
    analystName: '',
    minStock: 0
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  const unitsForPresentation = useMemo(() => {
    if (formData.presentation === 'Líquido') return BASE_UNITS_LIQUID;
    if (formData.presentation === 'Sólido') return BASE_UNITS_SOLID;
    return BASE_UNITS_PKG;
  }, [formData.presentation]);

  const totalBaseQuantity = useMemo(() => {
    return formData.quantityEntered * formData.quantityPerContainer;
  }, [formData.quantityEntered, formData.quantityPerContainer]);

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    try {
      const base64 = await fileToBase64(file);
      const analysis = await analyzeReagentLabel(base64);

      const newBaseUnit = analysis.presentation === 'Líquido' ? 'mL' : (analysis.presentation === 'Sólido' ? 'g' : 'unidades');

      setFormData(prev => ({
        ...prev,
        name: analysis.name || '',
        brand: analysis.brand || '',
        presentation: analysis.presentation || 'Líquido',
        baseUnit: newBaseUnit
      }));

      const existing = reagents.find(r => 
        r.name.toLowerCase() === analysis.name.toLowerCase() && 
        r.brand.toLowerCase() === analysis.brand.toLowerCase()
      );

      if (existing) {
        setIsExisting(true);
        setSelectedReagentId(existing.id);
        setFormData(prev => ({ 
          ...prev, 
          baseUnit: existing.baseUnit, 
          containerType: existing.containerType,
          quantityPerContainer: existing.quantityPerContainer,
          minStock: existing.minStock 
        }));
      } else {
        setIsExisting(false);
      }
    } catch (error) {
      alert("Error analizando la etiqueta.");
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    const finalBaseUnit = showNewUnitInput ? customUnit : formData.baseUnit;

    // Lógica crucial: Si el analista cambió la marca del reactivo seleccionado, 
    // lo tratamos como un nuevo registro para que coexistan las marcas.
    const originalReagent = isExisting ? reagents.find(r => r.id === selectedReagentId) : null;
    const brandChanged = originalReagent && originalReagent.brand.toLowerCase() !== formData.brand.toLowerCase();

    const finalReagentId = (isExisting && !brandChanged) ? selectedReagentId : undefined;

    onTransaction(
      {
        id: finalReagentId,
        name: formData.name,
        brand: formData.brand,
        presentation: formData.presentation,
        department: formData.department,
        expiryDate: formData.expiryDate || 'N/A',
        minStock: formData.minStock,
        containerType: formData.containerType,
        quantityPerContainer: formData.quantityPerContainer,
        baseUnit: finalBaseUnit
      },
      {
        reagentId: finalReagentId,
        type: 'IN',
        quantity: totalBaseQuantity,
        displayQuantity: formData.quantityEntered,
        displayUnit: formData.containerType,
        analyst: formData.analystName
      }
    );

    // Reset
    setFormData({
      name: '', brand: '', presentation: 'Líquido', containerType: 'Frascos',
      quantityEntered: 0, quantityPerContainer: 1, baseUnit: 'mL', 
      expiryDate: '', department: 'Fisicoquímico', analystName: '', minStock: 0
    });
    setIsExisting(false);
    setSelectedReagentId('');
    setShowNewUnitInput(false);
    setCustomUnit('');
    alert("Ingreso registrado exitosamente.");
  };

  return (
    <div className="max-w-3xl mx-auto">
      <div className="bg-white rounded-2xl shadow-xl border border-slate-200 overflow-hidden">
