import React, { useMemo } from 'react';
import { Reagent } from '../types';
import { 
  BellAlertIcon, 
  ShoppingBagIcon, 
  CheckCircleIcon,
  ExclamationCircleIcon
} from '@heroicons/react/24/solid';

interface Props {
  reagents: Reagent[];
  markAsOrdered: (id: string) => void;
  onUpdateMinStock: (id: string, newMin: number) => void;
}

const AlertsView: React.FC<Props> = ({ reagents, markAsOrdered, onUpdateMinStock }) => {
  // Consolidamos por nombre para calcular el stock total real del laboratorio
  const alertsData = useMemo(() => {
    const consolidated: Record<string, {
      name: string;
      totalStock: number;
      minStock: number;
      baseUnit: string;
      isOrdered: boolean;
      brands: { brand: string, stock: number, id: string }[];
    }> = {};

    reagents.forEach(r => {
      const key = r.name.toLowerCase();
      if (!consolidated[key]) {
        consolidated[key] = {
          name: r.name,
          totalStock: r.currentStock,
          minStock: r.minStock,
          baseUnit: r.baseUnit,
          isOrdered: r.isOrdered,
          brands: [{ brand: r.brand, stock: r.currentStock, id: r.id }]
        };
      } else {
        consolidated[key].totalStock += r.currentStock;
        consolidated[key].brands.push({ brand: r.brand, stock: r.currentStock, id: r.id });
        consolidated[key].minStock = Math.max(consolidated[key].minStock, r.minStock);
        // Si al menos una marca está marcada como pedida, consideramos el grupo como gestionado
        if (r.isOrdered) consolidated[key].isOrdered = true;
      }
    });

    // Solo mostramos lo que NO ha sido marcado como pedido todavía
    const lowStock = Object.values(consolidated).filter(c => c.totalStock <= c.minStock && !c.isOrdered);

    return { lowStock };
  }, [reagents]);

  return (
    <div className="space-y-10">
      <div className="bg-red-50 border-l-4 border-red-500 p-6 rounded-r-xl">
        <div className="flex items-center gap-3 mb-2">
          <BellAlertIcon className="w-8 h-8 text-red-600" />
          <h1 className="text-2xl font-bold text-red-900">Panel de Alertas Inteligente</h1>
        </div>
        <p className="text-red-700 font-medium">Lista de reactivos con stock crítico que requieren su atención inmediata.</p>
      </div>

      <div className="space-y-6">
        <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2">
          <ExclamationCircleIcon className="w-5 h-5 text-red-600" />
          Reactivos por Solicitar ({alertsData.lowStock.length})
        </h2>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {alertsData.lowStock.length > 0 ? (
            alertsData.lowStock.map(group => (
              <div key={group.name} className="bg-white rounded-2xl shadow-md border border-red-100 overflow-hidden group">
                <div className="p-5">
                  <div className="flex justify-between items-start mb-4">
                    <div>
                      <h3 className="font-bold text-slate-800 text-lg">{group.name}</h3>
                      <p className="text-[10px] text-slate-400 font-bold uppercase tracking-tight">Acción requerida</p>
                    </div>
                    <span className="bg-red-100 text-red-700 text-[10px] font-bold px-2 py-1 rounded-full uppercase">Crítico</span>
                  </div>

                  <div className="space-y-3 mb-6">
                    <div className="flex justify-between text-sm">
                      <span className="text-slate-500">Stock Consolidado:</span>
                      <span className="font-bold text-red-600">{group.totalStock} {group.baseUnit}</span>
                    </div>
                    <div className="flex justify-between text-sm">
                      <span className="text-slate-500">Stock Mínimo:</span>
                      <span className="font-bold text-slate-700">{group.minStock} {group.baseUnit}</span>
                    </div>

                    <div className="bg-slate-50 p-2 rounded border border-slate-100 space-y-1 max-h-24 overflow-y-auto">
                      <p className="text-[9px] text-slate-400 font-bold uppercase">Marcas en inventario:</p>
                      {group.brands.map((b, idx) => (
                        <div key={idx} className="flex justify-between text-[10px]">
                          <span className="text-slate-600 truncate mr-2">{b.brand}:</span>
                          <span className="font-semibold whitespace-nowrap">{b.stock}{group.baseUnit}</span>
                        </div>
                      ))}
                    </div>

                    <div className="h-1.5 w-full bg-slate-100 rounded-full overflow-hidden">
                      <div 
                        className="h-full bg-red-500" 
                        style={{ width: `${Math.min(100, (group.totalStock / group.minStock) * 100)}%` }}
                      ></div>
                    </div>
                  </div>

                  <button 
                    onClick={() => {
                      // Marcamos la primera ID del grupo; el componente App se encarga de propagar el estado por nombre
                      if (group.brands.length > 0) {
                        markAsOrdered(group.brands[0].id);
                      }
                    }}
                    className="w-full flex items-center justify-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 rounded-xl transition-all shadow-indigo-200 shadow-lg"
                  >
                    <ShoppingBagIcon className="w-5 h-5" />
                    Marcar como Pedido
                  </button>
                </div>
              </div>
            ))
          ) : (
            <div className="col-span-full py-12 text-center bg-emerald-50 rounded-2xl border border-emerald-100">
              <CheckCircleIcon className="w-12 h-12 text-emerald-500 mx-auto mb-2" />
              <p className="text-emerald-800 font-bold">¡Todo gestionado!</p>
              <p className="text-emerald-600 text-sm">No hay reactivos pendientes de pedido en este momento.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default AlertsView;

import React, { useState, useEffect, useMemo } from 'react';
import { HashRouter as Router, Routes, Route, Link, Navigate, useLocation } from 'react-router-dom';
import { 
  BeakerIcon, 
  QueueListIcon, 
  BellAlertIcon, 
  PlusCircleIcon, 
  MinusCircleIcon,
  UserCircleIcon,
  ArrowRightOnRectangleIcon,
  HomeIcon,
  ChevronRightIcon,
  LockClosedIcon,
  EyeIcon,
  EyeSlashIcon,
  Cog6ToothIcon,
  ClockIcon
} from '@heroicons/react/24/outline';

import { Reagent, Transaction, UserRole, Department } from './types';
import InventoryView from './components/InventoryView';
import InputForm from './components/InputForm';
import OutputForm from './components/OutputForm';
import HistoryView from './components/HistoryView';
import AlertsView from './components/AlertsView';
import ConfigView from './components/ConfigView';
import { generateId } from './utils';

const STORAGE_KEY_REAGENTS = 'reagentflow_inventory';
const STORAGE_KEY_TRANSACTIONS = 'reagentflow_transactions';
const STORAGE_KEY_MG_PASSWORD = 'reagentflow_mg_pwd';
const STORAGE_KEY_MG_EMAIL = 'reagentflow_mg_email';

const App: React.FC = () => {
  const [role, setRole] = useState<UserRole | null>(null);
  const [reagents, setReagents] = useState<Reagent[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [managerEmail, setManagerEmail] = useState<string>(localStorage.getItem(STORAGE_KEY_MG_EMAIL) || '');

  // Auth state
  const [pendingRole, setPendingRole] = useState<UserRole | null>(null);
  const [showAuthModal, setShowAuthModal] = useState(false);
  const [mgPassword, setMgPassword] = useState<string | null>(localStorage.getItem(STORAGE_KEY_MG_PASSWORD));

  const [authInput, setAuthInput] = useState('');
  const [authError, setAuthError] = useState('');
  const [showPassword, setShowPassword] = useState(false);

  // Load initial data
  useEffect(() => {
    const savedReagents = localStorage.getItem(STORAGE_KEY_REAGENTS);
    const savedTransactions = localStorage.getItem(STORAGE_KEY_TRANSACTIONS);
    if (savedReagents) setReagents(JSON.parse(savedReagents));
    if (savedTransactions) setTransactions(JSON.parse(savedTransactions));
  }, []);

  // Sync with LocalStorage
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY_REAGENTS, JSON.stringify(reagents));
  }, [reagents]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY_TRANSACTIONS, JSON.stringify(transactions));
  }, [transactions]);

  const handleTransaction = (reagent: Partial<Reagent>, transactionData: Omit<Transaction, 'id' | 'timestamp' | 'reagentName'>) => {
    const timestamp = new Date().toISOString();
    let updatedReagents = [...reagents];
    let reagentId = transactionData.reagentId;

    if (transactionData.type === 'IN') {
      const existingIdx = updatedReagents.findIndex(r => r.id === reagentId);
      if (existingIdx > -1) {
        const existing = updatedReagents[existingIdx];
        const rName = existing.name.toLowerCase();
        updatedReagents = updatedReagents.map(r => 
          r.name.toLowerCase() === rName 
            ? { ...r, isOrdered: false, ...(r.id === reagentId ? { 
                brand: reagent.brand || r.brand, 
                currentStock: r.currentStock + transactionData.quantity,
                lastUpdated: timestamp 
              } : {}) }
            : r
        );
      } else {
        const newReagent: Reagent = {
          id: reagentId || generateId(),
          name: reagent.name!,
          brand: reagent.brand!,
          presentation: reagent.presentation!,
          currentStock: transactionData.quantity,
          minStock: reagent.minStock || 0,
          department: reagent.department!,
          baseUnit: reagent.baseUnit || 'ud',
          containerType: reagent.containerType || 'Frasco',
          quantityPerContainer: reagent.quantityPerContainer || 1,
          expiryDate: reagent.expiryDate || 'N/A',
          isOrdered: false,
          lastUpdated: timestamp
        };
        updatedReagents.push(newReagent);
        reagentId = newReagent.id;
      }
    } else {
      const existingIdx = updatedReagents.findIndex(r => r.id === reagentId);
      if (existingIdx > -1) {
        const existing = updatedReagents[existingIdx];
        const newStock = Math.max(0, existing.currentStock - transactionData.quantity);
        updatedReagents[existingIdx] = { ...existing, currentStock: newStock, lastUpdated: timestamp };

        // Lógica de Alerta por Correo: Comprobar Stock Global Consolidado
        const consolidatedStock = updatedReagents
          .filter(r => r.name.toLowerCase() === existing.name.toLowerCase())
          .reduce((sum, r) => sum + r.currentStock, 0);

        if (consolidatedStock <= existing.minStock && managerEmail) {
          console.log(`[ALERTA EMAIL ENVIADA A ${managerEmail}]: El reactivo ${existing.name} ha alcanzado el stock mínimo (${consolidatedStock}${existing.baseUnit})`);
          // Aquí se podría integrar un servicio como EmailJS o un webhook
        }
      }
    }
    setReagents(updatedReagents);
    const newTransaction: Transaction = {
      ...transactionData,
      id: generateId(),
      reagentId: reagentId!,
      reagentName: updatedReagents.find(r => r.id === reagentId)?.name || 'Desconocido',
      timestamp
    };
    setTransactions([newTransaction, ...transactions]);
  };

  const updateMinStock = (reagentId: string, newMinStock: number) => {
    setReagents(prev => prev.map(r => r.id === reagentId ? { ...r, minStock: newMinStock } : r));
  };

  const markAsOrdered = (reagentId: string) => {
    const reagentToMark = reagents.find(r => r.id === reagentId);
    if (!reagentToMark) return;
    const rName = reagentToMark.name.toLowerCase();
    setReagents(prev => prev.map(r => 
      r.name.toLowerCase() === rName ? { ...r, isOrdered: true } : r
    ));
  };

  const updateMgSettings = (pwd?: string, email?: string) => {
    if (pwd) {
      localStorage.setItem(STORAGE_KEY_MG_PASSWORD, pwd);
      setMgPassword(pwd);
    }
    if (email !== undefined) {
      localStorage.setItem(STORAGE_KEY_MG_EMAIL, email);
