    return (
      <div className="md:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-slate-200 flex justify-around items-center h-16 px-2 z-50">
        {navItems.map((item) => (
          <Link key={item.path} to={item.path} className={`flex flex-col items-center justify-center w-full h-full transition-colors ${location.pathname === item.path ? 'text-indigo-600' : 'text-slate-400'}`}>
            <item.icon className="w-6 h-6" />
            <span className="text-[10px] font-bold mt-1 uppercase tracking-tighter">{item.label}</span>
          </Link>
        ))}
      </div>
    );
  };

  if (!role) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-600 to-indigo-900 flex items-center justify-center p-4">
        <div className="bg-white rounded-3xl shadow-2xl p-6 md:p-10 w-full max-w-md text-center">
          <BeakerIcon className="w-16 h-16 text-indigo-600 mx-auto mb-4" />
          <h1 className="text-3xl font-bold text-slate-800 mb-2">ReagentFlow</h1>
          <p className="text-slate-500 mb-8">Control Inteligente de Inventario</p>
          <div className="space-y-4">
            <button 
              onClick={() => { setRole('ANALISTA'); }}
              className="w-full bg-white border-2 border-slate-200 hover:border-indigo-600 hover:text-indigo-600 text-slate-700 font-bold py-4 px-6 rounded-2xl transition-all flex items-center justify-between group"
            >
              <div className="flex items-center gap-3"><QueueListIcon className="w-6 h-6" /><span>Analista</span></div>
              <ChevronRightIcon className="w-5 h-5 opacity-50 group-hover:opacity-100" />
            </button>
            <button 
              onClick={() => { setPendingRole('GERENTE'); setShowAuthModal(true); setAuthInput(''); setAuthError(''); }}
              className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-4 px-6 rounded-2xl transition-all flex items-center justify-between group shadow-xl"
            >
              <div className="flex items-center gap-3"><BellAlertIcon className="w-6 h-6" /><span>Gerente</span></div>
              <ChevronRightIcon className="w-5 h-5 opacity-50 group-hover:opacity-100" />
            </button>
          </div>
          <div className="mt-8 text-[10px] text-slate-400 uppercase tracking-widest font-bold">Multiplataforma v1.5.0</div>
        </div>

        {showAuthModal && (
          <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
            <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm overflow-hidden">
              <div className="bg-slate-50 p-6 border-b border-slate-100 flex items-center gap-3">
                <LockClosedIcon className="w-8 h-8 text-indigo-600" />
                <div>
                  <h3 className="font-bold text-slate-800">Seguridad</h3>
                  <p className="text-xs text-slate-500">{!mgPassword ? 'Cree su clave' : 'Ingrese clave'}</p>
                </div>
              </div>
              <form onSubmit={(e) => {
                e.preventDefault();
                if (pendingRole === 'GERENTE') {
                  if (!mgPassword) {
                    if (authInput.length < 4) { setAuthError('Mínimo 4 caracteres'); return; }
                    updateMgSettings(authInput);
                    setRole('GERENTE'); setShowAuthModal(false);
                  } else if (authInput === mgPassword) {
                    setRole('GERENTE'); setShowAuthModal(false);
                  } else { setAuthError('Clave incorrecta'); }
                }
              }} className="p-6 space-y-4">
                <div className="relative">
                  <input autoFocus type={showPassword ? "text" : "password"} placeholder="****"
                    className="w-full pl-4 pr-12 py-4 bg-slate-50 border-2 border-slate-200 rounded-xl outline-none focus:border-indigo-500 transition-all text-center text-xl tracking-widest"
                    value={authInput} onChange={(e) => setAuthInput(e.target.value)} />
                  <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400">
                    {showPassword ? <EyeSlashIcon className="w-5 h-5" /> : <EyeIcon className="w-5 h-5" />}
                  </button>
                </div>
                {authError && <p className="text-red-600 text-xs font-bold text-center">{authError}</p>}
                <div className="flex gap-3 pt-2">
                  <button type="button" onClick={() => setShowAuthModal(false)} className="flex-1 py-3 text-slate-500 font-bold hover:bg-slate-100 rounded-xl">Cerrar</button>
                  <button type="submit" className="flex-[2] bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 rounded-xl shadow-lg">Acceder</button>
                </div>
              </form>
            </div>
          </div>
        )}
      </div>
    );
  }

  return (
    <Router>
      <div className="flex flex-col min-h-screen bg-slate-50 pb-16 md:pb-0">
        <nav className="bg-white border-b border-slate-200 sticky top-0 z-30 shadow-sm hidden md:block">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex justify-between h-16">
              <div className="flex items-center gap-2">
                <BeakerIcon className="h-8 w-8 text-indigo-600" />
                <span className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-indigo-600 to-blue-500">ReagentFlow</span>
              </div>
              <div className="flex items-center gap-6">
                <Link to="/" className="text-slate-600 hover:text-indigo-600 font-bold text-sm">Inventario</Link>
                <Link to="/ingreso" className="text-slate-600 hover:text-indigo-600 font-bold text-sm">Ingresos</Link>
                <Link to="/salida" className="text-slate-600 hover:text-indigo-600 font-bold text-sm">Salidas</Link>
                <Link to="/historial" className="text-slate-600 hover:text-indigo-600 font-bold text-sm">Historial</Link>
                {role === 'GERENTE' && (
                  <>
                    <Link to="/alertas" className="flex items-center gap-1 text-slate-600 hover:text-red-600 font-bold text-sm">Alertas</Link>
                    <Link to="/config" className="text-slate-600 hover:text-indigo-600"><Cog6ToothIcon className="w-6 h-6" /></Link>
                  </>
