import React, { useState, useMemo } from 'react';
import { Reagent } from '../types';
import { MagnifyingGlassIcon, FunnelIcon, BeakerIcon } from '@heroicons/react/24/outline';
import { formatDate } from '../utils';

interface Props {
  reagents: Reagent[];
}

const InventoryView: React.FC<Props> = ({ reagents }) => {
  const [search, setSearch] = useState('');
  const [deptFilter, setDeptFilter] = useState<string>('all');

  const groupedReagents = useMemo(() => {
    const groups: Record<string, {
      name: string;
      department: string;
      presentation: string;
      totalStock: number;
      minStock: number;
      baseUnit: string;
      containerType: string;
      quantityPerContainer: number;
      expiryDate: string;
      lastUpdated: string;
      brands: { brand: string; stock: number; id: string }[];
    }> = {};

    reagents.forEach(r => {
      const key = `${r.name.toLowerCase()}-${r.department}`;
      if (!groups[key]) {
        groups[key] = {
          name: r.name,
          department: r.department,
          presentation: r.presentation,
          totalStock: r.currentStock,
          minStock: r.minStock,
          baseUnit: r.baseUnit,
          containerType: r.containerType,
          quantityPerContainer: r.quantityPerContainer,
          expiryDate: r.expiryDate,
          lastUpdated: r.lastUpdated,
          brands: [{ brand: r.brand, stock: r.currentStock, id: r.id }]
        };
      } else {
        groups[key].totalStock += r.currentStock;
        groups[key].brands.push({ brand: r.brand, stock: r.currentStock, id: r.id });
        if (r.expiryDate !== 'N/A' && (groups[key].expiryDate === 'N/A' || new Date(r.expiryDate) < new Date(groups[key].expiryDate))) {
          groups[key].expiryDate = r.expiryDate;
        }
        if (new Date(r.lastUpdated) > new Date(groups[key].lastUpdated)) {
          groups[key].lastUpdated = r.lastUpdated;
        }
        groups[key].minStock = Math.max(groups[key].minStock, r.minStock);
      }
    });

    return Object.values(groups).filter(g => {
      const matchesSearch = g.name.toLowerCase().includes(search.toLowerCase()) || 
                            g.brands.some(b => b.brand.toLowerCase().includes(search.toLowerCase()));
      const matchesDept = deptFilter === 'all' || g.department === deptFilter;
      return matchesSearch && matchesDept;
    });
  }, [reagents, search, deptFilter]);

  return (
    <div className="space-y-6 pb-4">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-800">Inventario Global</h1>
          <p className="text-slate-500 text-sm">Consolidado por tipo de reactivo.</p>
        </div>

        <div className="grid grid-cols-1 sm:flex gap-3">
          <div className="relative">
            <MagnifyingGlassIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
            <input 
              type="text"
              placeholder="Nombre o marca..."
              className="pl-10 pr-4 py-3 bg-white border border-slate-200 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none w-full sm:w-64 transition-all text-sm"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
          </div>

          <div className="relative">
            <FunnelIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
            <select 
              className="pl-10 pr-8 py-3 bg-white border border-slate-200 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none appearance-none cursor-pointer w-full text-sm font-bold text-slate-700"
              value={deptFilter}
              onChange={(e) => setDeptFilter(e.target.value)}
            >
              <option value="all">Departamentos</option>
              <option value="Fisicoquímico">Fisicoquímico</option>
              <option value="Microbiología">Microbiología</option>
              <option value="Molecular">Molecular</option>
            </select>
          </div>
        </div>
      </div>

      <div className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
        <div className="overflow-x-auto scrollbar-hide">
          <table className="w-full text-left min-w-[600px]">
            <thead className="bg-slate-50 border-b border-slate-200">
              <tr>
                <th className="px-6 py-4 text-[10px] font-black text-slate-500 uppercase tracking-widest">Reactivo</th>
                <th className="px-6 py-4 text-[10px] font-black text-slate-500 uppercase tracking-widest">Marcas / Existencias</th>
                <th className="px-6 py-4 text-[10px] font-black text-slate-500 uppercase tracking-widest">Stock Total</th>
                <th className="px-6 py-4 text-[10px] font-black text-slate-500 uppercase tracking-widest">Estado</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {groupedReagents.map(group => {
                const isLow = group.totalStock <= group.minStock;
                return (
                  <tr key={`${group.name}-${group.department}`} className="hover:bg-slate-50/50 transition-colors">
                    <td className="px-6 py-4">
                      <div className="font-bold text-slate-800">{group.name}</div>
                      <div className="text-[10px] text-indigo-500 font-black uppercase tracking-tighter">{group.department}</div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex flex-wrap gap-1 max-w-xs">
                        {group.brands.map((b, idx) => (
                          <span key={idx} className="inline-flex items-center px-2 py-0.5 rounded-lg text-[10px] font-bold bg-slate-100 text-slate-600 border border-slate-200">
                            {b.brand}: {b.stock}{group.baseUnit}
                          </span>
                        ))}
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className={`text-sm font-black ${isLow ? 'text-red-600' : 'text-slate-800'}`}>
                        {group.totalStock} {group.baseUnit}
                      </div>
                      <div className="text-[9px] text-slate-400 font-black uppercase">Mín: {group.minStock} {group.baseUnit}</div>
                    </td>
                    <td className="px-6 py-4">
                      {isLow ? (
                        <span className="px-3 py-1 rounded-full text-[9px] font-black bg-red-100 text-red-700 border border-red-200 uppercase tracking-widest whitespace-nowrap">Stock Bajo</span>
                      ) : (
                        <span className="px-3 py-1 rounded-full text-[9px] font-black bg-emerald-100 text-emerald-700 border border-emerald-200 uppercase tracking-widest whitespace-nowrap">OK</span>
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default InventoryView;

import React, { useState, useEffect, useMemo } from 'react';
import { HashRouter as Router, Routes, Route, Link, Navigate, useLocation } from 'react-router-dom';
import { 
  BeakerIcon, 
  QueueListIcon, 
  BellAlertIcon, 
  PlusCircleIcon, 
  MinusCircleIcon,
  UserCircleIcon,
  ArrowRightOnRectangleIcon,
  HomeIcon,
  ChevronRightIcon,
  LockClosedIcon,
  EyeIcon,
  EyeSlashIcon,
  Cog6ToothIcon,
  ClockIcon,
  CheckBadgeIcon
} from '@heroicons/react/24/outline';

import { Reagent, Transaction, UserRole, Department } from './types';
import InventoryView from './components/InventoryView';
import InputForm from './components/InputForm';
import OutputForm from './components/OutputForm';
import HistoryView from './components/HistoryView';
import AlertsView from './components/AlertsView';
import ConfigView from './components/ConfigView';
import { generateId } from './utils';

const STORAGE_KEY_REAGENTS = 'reagentflow_inventory';
const STORAGE_KEY_TRANSACTIONS = 'reagentflow_transactions';
const STORAGE_KEY_NOTIFICATIONS = 'reagentflow_notifications';
const STORAGE_KEY_MG_PASSWORD = 'reagentflow_mg_pwd';
const STORAGE_KEY_MG_EMAIL = 'reagentflow_mg_email';

interface NotificationLog {
  id: string;
  reagentName: string;
  timestamp: string;
  targetEmail: string;
  stockLevel: string;
}

const App: React.FC = () => {
  const [role, setRole] = useState<UserRole | null>(null);
  const [reagents, setReagents] = useState<Reagent[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [notifications, setNotifications] = useState<NotificationLog[]>([]);
  const [managerEmail, setManagerEmail] = useState<string>(localStorage.getItem(STORAGE_KEY_MG_EMAIL) || '');
  const [toast, setToast] = useState<{message: string, type: 'success' | 'alert'} | null>(null);

  // Auth state
  const [pendingRole, setPendingRole] = useState<UserRole | null>(null);
  const [showAuthModal, setShowAuthModal] = useState(false);
  const [mgPassword, setMgPassword] = useState<string | null>(localStorage.getItem(STORAGE_KEY_MG_PASSWORD));

  const [authInput, setAuthInput] = useState('');
  const [authError, setAuthError] = useState('');
  const [showPassword, setShowPassword] = useState(false);

  // Load initial data
  useEffect(() => {
    const savedReagents = localStorage.getItem(STORAGE_KEY_REAGENTS);
    const savedTransactions = localStorage.getItem(STORAGE_KEY_TRANSACTIONS);
    const savedNotifs = localStorage.getItem(STORAGE_KEY_NOTIFICATIONS);
    if (savedReagents) setReagents(JSON.parse(savedReagents));
    if (savedTransactions) setTransactions(JSON.parse(savedTransactions));
    if (savedNotifs) setNotifications(JSON.parse(savedNotifs));
  }, []);

  // Sync with LocalStorage
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY_REAGENTS, JSON.stringify(reagents));
  }, [reagents]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY_TRANSACTIONS, JSON.stringify(transactions));
  }, [transactions]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY_NOTIFICATIONS, JSON.stringify(notifications));
  }, [notifications]);

  const showToast = (message: string, type: 'success' | 'alert' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 4000);
  };

  const handleTransaction = (reagent: Partial<Reagent>, transactionData: Omit<Transaction, 'id' | 'timestamp' | 'reagentName'>) => {
    const timestamp = new Date().toISOString();
    let updatedReagents = [...reagents];
    let reagentId = transactionData.reagentId;

    if (transactionData.type === 'IN') {
      const existingIdx = updatedReagents.findIndex(r => r.id === reagentId);
      if (existingIdx > -1) {
        const existing = updatedReagents[existingIdx];
        const rName = existing.name.toLowerCase();
        updatedReagents = updatedReagents.map(r => 
          r.name.toLowerCase() === rName 
            ? { ...r, isOrdered: false, ...(r.id === reagentId ? { 
                brand: reagent.brand || r.brand, 
                currentStock: r.currentStock + transactionData.quantity,
                lastUpdated: timestamp 
              } : {}) }
            : r
        );
      } else {
        const newReagent: Reagent = {
          id: reagentId || generateId(),
          name: reagent.name!,
          brand: reagent.brand!,
          presentation: reagent.presentation!,
          currentStock: transactionData.quantity,
          minStock: reagent.minStock || 0,
          department: reagent.department!,
          baseUnit: reagent.baseUnit || 'ud',
          containerType: reagent.containerType || 'Frasco',
          quantityPerContainer: reagent.quantityPerContainer || 1,
          expiryDate: reagent.expiryDate || 'N/A',
          isOrdered: false,
          lastUpdated: timestamp
        };
        updatedReagents.push(newReagent);
        reagentId = newReagent.id;
      }
    } else {
      const existingIdx = updatedReagents.findIndex(r => r.id === reagentId);
      if (existingIdx > -1) {
        const existing = updatedReagents[existingIdx];
        const newStock = Math.max(0, existing.currentStock - transactionData.quantity);
        updatedReagents[existingIdx] = { ...existing, currentStock: newStock, lastUpdated: timestamp };

        // Lógica Mejorada de Alerta por Correo
        const consolidatedStock = updatedReagents
          .filter(r => r.name.toLowerCase() === existing.name.toLowerCase())
          .reduce((sum, r) => sum + r.currentStock, 0);

        if (consolidatedStock <= existing.minStock && managerEmail && !existing.isOrdered) {
          // Solo notificamos si no hay una notificación reciente (en los últimos 10 min) para este mismo reactivo
          const lastNotif = notifications.find(n => n.reagentName === existing.name);
          const minutesSinceLast = lastNotif ? (new Date().getTime() - new Date(lastNotif.timestamp).getTime()) / 60000 : 999;

          if (minutesSinceLast > 10) {
            const newNotif: NotificationLog = {
              id: generateId(),
              reagentName: existing.name,
              timestamp,
              targetEmail: managerEmail,
              stockLevel: `${consolidatedStock} ${existing.baseUnit}`
            };
            setNotifications(prev => [newNotif, ...prev].slice(0, 50));
            showToast(`Alerta enviada al correo: ${managerEmail}`, 'alert');
            console.log(`[ALERTA EMAIL REAL]: Para ${managerEmail} sobre ${existing.name}`);
          }
        }
      }
    }
    setReagents(updatedReagents);
    const newTransaction: Transaction = {
      ...transactionData,
      id: generateId(),
      reagentId: reagentId!,
      reagentName: updatedReagents.find(r => r.id === reagentId)?.name || 'Desconocido',
      timestamp
    };
    setTransactions([newTransaction, ...transactions]);
  };

  const updateMinStock = (reagentId: string, newMinStock: number) => {
    setReagents(prev => prev.map(r => r.id === reagentId ? { ...r, minStock: newMinStock } : r));
  };

  const markAsOrdered = (reagentId: string) => {
    const reagentToMark = reagents.find(r => r.id === reagentId);
    if (!reagentToMark) return;
    const rName = reagentToMark.name.toLowerCase();
    setReagents(prev => prev.map(r => 
      r.name.toLowerCase() === rName ? { ...r, isOrdered: true } : r
    ));
    showToast("Marcado como pedido correctamente");
  };

  const updateMgSettings = (pwd?: string, email?: string) => {
    if (pwd) {
      localStorage.setItem(STORAGE_KEY_MG_PASSWORD, pwd);
      setMgPassword(pwd);
    }
    if (email !== undefined) {
      localStorage.setItem(STORAGE_KEY_MG_EMAIL, email);
      setManagerEmail(email);
    }
  };

  const MobileNav = () => {
    const location = useLocation();
    const navItems = [
      { path: '/', icon: HomeIcon, label: 'Inicio' },
      { path: '/ingreso', icon: PlusCircleIcon, label: 'Entra' },
      { path: '/salida', icon: MinusCircleIcon, label: 'Sale' },
      { path: '/historial', icon: ClockIcon, label: 'Histo' },
      ...(role === 'GERENTE' ? [{ path: '/alertas', icon: BellAlertIcon, label: 'Alertas' }] : [])
    ];

    return (
      <div className="md:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-slate-200 flex justify-around items-center h-16 px-2 z-50">
        {navItems.map((item) => (
          <Link key={item.path} to={item.path} className={`flex flex-col items-center justify-center w-full h-full transition-colors ${location.pathname === item.path ? 'text-indigo-600' : 'text-slate-400'}`}>
            <item.icon className="w-6 h-6" />
            <span className="text-[10px] font-bold mt-1 uppercase tracking-tighter">{item.label}</span>
          </Link>
        ))}
      </div>
    );
  };

  if (!role) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-600 to-indigo-900 flex items-center justify-center p-4">
        <div className="bg-white rounded-3xl shadow-2xl p-6 md:p-10 w-full max-w-md text-center relative overflow-hidden">
          <BeakerIcon className="w-16 h-16 text-indigo-600 mx-auto mb-4" />
          <h1 className="text-3xl font-bold text-slate-800 mb-2">ReagentFlow</h1>
          <p className="text-slate-500 mb-8 font-medium italic">Control de Stock de Reactivos</p>
          <div className="space-y-4">
            <button 
              onClick={() => { setRole('ANALISTA'); }}
              className="w-full bg-slate-50 border-2 border-slate-200 hover:border-indigo-600 hover:text-indigo-600 text-slate-700 font-bold py-5 px-6 rounded-2xl transition-all flex items-center justify-between group"
            >
              <div className="flex items-center gap-3"><QueueListIcon className="w-6 h-6" /><span>Analista</span></div>
              <ChevronRightIcon className="w-5 h-5 opacity-50 group-hover:opacity-100" />
            </button>
            <button 
              onClick={() => { setPendingRole('GERENTE'); setShowAuthModal(true); setAuthInput(''); setAuthError(''); }}
              className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-5 px-6 rounded-2xl transition-all flex items-center justify-between group shadow-xl"
            >
              <div className="flex items-center gap-3"><BellAlertIcon className="w-6 h-6" /><span>Gerente</span></div>
              <ChevronRightIcon className="w-5 h-5 opacity-50 group-hover:opacity-100" />
            </button>
          </div>
          <div className="mt-10 text-[10px] text-slate-400 uppercase tracking-widest font-black">Ready for Mobile & Tablet</div>
        </div>

        {showAuthModal && (
          <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/70 backdrop-blur-sm">
            <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm overflow-hidden animate-in fade-in zoom-in-95 duration-200">
              <div className="bg-slate-50 p-6 border-b border-slate-100 flex items-center gap-3">
                <div className="p-2 bg-indigo-100 rounded-lg"><LockClosedIcon className="w-6 h-6 text-indigo-600" /></div>
                <div>
                  <h3 className="font-bold text-slate-800">Acceso Gerente</h3>
                  <p className="text-xs text-slate-500">{!mgPassword ? 'Cree su clave maestra' : 'Ingrese clave'}</p>
                </div>
              </div>
              <form onSubmit={(e) => {
                e.preventDefault();
                if (pendingRole === 'GERENTE') {
                  if (!mgPassword) {
                    if (authInput.length < 4) { setAuthError('Mínimo 4 caracteres'); return; }
                    updateMgSettings(authInput);
                    setRole('GERENTE'); setShowAuthModal(false);
                  } else if (authInput === mgPassword) {
                    setRole('GERENTE'); setShowAuthModal(false);
                  } else { setAuthError('Clave incorrecta'); }
                }
              }} className="p-6 space-y-4">
                <input autoFocus type={showPassword ? "text" : "password"} placeholder="****"
                  className="w-full px-4 py-4 bg-slate-50 border-2 border-slate-200 rounded-xl outline-none focus:border-indigo-500 transition-all text-center text-2xl tracking-widest font-bold"
                  value={authInput} onChange={(e) => setAuthInput(e.target.value)} />
                {authError && <p className="text-red-600 text-xs font-bold text-center">{authError}</p>}
                <div className="flex gap-3 pt-2">
                  <button type="button" onClick={() => setShowAuthModal(false)} className="flex-1 py-3 text-slate-500 font-bold hover:bg-slate-100 rounded-xl">Cerrar</button>
                  <button type="submit" className="flex-[2] bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 rounded-xl shadow-lg">Entrar</button>
                </div>
              </form>
            </div>
          </div>
        )}
      </div>
    );
  }

  return (
    <Router>
      <div className="flex flex-col min-h-screen bg-slate-50 pb-20 md:pb-0">
        {/* Toast Notification */}
        {toast && (
