import React, { useMemo } from 'react';
import { Reagent } from '../types';
import { formatDate, formatDateTime } from '../utils';
import { 
  BellAlertIcon, 
  ShoppingBagIcon, 
  CheckCircleIcon,
  ExclamationCircleIcon,
  EnvelopeIcon,
  ClockIcon
} from '@heroicons/react/24/solid';

interface Props {
  reagents: Reagent[];
  markAsOrdered: (id: string) => void;
  onUpdateMinStock: (id: string, newMin: number) => void;
  notifications: any[];
}

const AlertsView: React.FC<Props> = ({ reagents, markAsOrdered, onUpdateMinStock, notifications }) => {
  const alertsData = useMemo(() => {
    const consolidated: Record<string, {
      name: string;
      totalStock: number;
      minStock: number;
      baseUnit: string;
      isOrdered: boolean;
      brands: { brand: string, stock: number, id: string }[];
    }> = {};

    reagents.forEach(r => {
      const key = r.name.toLowerCase();
      if (!consolidated[key]) {
        consolidated[key] = {
          name: r.name,
          totalStock: r.currentStock,
          minStock: r.minStock,
          baseUnit: r.baseUnit,
          isOrdered: r.isOrdered,
          brands: [{ brand: r.brand, stock: r.currentStock, id: r.id }]
        };
      } else {
        consolidated[key].totalStock += r.currentStock;
        consolidated[key].brands.push({ brand: r.brand, stock: r.currentStock, id: r.id });
        consolidated[key].minStock = Math.max(consolidated[key].minStock, r.minStock);
        if (r.isOrdered) consolidated[key].isOrdered = true;
      }
    });

    const lowStock = Object.values(consolidated).filter(c => c.totalStock <= c.minStock && !c.isOrdered);
    return { lowStock };
  }, [reagents]);

  return (
    <div className="space-y-12 pb-10">
      <div className="bg-red-50 border-l-4 border-red-500 p-6 rounded-r-3xl shadow-sm">
        <div className="flex items-center gap-3 mb-2">
          <BellAlertIcon className="w-8 h-8 text-red-600" />
          <h1 className="text-2xl font-bold text-red-900 uppercase tracking-tighter">Panel de Gestión Crítica</h1>
        </div>
        <p className="text-red-700 font-medium">Reactivos por debajo del stock mínimo. Las alertas se envían automáticamente al correo configurado.</p>
      </div>

      <section className="space-y-6">
        <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2 px-1">
          <ExclamationCircleIcon className="w-5 h-5 text-red-600" />
          Pendientes de Pedido ({alertsData.lowStock.length})
        </h2>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {alertsData.lowStock.length > 0 ? (
            alertsData.lowStock.map(group => (
              <div key={group.name} className="bg-white rounded-3xl shadow-sm border border-red-100 overflow-hidden group hover:shadow-md transition-all">
                <div className="p-6">
                  <div className="flex justify-between items-start mb-4">
                    <div className="max-w-[70%]">
                      <h3 className="font-bold text-slate-800 text-lg leading-tight">{group.name}</h3>
                      <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">Acción Pendiente</p>
                    </div>
                    <span className="bg-red-50 text-red-600 text-[10px] font-black px-3 py-1 rounded-full uppercase border border-red-100">Crítico</span>
                  </div>

                  <div className="space-y-4 mb-6">
                    <div className="flex justify-between items-end">
                      <span className="text-xs font-bold text-slate-500">Stock Consolidado:</span>
                      <span className="font-black text-red-600 text-xl leading-none">{group.totalStock} <span className="text-xs uppercase">{group.baseUnit}</span></span>
                    </div>

                    <div className="bg-slate-50 p-3 rounded-2xl border border-slate-100 space-y-2">
                      <p className="text-[9px] text-slate-400 font-black uppercase flex items-center gap-1">
                        <ShoppingBagIcon className="w-3 h-3" />
                        Existencias por Marca
                      </p>
                      <div className="max-h-24 overflow-y-auto scrollbar-hide space-y-1">
                        {group.brands.map((b, idx) => (
                          <div key={idx} className="flex justify-between text-[11px] font-medium text-slate-600 bg-white p-2 rounded-lg border border-slate-100">
                            <span className="truncate mr-2">{b.brand}</span>
                            <span className="font-bold whitespace-nowrap text-slate-800">{b.stock}{group.baseUnit}</span>
                          </div>
                        ))}
                      </div>
                    </div>

                    <div className="h-2 w-full bg-slate-100 rounded-full overflow-hidden">
                      <div 
                        className="h-full bg-red-500 transition-all duration-1000" 
                        style={{ width: `${Math.max(10, Math.min(100, (group.totalStock / group.minStock) * 100))}%` }}
                      ></div>
                    </div>
                  </div>

                  <button 
                    onClick={() => group.brands.length > 0 && markAsOrdered(group.brands[0].id)}
                    className="w-full flex items-center justify-center gap-3 bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-4 rounded-2xl transition-all shadow-lg shadow-indigo-100 active:scale-95"
                  >
                    <ShoppingBagIcon className="w-5 h-5" />
                    Marcar como Pedido
                  </button>
                </div>
              </div>
            ))
          ) : (
            <div className="col-span-full py-16 text-center bg-white rounded-3xl border-2 border-dashed border-slate-200">
              <CheckCircleIcon className="w-16 h-16 text-emerald-500 mx-auto mb-4" />
              <p className="text-slate-800 font-black text-xl">Inventario Seguro</p>
              <p className="text-slate-500 text-sm mt-1">Todos los reactivos están por encima del stock mínimo.</p>
            </div>
          )}
        </div>
      </section>

      {/* Historial de Notificaciones Enviadas */}
      <section className="space-y-6 pt-6">
        <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2 px-1">
          <EnvelopeIcon className="w-5 h-5 text-indigo-500" />
          Historial de Alertas Enviadas al Correo
        </h2>

        <div className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
          {notifications.length > 0 ? (
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-slate-50 border-b border-slate-200">
                  <tr>
                    <th className="px-6 py-4 text-[10px] font-black text-slate-500 uppercase">Fecha y Hora</th>
                    <th className="px-6 py-4 text-[10px] font-black text-slate-500 uppercase">Reactivo</th>
                    <th className="px-6 py-4 text-[10px] font-black text-slate-500 uppercase">Destinatario</th>
                    <th className="px-6 py-4 text-[10px] font-black text-slate-500 uppercase">Estado al enviar</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {notifications.map((n) => (
                    <tr key={n.id} className="text-sm">
                      <td className="px-6 py-4 whitespace-nowrap text-slate-500 font-medium">
                        <div className="flex items-center gap-2">
                          <ClockIcon className="w-4 h-4 text-slate-300" />
                          {formatDateTime(n.timestamp)}
                        </div>
                      </td>
                      <td className="px-6 py-4 font-bold text-slate-800">{n.reagentName}</td>
                      <td className="px-6 py-4 text-indigo-600 font-medium">{n.targetEmail}</td>
                      <td className="px-6 py-4">
                        <span className="px-2 py-0.5 bg-red-50 text-red-700 rounded-md font-bold text-[10px] border border-red-100">
                          {n.stockLevel}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : (
            <div className="p-10 text-center text-slate-400 italic">
              No hay registro de alertas enviadas recientemente.
            </div>
          )}
        </div>
      </section>
    </div>
  );
};

export default AlertsView;

import React, { useState, useEffect, useMemo } from 'react';
import { HashRouter as Router, Routes, Route, Link, Navigate, useLocation } from 'react-router-dom';
import emailjs from '@emailjs/browser';
import { 
  BeakerIcon, 
  QueueListIcon, 
  BellAlertIcon, 
  PlusCircleIcon, 
  MinusCircleIcon,
  UserCircleIcon,
  ArrowRightOnRectangleIcon,
  HomeIcon,
  ChevronRightIcon,
  LockClosedIcon,
  EyeIcon,
  EyeSlashIcon,
  Cog6ToothIcon,
  ClockIcon,
  CheckBadgeIcon,
  EnvelopeIcon
} from '@heroicons/react/24/outline';

import { Reagent, Transaction, UserRole, Department } from './types';
import InventoryView from './components/InventoryView';
import InputForm from './components/InputForm';
import OutputForm from './components/OutputForm';
import HistoryView from './components/HistoryView';
import AlertsView from './components/AlertsView';
import ConfigView from './components/ConfigView';
import { generateId } from './utils';

const STORAGE_KEY_REAGENTS = 'reagentflow_inventory';
const STORAGE_KEY_TRANSACTIONS = 'reagentflow_transactions';
const STORAGE_KEY_NOTIFICATIONS = 'reagentflow_notifications';
const STORAGE_KEY_MG_PASSWORD = 'reagentflow_mg_pwd';
const STORAGE_KEY_MG_EMAIL = 'reagentflow_mg_email';

// CONFIGURACIÓN EMAILJS (El usuario debe completar esto en su cuenta de emailjs.com)
const EMAILJS_SERVICE_ID = "default_service"; // Cambiar por tu Service ID
const EMAILJS_TEMPLATE_ID = "template_reagent_alert"; // Cambiar por tu Template ID
const EMAILJS_PUBLIC_KEY = "YOUR_PUBLIC_KEY"; // Cambiar por tu Public Key

interface NotificationLog {
  id: string;
  reagentName: string;
  timestamp: string;
  targetEmail: string;
  stockLevel: string;
  status: 'SENT' | 'FAILED' | 'PENDING';
}

const App: React.FC = () => {
  const [role, setRole] = useState<UserRole | null>(null);
  const [reagents, setReagents] = useState<Reagent[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [notifications, setNotifications] = useState<NotificationLog[]>([]);
  const [managerEmail, setManagerEmail] = useState<string>(localStorage.getItem(STORAGE_KEY_MG_EMAIL) || '');
  const [toast, setToast] = useState<{message: string, type: 'success' | 'alert' | 'error'} | null>(null);

  // Auth state
  const [pendingRole, setPendingRole] = useState<UserRole | null>(null);
  const [showAuthModal, setShowAuthModal] = useState(false);
  const [mgPassword, setMgPassword] = useState<string | null>(localStorage.getItem(STORAGE_KEY_MG_PASSWORD));

  const [authInput, setAuthInput] = useState('');
  const [authError, setAuthError] = useState('');
  const [showPassword, setShowPassword] = useState(false);

  // Inicializar EmailJS al cargar
  useEffect(() => {
    if (EMAILJS_PUBLIC_KEY !== "YOUR_PUBLIC_KEY") {
      emailjs.init(EMAILJS_PUBLIC_KEY);
    }
  }, []);

  // Carga inicial de datos persistentes
  useEffect(() => {
    const savedReagents = localStorage.getItem(STORAGE_KEY_REAGENTS);
    const savedTransactions = localStorage.getItem(STORAGE_KEY_TRANSACTIONS);
    const savedNotifs = localStorage.getItem(STORAGE_KEY_NOTIFICATIONS);
    if (savedReagents) setReagents(JSON.parse(savedReagents));
    if (savedTransactions) setTransactions(JSON.parse(savedTransactions));
    if (savedNotifs) setNotifications(JSON.parse(savedNotifs));
  }, []);

  // Sincronización con LocalStorage
  useEffect(() => { localStorage.setItem(STORAGE_KEY_REAGENTS, JSON.stringify(reagents)); }, [reagents]);
  useEffect(() => { localStorage.setItem(STORAGE_KEY_TRANSACTIONS, JSON.stringify(transactions)); }, [transactions]);
  useEffect(() => { localStorage.setItem(STORAGE_KEY_NOTIFICATIONS, JSON.stringify(notifications)); }, [notifications]);

  const showToast = (message: string, type: 'success' | 'alert' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 4000);
  };

  const sendEmailAlert = async (reagent: Reagent, stock: number) => {
    if (!managerEmail || EMAILJS_PUBLIC_KEY === "YOUR_PUBLIC_KEY") return 'PENDING';

    try {
      const templateParams = {
        to_email: managerEmail,
        reagent_name: reagent.name,
        brand: reagent.brand,
        current_stock: `${stock} ${reagent.baseUnit}`,
        min_stock: `${reagent.minStock} ${reagent.baseUnit}`,
        department: reagent.department,
        timestamp: new Date().toLocaleString()
      };

      await emailjs.send(EMAILJS_SERVICE_ID, EMAILJS_TEMPLATE_ID, templateParams);
      return 'SENT';
    } catch (error) {
      console.error("Error enviando email via EmailJS:", error);
      return 'FAILED';
    }
  };

  const handleTransaction = async (reagent: Partial<Reagent>, transactionData: Omit<Transaction, 'id' | 'timestamp' | 'reagentName'>) => {
    const timestamp = new Date().toISOString();
    let updatedReagents = [...reagents];
    let reagentId = transactionData.reagentId;

    if (transactionData.type === 'IN') {
      const existingIdx = updatedReagents.findIndex(r => r.id === reagentId);
      if (existingIdx > -1) {
        const existing = updatedReagents[existingIdx];
        const rName = existing.name.toLowerCase();
        updatedReagents = updatedReagents.map(r => 
          r.name.toLowerCase() === rName 
            ? { ...r, isOrdered: false, ...(r.id === reagentId ? { 
                brand: reagent.brand || r.brand, 
                currentStock: r.currentStock + transactionData.quantity,
                lastUpdated: timestamp 
              } : {}) }
            : r
        );
      } else {
        const newReagent: Reagent = {
          id: reagentId || generateId(),
          name: reagent.name!,
          brand: reagent.brand!,
          presentation: reagent.presentation!,
          currentStock: transactionData.quantity,
          minStock: reagent.minStock || 0,
          department: reagent.department!,
          baseUnit: reagent.baseUnit || 'ud',
          containerType: reagent.containerType || 'Frasco',
          quantityPerContainer: reagent.quantityPerContainer || 1,
          expiryDate: reagent.expiryDate || 'N/A',
          isOrdered: false,
          lastUpdated: timestamp
        };
        updatedReagents.push(newReagent);
        reagentId = newReagent.id;
      }
      showToast("Ingreso registrado correctamente", "success");
    } else {
      const existingIdx = updatedReagents.findIndex(r => r.id === reagentId);
      if (existingIdx > -1) {
        const existing = updatedReagents[existingIdx];
        const newStock = Math.max(0, existing.currentStock - transactionData.quantity);
        updatedReagents[existingIdx] = { ...existing, currentStock: newStock, lastUpdated: timestamp };

        const consolidatedStock = updatedReagents
          .filter(r => r.name.toLowerCase() === existing.name.toLowerCase())
          .reduce((sum, r) => sum + r.currentStock, 0);

        if (consolidatedStock <= existing.minStock && managerEmail && !existing.isOrdered) {
          const lastNotif = notifications.find(n => n.reagentName === existing.name);
          const minutesSinceLast = lastNotif ? (new Date().getTime() - new Date(lastNotif.timestamp).getTime()) / 60000 : 999;

          if (minutesSinceLast > 15) { // Evitar spam: 1 alerta cada 15 min por reactivo
            showToast(`Enviando alerta a ${managerEmail}...`, 'alert');

            const emailStatus = await sendEmailAlert(existing, consolidatedStock);

            const newNotif: NotificationLog = {
              id: generateId(),
              reagentName: existing.name,
              timestamp,
              targetEmail: managerEmail,
              stockLevel: `${consolidatedStock} ${existing.baseUnit}`,
              status: emailStatus
            };
            setNotifications(prev => [newNotif, ...prev].slice(0, 50));

            if (emailStatus === 'SENT') showToast("Alerta enviada exitosamente", "success");
            else if (emailStatus === 'FAILED') showToast("Fallo al enviar correo. Ver consola.", "error");
          }
        }
      }
      showToast("Salida registrada", "success");
    }

    setReagents(updatedReagents);
    const newTransaction: Transaction = {
      ...transactionData,
      id: generateId(),
      reagentId: reagentId!,
      reagentName: updatedReagents.find(r => r.id === reagentId)?.name || 'Desconocido',
      timestamp
    };
    setTransactions([newTransaction, ...transactions]);
  };

  const updateMinStock = (reagentId: string, newMinStock: number) => {
    setReagents(prev => prev.map(r => r.id === reagentId ? { ...r, minStock: newMinStock } : r));
  };

  const markAsOrdered = (reagentId: string) => {
    const reagentToMark = reagents.find(r => r.id === reagentId);
    if (!reagentToMark) return;
    const rName = reagentToMark.name.toLowerCase();
    setReagents(prev => prev.map(r => 
      r.name.toLowerCase() === rName ? { ...r, isOrdered: true } : r
    ));
    showToast("Pedido registrado");
  };

  const updateMgSettings = (pwd?: string, email?: string) => {
    if (pwd) { localStorage.setItem(STORAGE_KEY_MG_PASSWORD, pwd); setMgPassword(pwd); }
    if (email !== undefined) { localStorage.setItem(STORAGE_KEY_MG_EMAIL, email); setManagerEmail(email); }
  };

  const MobileNav = () => {
    const location = useLocation();
    const navItems = [
      { path: '/', icon: HomeIcon, label: 'Inicio' },
      { path: '/ingreso', icon: PlusCircleIcon, label: 'Entra' },
      { path: '/salida', icon: MinusCircleIcon, label: 'Sale' },
      { path: '/historial', icon: ClockIcon, label: 'Histo' },
      ...(role === 'GERENTE' ? [{ path: '/alertas', icon: BellAlertIcon, label: 'Alertas' }] : [])
    ];
    return (
      <div className="md:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-slate-200 flex justify-around items-center h-16 px-2 z-50">
        {navItems.map((item) => (
          <Link key={item.path} to={item.path} className={`flex flex-col items-center justify-center w-full h-full transition-colors ${location.pathname === item.path ? 'text-indigo-600' : 'text-slate-400'}`}>
            <item.icon className="w-6 h-6" />
            <span className="text-[10px] font-bold mt-1 uppercase tracking-tighter">{item.label}</span>
          </Link>
        ))}
      </div>
    );
  };

  if (!role) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-600 to-indigo-900 flex items-center justify-center p-4">
        <div className="bg-white rounded-3xl shadow-2xl p-6 md:p-10 w-full max-w-md text-center relative overflow-hidden">
          <BeakerIcon className="w-16 h-16 text-indigo-600 mx-auto mb-4" />
          <h1 className="text-3xl font-bold text-slate-800 mb-2">ReagentFlow</h1>
          <p className="text-slate-500 mb-8 font-medium italic">Gestión de Stock Profesional</p>
          <div className="space-y-4">
            <button onClick={() => setRole('ANALISTA')} className="w-full bg-slate-50 border-2 border-slate-200 hover:border-indigo-600 hover:text-indigo-600 text-slate-700 font-bold py-5 px-6 rounded-2xl transition-all flex items-center justify-between group">
              <div className="flex items-center gap-3"><QueueListIcon className="w-6 h-6" /><span>Analista</span></div>
              <ChevronRightIcon className="w-5 h-5 opacity-50 group-hover:opacity-100" />
            </button>
            <button onClick={() => { setPendingRole('GERENTE'); setShowAuthModal(true); setAuthInput(''); setAuthError(''); }} className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-5 px-6 rounded-2xl transition-all flex items-center justify-between group shadow-xl">
              <div className="flex items-center gap-3"><BellAlertIcon className="w-6 h-6" /><span>Gerente</span></div>
              <ChevronRightIcon className="w-5 h-5 opacity-50 group-hover:opacity-100" />
            </button>
          </div>
        </div>

        {showAuthModal && (
          <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/70 backdrop-blur-sm">
            <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm overflow-hidden animate-in fade-in zoom-in-95 duration-200">
              <div className="bg-slate-50 p-6 border-b border-slate-100 flex items-center gap-3">
                <div className="p-2 bg-indigo-100 rounded-lg"><LockClosedIcon className="w-6 h-6 text-indigo-600" /></div>
