import React, { useState } from 'react';
import { LockClosedIcon, ShieldCheckIcon, EnvelopeIcon, BellIcon, UserPlusIcon, TrashIcon, UsersIcon } from '@heroicons/react/24/solid';

interface Props {
  updateMgSettings: (mg?: string, email?: string) => void;
