import React, { useState, useRef, useMemo } from 'react';
import { Reagent, Presentation, Department, Transaction } from '../types';
import { analyzeReagentLabel } from '../services/geminiService';
import { fileToBase64, generateId } from '../utils';
import { 
  CameraIcon, 
  SparklesIcon, 
  ArrowPathIcon,
  PlusIcon
} from '@heroicons/react/24/solid';

interface Props {
  reagents: Reagent[];
  analysts: string[];
  transactions: Transaction[];
  onTransaction: (reagent: Partial<Reagent>, data: any) => void;
}

const BASE_UNITS_LIQUID = ['mL', 'L'];
const BASE_UNITS_SOLID = ['g', 'kg'];
const BASE_UNITS_PKG = ['unidades'];

const InputForm: React.FC<Props> = ({ reagents, analysts, transactions, onTransaction }) => {
  const [loading, setLoading] = useState(false);
  const [isExisting, setIsExisting] = useState(false);
  const [selectedReagentId, setSelectedReagentId] = useState('');
  const [showNewUnitInput, setShowNewUnitInput] = useState(false);
  const [customUnit, setCustomUnit] = useState('');

  // Form State
  const [formData, setFormData] = useState({
    name: '',
    brand: '',
    presentation: 'Líquido' as Presentation,
    containerType: 'Frascos',
    quantityEntered: 0,
    quantityPerContainer: 1,
    baseUnit: 'mL',
    expiryDate: '',
    department: 'Fisicoquímico' as Department,
    analystName: '',
    minStock: 0
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  const unitsForPresentation = useMemo(() => {
    if (formData.presentation === 'Líquido') return BASE_UNITS_LIQUID;
    if (formData.presentation === 'Sólido') return BASE_UNITS_SOLID;
    return BASE_UNITS_PKG;
  }, [formData.presentation]);

  const totalBaseQuantity = useMemo(() => {
    return formData.quantityEntered * formData.quantityPerContainer;
  }, [formData.quantityEntered, formData.quantityPerContainer]);

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    try {
      const base64 = await fileToBase64(file);
      const analysis = await analyzeReagentLabel(base64);

      const newBaseUnit = analysis.presentation === 'Líquido' ? 'mL' : (analysis.presentation === 'Sólido' ? 'g' : 'unidades');

      setFormData(prev => ({
        ...prev,
        name: analysis.name || '',
        brand: analysis.brand || '',
        presentation: analysis.presentation || 'Líquido',
        baseUnit: newBaseUnit
      }));

      const existing = reagents.find(r => 
        r.name.toLowerCase() === analysis.name.toLowerCase() && 
        r.brand.toLowerCase() === analysis.brand.toLowerCase()
      );

      if (existing) {
        setIsExisting(true);
        setSelectedReagentId(existing.id);
        setFormData(prev => ({ 
          ...prev, 
          baseUnit: existing.baseUnit, 
          containerType: existing.containerType,
          quantityPerContainer: existing.quantityPerContainer,
          minStock: existing.minStock 
        }));
      } else {
        setIsExisting(false);
      }
    } catch (error) {
      alert("Error analizando la etiqueta.");
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.analystName) {
      alert("Debe seleccionar un analista responsable.");
      return;
    }

    const finalBaseUnit = showNewUnitInput ? customUnit : formData.baseUnit;
    const originalReagent = isExisting ? reagents.find(r => r.id === selectedReagentId) : null;
    const brandChanged = originalReagent && originalReagent.brand.toLowerCase() !== formData.brand.toLowerCase();
    const finalReagentId = (isExisting && !brandChanged) ? selectedReagentId : undefined;

    onTransaction(
      {
        id: finalReagentId,
        name: formData.name,
        brand: formData.brand,
        presentation: formData.presentation,
        department: formData.department,
        expiryDate: formData.expiryDate || 'N/A',
        minStock: formData.minStock,
        containerType: formData.containerType,
        quantityPerContainer: formData.quantityPerContainer,
        baseUnit: finalBaseUnit
      },
      {
        reagentId: finalReagentId,
        type: 'IN',
        quantity: totalBaseQuantity,
        displayQuantity: formData.quantityEntered,
        displayUnit: formData.containerType,
        analyst: formData.analystName
      }
    );

    setFormData({
      name: '', brand: '', presentation: 'Líquido', containerType: 'Frascos',
      quantityEntered: 0, quantityPerContainer: 1, baseUnit: 'mL', 
      expiryDate: '', department: 'Fisicoquímico', analystName: '', minStock: 0
    });
    setIsExisting(false);
    setSelectedReagentId('');
    setShowNewUnitInput(false);
    setCustomUnit('');
  };

  return (
    <div className="max-w-3xl mx-auto">
      <div className="bg-white rounded-3xl shadow-xl border border-slate-200 overflow-hidden">
        <div className="bg-indigo-600 p-6 text-white flex justify-between items-center">
          <div>
            <h2 className="text-xl font-bold">Registro de Ingreso</h2>
            <p className="text-indigo-100 text-sm">Complete los datos o use la cámara.</p>
          </div>
          <SparklesIcon className="w-8 h-8 opacity-40" />
        </div>

        <div className="p-8">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-8">
            <button 
              type="button"
              onClick={() => fileInputRef.current?.click()}
              disabled={loading}
              className="flex items-center justify-center gap-2 bg-indigo-50 hover:bg-indigo-100 text-indigo-700 py-4 px-4 rounded-2xl border border-indigo-200 font-bold transition-all"
            >
              {loading ? <ArrowPathIcon className="w-5 h-5 animate-spin" /> : <CameraIcon className="w-5 h-5" />}
              {loading ? "Escaneando..." : "Escanear Etiqueta"}
            </button>
            <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleImageUpload} />

            <select 
              className="bg-slate-50 border-2 border-slate-200 py-4 px-4 rounded-2xl text-slate-700 font-bold outline-none focus:border-indigo-500"
              value={isExisting ? selectedReagentId : 'new'}
              onChange={(e) => {
                const val = e.target.value;
                if (val === 'new') {
                  setIsExisting(false);
                  setSelectedReagentId('');
                  setFormData(prev => ({ ...prev, name: '', brand: '', minStock: 0 }));
                } else {
                  setIsExisting(true);
                  const r = reagents.find(x => x.id === val);
                  if(r) {
                    setSelectedReagentId(val);
                    setFormData(prev => ({
                      ...prev, name: r.name, brand: r.brand, presentation: r.presentation,
                      baseUnit: r.baseUnit, containerType: r.containerType, 
                      quantityPerContainer: r.quantityPerContainer, minStock: r.minStock
                    }));
                  }
                }
              }}
            >
              <option value="new">+ Nuevo Reactivo / Marca</option>
              {reagents.map(r => <option key={r.id} value={r.id}>{r.name} - {r.brand}</option>)}
            </select>
          </div>

          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Nombre</label>
                <input type="text" required disabled={isExisting} className="w-full px-4 py-3 bg-slate-50 border-2 border-slate-200 rounded-xl focus:border-indigo-500 outline-none disabled:opacity-60" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Marca</label>
                <input type="text" required className="w-full px-4 py-3 bg-slate-50 border-2 border-slate-200 rounded-xl focus:border-indigo-500 outline-none" value={formData.brand} onChange={e => setFormData({...formData, brand: e.target.value})} />
              </div>

              <div className="space-y-2">
                <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Tipo de Envase</label>
                <input type="text" required placeholder="Frascos, Botellas..." className="w-full px-4 py-3 bg-slate-50 border-2 border-slate-200 rounded-xl focus:border-indigo-500 outline-none" value={formData.containerType} onChange={e => setFormData({...formData, containerType: e.target.value})} />
              </div>

              <div className="space-y-2">
                <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Analista Responsable</label>
                <select 
                  required 
                  className="w-full px-4 py-3 bg-slate-50 border-2 border-slate-200 rounded-xl focus:border-indigo-500 outline-none font-bold text-slate-700"
                  value={formData.analystName} 
                  onChange={e => setFormData({...formData, analystName: e.target.value})}
                >
                  <option value="">-- Seleccionar Analista --</option>
                  {analysts.map((a, i) => <option key={i} value={a}>{a}</option>)}
                </select>
                {analysts.length === 0 && <p className="text-[10px] text-red-500 font-bold uppercase">No hay analistas registrados. Avise al gerente.</p>}
              </div>

              <div className="space-y-2">
                <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Cant. Envases</label>
                <input type="number" required min="1" className="w-full px-4 py-3 bg-slate-50 border-2 border-slate-200 rounded-xl focus:border-indigo-500 outline-none" value={formData.quantityEntered || ''} onChange={e => setFormData({...formData, quantityEntered: parseInt(e.target.value) || 0})} />
              </div>

              <div className="space-y-2">
                <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Contenido por Envase</label>
                <div className="flex gap-2">
                  <input type="number" required step="0.01" className="flex-grow px-4 py-3 bg-slate-50 border-2 border-slate-200 rounded-xl focus:border-indigo-500 outline-none" value={formData.quantityPerContainer || ''} onChange={e => setFormData({...formData, quantityPerContainer: parseFloat(e.target.value) || 0})} />
                  <select className="w-24 border-2 border-slate-200 rounded-xl bg-slate-100 px-2 outline-none font-bold" value={formData.baseUnit} onChange={e => setFormData({...formData, baseUnit: e.target.value})}>
                    {unitsForPresentation.map(u => <option key={u} value={u}>{u}</option>)}
                  </select>
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Stock Mínimo ({formData.baseUnit})</label>
                <input type="number" required min="0" step="0.01" className="w-full px-4 py-3 bg-slate-50 border-2 border-slate-200 rounded-xl focus:border-indigo-500 outline-none" value={formData.minStock || ''} onChange={e => setFormData({...formData, minStock: parseFloat(e.target.value) || 0})} />
              </div>

              <div className="space-y-2">
                <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Departamento</label>
                <select className="w-full px-4 py-3 bg-slate-50 border-2 border-slate-200 rounded-xl focus:border-indigo-500 outline-none font-bold" value={formData.department} onChange={e => setFormData({...formData, department: e.target.value as Department})}>
                  <option value="Fisicoquímico">Fisicoquímico</option>
                  <option value="Microbiología">Microbiología</option>
                  <option value="Molecular">Molecular</option>
                </select>
              </div>
            </div>

            <button type="submit" className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-black py-5 rounded-2xl shadow-xl transition-all active:scale-[0.98] uppercase tracking-widest">
              Confirmar Ingreso
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

export default InputForm;

import React, { useState, useRef, useMemo } from 'react';
import { Reagent, Transaction } from '../types';
import { analyzeReagentLabel } from '../services/geminiService';
import { fileToBase64 } from '../utils';
import { 
  CameraIcon, 
  ArrowPathIcon,
  MinusCircleIcon,
  ExclamationTriangleIcon
} from '@heroicons/react/24/solid';

interface Props {
  reagents: Reagent[];
  analysts: string[];
  onTransaction: (reagent: Partial<Reagent>, data: any) => void;
}

const OutputForm: React.FC<Props> = ({ reagents, analysts, onTransaction }) => {
  const [loading, setLoading] = useState(false);
  const [selectedReagentId, setSelectedReagentId] = useState('');
  const [outputMode, setOutputMode] = useState<'CONTAINER' | 'QUANTITY'>('CONTAINER');
  const [formData, setFormData] = useState({
    containers: 0,
    amount: 0,
    analystName: '',
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  const selectedReagent = useMemo(() => reagents.find(r => r.id === selectedReagentId), [reagents, selectedReagentId]);

  const totalAmountToWithdraw = useMemo(() => {
    if (!selectedReagent) return 0;
    return outputMode === 'CONTAINER' 
      ? formData.containers * selectedReagent.quantityPerContainer 
      : formData.amount;
  }, [outputMode, formData, selectedReagent]);

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setLoading(true);
    try {
      const base64 = await fileToBase64(file);
      const analysis = await analyzeReagentLabel(base64);
      const found = reagents.find(r => r.name.toLowerCase().includes(analysis.name.toLowerCase()) || analysis.name.toLowerCase().includes(r.name.toLowerCase()));
      if (found) setSelectedReagentId(found.id);
      else alert("Reactivo no encontrado.");
    } catch (error) { alert("Error al analizar."); } finally { setLoading(false); }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedReagent) return;
    if (!formData.analystName) {
      alert("Seleccione un analista.");
      return;
    }
    if (totalAmountToWithdraw > selectedReagent.currentStock) {
      alert("No hay suficiente stock.");
      return;
    }

    onTransaction({}, {
      reagentId: selectedReagentId,
      type: 'OUT',
      quantity: totalAmountToWithdraw,
      displayQuantity: outputMode === 'CONTAINER' ? formData.containers : formData.amount,
      displayUnit: outputMode === 'CONTAINER' ? selectedReagent.containerType : selectedReagent.baseUnit,
      analyst: formData.analystName
    });

    setSelectedReagentId('');
    setFormData({ containers: 0, amount: 0, analystName: '' });
  };

  return (
    <div className="max-w-3xl mx-auto">
      <div className="bg-white rounded-3xl shadow-xl border border-slate-200 overflow-hidden">
        <div className="bg-rose-600 p-6 text-white flex justify-between items-center">
          <div>
            <h2 className="text-xl font-bold">Registro de Egreso / Uso</h2>
            <p className="text-rose-100 text-sm">Seleccione el reactivo y el analista responsable.</p>
          </div>
          <MinusCircleIcon className="w-8 h-8 opacity-40" />
        </div>

        <div className="p-8">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-8">
            <button type="button" onClick={() => fileInputRef.current?.click()} disabled={loading} className="flex items-center justify-center gap-2 bg-rose-50 hover:bg-rose-100 text-rose-700 py-4 px-4 rounded-2xl border border-rose-200 font-bold transition-all">
              {loading ? <ArrowPathIcon className="w-5 h-5 animate-spin" /> : <CameraIcon className="w-5 h-5" />}
              {loading ? "Buscando..." : "Escanear Envase"}
            </button>
            <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleImageUpload} />

            <select className="bg-slate-50 border-2 border-slate-200 py-4 px-4 rounded-2xl text-slate-700 font-bold outline-none focus:border-rose-500" value={selectedReagentId} onChange={(e) => setSelectedReagentId(e.target.value)}>
              <option value="">-- Seleccionar Reactivo --</option>
              {reagents.map(r => <option key={r.id} value={r.id}>{r.name} ({r.currentStock} {r.baseUnit} disp.)</option>)}
            </select>
          </div>

          {selectedReagent && (
            <form onSubmit={handleSubmit} className="space-y-6">
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4 p-5 bg-slate-50 rounded-2xl border border-slate-200">
                <div className="text-center">
                  <p className="text-[10px] uppercase text-slate-400 font-black tracking-widest">Disponible</p>
                  <p className="font-bold text-slate-800">{selectedReagent.currentStock} {selectedReagent.baseUnit}</p>
                </div>
                <div className="text-center border-l border-slate-200">
                  <p className="text-[10px] uppercase text-slate-400 font-black tracking-widest">Envase</p>
                  <p className="font-bold text-slate-800">{selectedReagent.containerType}</p>
                </div>
                <div className="text-center border-l border-slate-200">
                  <p className="text-[10px] uppercase text-slate-400 font-black tracking-widest">Contenido</p>
                  <p className="font-bold text-slate-800">{selectedReagent.quantityPerContainer}{selectedReagent.baseUnit}</p>
                </div>
                <div className="text-center border-l border-slate-200">
                  <p className="text-[10px] uppercase text-slate-400 font-black tracking-widest">Equiv.</p>
                  <p className="font-bold text-rose-600">{(selectedReagent.currentStock / selectedReagent.quantityPerContainer).toFixed(1)} ud.</p>
                </div>
              </div>

              <div className="flex bg-slate-100 p-1 rounded-2xl">
                 <button type="button" onClick={() => setOutputMode('CONTAINER')} className={`flex-1 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${outputMode === 'CONTAINER' ? 'bg-white shadow text-rose-600' : 'text-slate-500'}`}>Por {selectedReagent.containerType}</button>
                 <button type="button" onClick={() => setOutputMode('QUANTITY')} className={`flex-1 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${outputMode === 'QUANTITY' ? 'bg-white shadow text-rose-600' : 'text-slate-500'}`}>Por Medida ({selectedReagent.baseUnit})</button>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Cantidad a Retirar</label>
                  <div className="relative">
                    {outputMode === 'CONTAINER' ? (
                      <input type="number" required min="1" className="w-full pl-4 pr-24 py-4 bg-slate-50 border-2 border-slate-200 rounded-xl focus:border-rose-500 outline-none font-bold" value={formData.containers || ''} onChange={e => setFormData({...formData, containers: parseInt(e.target.value) || 0})} />
                    ) : (
                      <input type="number" required step="0.01" min="0.01" className="w-full pl-4 pr-24 py-4 bg-slate-50 border-2 border-slate-200 rounded-xl focus:border-rose-500 outline-none font-bold" value={formData.amount || ''} onChange={e => setFormData({...formData, amount: parseFloat(e.target.value) || 0})} />
                    )}
                    <span className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 font-black text-[10px] uppercase">
                      {outputMode === 'CONTAINER' ? selectedReagent.containerType : selectedReagent.baseUnit}
                    </span>
                  </div>
                  <p className="text-[10px] text-slate-400 font-bold uppercase">Consumo total: {totalAmountToWithdraw} {selectedReagent.baseUnit}</p>
                </div>

                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Analista Responsable</label>
                  <select 
                    required 
                    className="w-full px-4 py-4 bg-slate-50 border-2 border-slate-200 rounded-xl focus:border-rose-500 outline-none font-bold text-slate-700"
                    value={formData.analystName} 
                    onChange={e => setFormData({...formData, analystName: e.target.value})}
                  >
                    <option value="">-- Seleccionar --</option>
                    {analysts.map((a, i) => <option key={i} value={a}>{a}</option>)}
                  </select>
                </div>
              </div>

              {selectedReagent.currentStock - totalAmountToWithdraw <= selectedReagent.minStock && (
                <div className="bg-amber-50 p-4 rounded-2xl border border-amber-200 flex gap-3 animate-pulse"><ExclamationTriangleIcon className="w-6 h-6 text-amber-500 shrink-0" /><p className="text-[11px] text-amber-700 font-bold uppercase leading-tight">Aviso: El stock quedará en nivel crítico tras esta operación.</p></div>
              )}

              <button type="submit" className="w-full bg-rose-600 hover:bg-rose-700 text-white font-black py-5 rounded-2xl shadow-xl transition-all active:scale-[0.98] uppercase tracking-widest">Registrar Salida</button>
            </form>
          )}
        </div>
      </div>
    </div>
  );
};

export default OutputForm;

import React, { useState, useEffect, useMemo } from 'react';
import { HashRouter as Router, Routes, Route, Link, Navigate, useLocation } from 'react-router-dom';
import emailjs from '@emailjs/browser';
import { 
  BeakerIcon, 
  QueueListIcon, 
  BellAlertIcon, 
  PlusCircleIcon, 
  MinusCircleIcon,
  UserCircleIcon,
  ArrowRightOnRectangleIcon,
  HomeIcon,
  ChevronRightIcon,
  LockClosedIcon,
  EyeIcon,
  EyeSlashIcon,
  Cog6ToothIcon,
  ClockIcon,
  CheckBadgeIcon,
  EnvelopeIcon,
  CloudIcon,
  TableCellsIcon
} from '@heroicons/react/24/outline';

import { Reagent, Transaction, UserRole, Department } from './types';
import InventoryView from './components/InventoryView';
import InputForm from './components/InputForm';
import OutputForm from './components/OutputForm';
import HistoryView from './components/HistoryView';
import AlertsView from './components/AlertsView';
import ConfigView from './components/ConfigView';
import CloudSyncView from './components/CloudSyncView';
import { generateId } from './utils';

const STORAGE_KEY_REAGENTS = 'reagentflow_inventory';
const STORAGE_KEY_TRANSACTIONS = 'reagentflow_transactions';
const STORAGE_KEY_NOTIFICATIONS = 'reagentflow_notifications';
const STORAGE_KEY_ANALYSTS = 'reagentflow_analysts';
const STORAGE_KEY_MG_PASSWORD = 'reagentflow_mg_pwd';
const STORAGE_KEY_MG_EMAIL = 'reagentflow_mg_email';
const STORAGE_KEY_CLOUD_URL = 'reagentflow_cloud_url';

// CONFIGURACIÓN EMAILJS (MANTENIDA SEGÚN TU SOLICITUD)
const EMAILJS_SERVICE_ID = "controlreactivo_lab";
const EMAILJS_TEMPLATE_ID = "template_czefw4r";
const EMAILJS_PUBLIC_KEY = "aMH7yh-WaX5jjiRUm";

interface NotificationLog {
  id: string;
  reagentName: string;
  timestamp: string;
  targetEmail: string;
  stockLevel: string;
  status: 'SENT' | 'FAILED' | 'PENDING';
}

const App: React.FC = () => {
  const [role, setRole] = useState<UserRole | null>(null);
  const [reagents, setReagents] = useState<Reagent[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [notifications, setNotifications] = useState<NotificationLog[]>([]);
  const [analysts, setAnalysts] = useState<string[]>(JSON.parse(localStorage.getItem(STORAGE_KEY_ANALYSTS) || '[]'));
  const [managerEmail, setManagerEmail] = useState<string>(localStorage.getItem(STORAGE_KEY_MG_EMAIL) || '');
  const [cloudUrl, setCloudUrl] = useState<string>(localStorage.getItem(STORAGE_KEY_CLOUD_URL) || '');
  const [toast, setToast] = useState<{message: string, type: 'success' | 'alert' | 'error'} | null>(null);

  const [pendingRole, setPendingRole] = useState<UserRole | null>(null);
  const [showAuthModal, setShowAuthModal] = useState(false);
  const [mgPassword, setMgPassword] = useState<string | null>(localStorage.getItem(STORAGE_KEY_MG_PASSWORD));
  const [authInput, setAuthInput] = useState('');
  const [authError, setAuthError] = useState('');

  useEffect(() => {
    if (EMAILJS_PUBLIC_KEY) emailjs.init(EMAILJS_PUBLIC_KEY);
  }, []);

  useEffect(() => {
    const savedReagents = localStorage.getItem(STORAGE_KEY_REAGENTS);
    const savedTransactions = localStorage.getItem(STORAGE_KEY_TRANSACTIONS);
    const savedNotifs = localStorage.getItem(STORAGE_KEY_NOTIFICATIONS);
    if (savedReagents) setReagents(JSON.parse(savedReagents));
    if (savedTransactions) setTransactions(JSON.parse(savedTransactions));
    if (savedNotifs) setNotifications(JSON.parse(savedNotifs));
  }, []);

  useEffect(() => { localStorage.setItem(STORAGE_KEY_REAGENTS, JSON.stringify(reagents)); }, [reagents]);
  useEffect(() => { localStorage.setItem(STORAGE_KEY_TRANSACTIONS, JSON.stringify(transactions)); }, [transactions]);
  useEffect(() => { localStorage.setItem(STORAGE_KEY_NOTIFICATIONS, JSON.stringify(notifications)); }, [notifications]);
  useEffect(() => { localStorage.setItem(STORAGE_KEY_ANALYSTS, JSON.stringify(analysts)); }, [analysts]);
  useEffect(() => { localStorage.setItem(STORAGE_KEY_CLOUD_URL, cloudUrl); }, [cloudUrl]);

  const showToast = (message: string, type: 'success' | 'alert' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 4000);
  };

  const syncToCloud = async (data: any) => {
    if (!cloudUrl) return;
    try {
      await fetch(cloudUrl, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(data)
      });
      console.log("Sincronización con nube completada");
    } catch (e) {
      console.error("Error en sincronización nube:", e);
    }
  };

  const handleTransaction = async (reagent: Partial<Reagent>, transactionData: Omit<Transaction, 'id' | 'timestamp' | 'reagentName'>) => {
    const timestamp = new Date().toISOString();
    let updatedReagents = [...reagents];
    let reagentId = transactionData.reagentId;

    if (transactionData.type === 'IN') {
      const existingIdx = updatedReagents.findIndex(r => r.id === reagentId);
      if (existingIdx > -1) {
        const existing = updatedReagents[existingIdx];
        updatedReagents = updatedReagents.map(r => 
          r.name.toLowerCase() === existing.name.toLowerCase() 
            ? { ...r, isOrdered: false, ...(r.id === reagentId ? { 
                brand: reagent.brand || r.brand, 
                currentStock: r.currentStock + transactionData.quantity,
                lastUpdated: timestamp 
              } : {}) }
            : r
        );
      } else {
        const newReagent: Reagent = {
          id: reagentId || generateId(),
          name: reagent.name!,
          brand: reagent.brand!,
          presentation: reagent.presentation!,
          currentStock: transactionData.quantity,
          minStock: reagent.minStock || 0,
          department: reagent.department!,
          baseUnit: reagent.baseUnit || 'ud',
          containerType: reagent.containerType || 'Frasco',
          quantityPerContainer: reagent.quantityPerContainer || 1,
          expiryDate: reagent.expiryDate || 'N/A',
          isOrdered: false,
          lastUpdated: timestamp
        };
        updatedReagents.push(newReagent);
        reagentId = newReagent.id;
      }
      showToast("Ingreso registrado correctamente", "success");
    } else {
      const existingIdx = updatedReagents.findIndex(r => r.id === reagentId);
      if (existingIdx > -1) {
        const existing = updatedReagents[existingIdx];
        const newStock = Math.max(0, existing.currentStock - transactionData.quantity);
        updatedReagents[existingIdx] = { ...existing, currentStock: newStock, lastUpdated: timestamp };

        const consolidatedStock = updatedReagents
          .filter(r => r.name.toLowerCase() === existing.name.toLowerCase())
          .reduce((sum, r) => sum + r.currentStock, 0);

        if (consolidatedStock <= existing.minStock && managerEmail && !existing.isOrdered) {
          const lastNotif = notifications.find(n => n.reagentName === existing.name);
          const minutesSinceLast = lastNotif ? (new Date().getTime() - new Date(lastNotif.timestamp).getTime()) / 60000 : 999;
          if (minutesSinceLast > 15) {
            showToast(`Enviando alerta a ${managerEmail}...`, 'alert');
            const emailStatus = await (async () => {
              if (!managerEmail) return 'PENDING' as const;
              try {
                const templateParams = {
                  to_email: managerEmail,
                  reagent_name: existing.name,
                  brand: existing.brand,
                  current_stock: `${consolidatedStock} ${existing.baseUnit}`,
                  min_stock: `${existing.minStock} ${existing.baseUnit}`,
                  department: existing.department,
                  timestamp: new Date().toLocaleString()
                };
                await emailjs.send(EMAILJS_SERVICE_ID, EMAILJS_TEMPLATE_ID, templateParams);
                return 'SENT' as const;
              } catch (error) { return 'FAILED' as const; }
            })();
            const newNotif: NotificationLog = {
              id: generateId(), reagentName: existing.name, timestamp, targetEmail: managerEmail,
              stockLevel: `${consolidatedStock} ${existing.baseUnit}`, status: emailStatus
            };
            setNotifications(prev => [newNotif, ...prev].slice(0, 50));
            if (emailStatus === 'SENT') showToast("Alerta enviada exitosamente", "success");
          }
        }
      }
      showToast("Salida registrada", "success");
    }

    setReagents(updatedReagents);
    const newTransaction: Transaction = {
      ...transactionData,
      id: generateId(),
      reagentId: reagentId!,
      reagentName: updatedReagents.find(r => r.id === reagentId)?.name || 'Desconocido',
      timestamp
    };
    setTransactions([newTransaction, ...transactions]);

    // Sincronizar con Nube si está configurado
    if (cloudUrl) {
      syncToCloud({
        ...newTransaction,
        timestamp: new Date(newTransaction.timestamp).toLocaleString('es-PY'),
        action: 'NUEVO_MOVIMIENTO'
      });
    }
  };

  const updateMinStock = (reagentId: string, newMinStock: number) => {
    setReagents(prev => prev.map(r => r.id === reagentId ? { ...r, minStock: newMinStock } : r));
  };

  const markAsOrdered = (reagentId: string) => {
    const reagentToMark = reagents.find(r => r.id === reagentId);
    if (!reagentToMark) return;
    const rName = reagentToMark.name.toLowerCase();
    setReagents(prev => prev.map(r => r.name.toLowerCase() === rName ? { ...r, isOrdered: true } : r));
    showToast("Pedido registrado");
  };

  const updateMgSettings = (pwd?: string, email?: string) => {
    if (pwd) { localStorage.setItem(STORAGE_KEY_MG_PASSWORD, pwd); setMgPassword(pwd); }
    if (email !== undefined) { localStorage.setItem(STORAGE_KEY_MG_EMAIL, email); setManagerEmail(email); }
  };

  const addAnalyst = (name: string) => {
    if (!name || analysts.includes(name)) return;
    setAnalysts(prev => [...prev, name]);
  };

  const removeAnalyst = (name: string) => {
    setAnalysts(prev => prev.filter(a => a !== name));
  };

  const MobileNav = () => {
    const location = useLocation();
    const navItems = [
      { path: '/', icon: HomeIcon, label: 'Inicio' },
      { path: '/ingreso', icon: PlusCircleIcon, label: 'Entra' },
      { path: '/salida', icon: MinusCircleIcon, label: 'Sale' },
      { path: '/historial', icon: ClockIcon, label: 'Histo' },
      ...(role === 'GERENTE' ? [
        { path: '/alertas', icon: BellAlertIcon, label: 'Alertas' },
        { path: '/nube', icon: CloudIcon, label: 'Nube' }
      ] : [])
    ];
    return (
      <div className="md:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-slate-200 flex justify-around items-center h-16 px-2 z-50">
        {navItems.map((item) => (
          <Link key={item.path} to={item.path} className={`flex flex-col items-center justify-center w-full h-full transition-colors ${location.pathname === item.path ? 'text-indigo-600' : 'text-slate-400'}`}>
            <item.icon className="w-6 h-6" />
            <span className="text-[10px] font-bold mt-1 uppercase tracking-tighter">{item.label}</span>
          </Link>
        ))}
      </div>
    );
  };

  if (!role) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-600 to-indigo-900 flex items-center justify-center p-4">
        <div className="bg-white rounded-3xl shadow-2xl p-6 md:p-10 w-full max-w-md text-center relative overflow-hidden">
          <BeakerIcon className="w-16 h-16 text-indigo-600 mx-auto mb-4" />
          <h1 className="text-3xl font-bold text-slate-800 mb-2">ReagentFlow</h1>
          <p className="text-slate-500 mb-8 font-medium italic">Gestión de Stock Profesional</p>
          <div className="space-y-4">
            <button onClick={() => setRole('ANALISTA')} className="w-full bg-slate-50 border-2 border-slate-200 hover:border-indigo-600 hover:text-indigo-600 text-slate-700 font-bold py-5 px-6 rounded-2xl transition-all flex items-center justify-between group">
              <div className="flex items-center gap-3"><QueueListIcon className="w-6 h-6" /><span>Analista</span></div>
              <ChevronRightIcon className="w-5 h-5 opacity-50 group-hover:opacity-100" />
            </button>
            <button onClick={() => { setPendingRole('GERENTE'); setShowAuthModal(true); setAuthInput(''); setAuthError(''); }} className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-5 px-6 rounded-2xl transition-all flex items-center justify-between group shadow-xl">
              <div className="flex items-center gap-3"><BellAlertIcon className="w-6 h-6" /><span>Gerente</span></div>
              <ChevronRightIcon className="w-5 h-5 opacity-50 group-hover:opacity-100" />
            </button>
          </div>
        </div>
        {showAuthModal && (
          <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/70 backdrop-blur-sm">
            <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm overflow-hidden animate-in fade-in zoom-in-95 duration-200">
              <div className="bg-slate-50 p-6 border-b border-slate-100 flex items-center gap-3">
                <div className="p-2 bg-indigo-100 rounded-lg"><LockClosedIcon className="w-6 h-6 text-indigo-600" /></div>
                <div><h3 className="font-bold text-slate-800">Acceso Seguro</h3><p className="text-xs text-slate-500">Módulo Gerencial</p></div>
              </div>
              <form onSubmit={(e) => {
                e.preventDefault();
                if (!mgPassword) {
                  if (authInput.length < 4) { setAuthError('Mínimo 4 caracteres'); return; }
                  updateMgSettings(authInput); setRole('GERENTE'); setShowAuthModal(false);
                } else if (authInput === mgPassword) {
                  setRole('GERENTE'); setShowAuthModal(false);
                } else { setAuthError('Clave incorrecta'); }
              }} className="p-6 space-y-4">
                <input autoFocus type="password" placeholder="****" className="w-full px-4 py-4 bg-slate-50 border-2 border-slate-200 rounded-xl outline-none focus:border-indigo-500 transition-all text-center text-2xl tracking-widest font-bold" value={authInput} onChange={(e) => setAuthInput(e.target.value)} />
                {authError && <p className="text-red-600 text-xs font-bold text-center">{authError}</p>}
                <div className="flex gap-3 pt-2">
                  <button type="button" onClick={() => setShowAuthModal(false)} className="flex-1 py-3 text-slate-500 font-bold hover:bg-slate-100 rounded-xl">Cerrar</button>
                  <button type="submit" className="flex-[2] bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 rounded-xl shadow-lg">Entrar</button>
                </div>
              </form>
            </div>
          </div>
        )}
      </div>
    );
  }

  return (
    <Router>
      <div className="flex flex-col min-h-screen bg-slate-50 pb-20 md:pb-0">
        {toast && (
          <div className={`fixed top-4 left-1/2 -translate-x-1/2 z-[100] px-6 py-3 rounded-2xl shadow-2xl flex items-center gap-3 animate-in slide-in-from-top-4 duration-300 ${toast.type === 'alert' ? 'bg-amber-600 text-white' : toast.type === 'error' ? 'bg-red-600 text-white' : 'bg-slate-900 text-white'}`}>
            {toast.type === 'alert' ? <EnvelopeIcon className="w-6 h-6 animate-bounce" /> : <CheckBadgeIcon className="w-6 h-6" />}
            <span className="font-bold text-sm">{toast.message}</span>
          </div>
        )}

        <nav className="bg-white border-b border-slate-200 sticky top-0 z-30 shadow-sm hidden md:block">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 flex justify-between h-16">
            <div className="flex items-center gap-2"><BeakerIcon className="h-8 w-8 text-indigo-600" /><span className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-indigo-600 to-blue-500">ReagentFlow</span></div>
            <div className="flex items-center gap-6">
              <Link to="/" className="text-slate-600 hover:text-indigo-600 font-bold text-sm">Inventario</Link>
              <Link to="/ingreso" className="text-slate-600 hover:text-indigo-600 font-bold text-sm">Ingresos</Link>
              <Link to="/salida" className="text-slate-600 hover:text-indigo-600 font-bold text-sm">Salidas</Link>
              <Link to="/historial" className="text-slate-600 hover:text-indigo-600 font-bold text-sm">Historial</Link>
              {role === 'GERENTE' && (
                <>
                  <Link to="/alertas" className="text-slate-600 hover:text-red-600 font-bold text-sm">Alertas</Link>
                  <Link to="/nube" className="text-slate-600 hover:text-indigo-600 font-bold text-sm">Nube y Excel</Link>
                  <Link to="/config" className="text-slate-400 hover:text-indigo-600"><Cog6ToothIcon className="w-6 h-6" /></Link>
                </>
              )}
              <div className="h-6 w-[1px] bg-slate-200 mx-2"></div>
              <div className="flex items-center gap-2 bg-slate-100 px-3 py-1 rounded-full border border-slate-200">
                <UserCircleIcon className="w-4 h-4 text-slate-500" />
                <span className="text-[10px] font-black text-slate-700 uppercase">{role}</span>
              </div>
              <button onClick={() => setRole(null)} className="text-slate-400 hover:text-red-600"><ArrowRightOnRectangleIcon className="w-6 h-6" /></button>
            </div>
          </div>
        </nav>

        <div className="md:hidden bg-white px-4 py-4 border-b border-slate-200 sticky top-0 z-40 flex justify-between items-center shadow-sm">
           <div className="flex items-center gap-2"><BeakerIcon className="h-6 w-6 text-indigo-600" /><span className="font-bold text-slate-800">ReagentFlow</span></div>
           <div className="flex items-center gap-4">
              {role === 'GERENTE' && <Link to="/config" className="text-slate-400"><Cog6ToothIcon className="w-6 h-6" /></Link>}
              <button onClick={() => setRole(null)} className="text-slate-400"><ArrowRightOnRectangleIcon className="w-6 h-6" /></button>
           </div>
        </div>

        <main className="flex-grow max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
          <Routes>
            <Route path="/" element={<InventoryView reagents={reagents} />} />
            <Route path="/ingreso" element={<InputForm reagents={reagents} analysts={analysts} onTransaction={handleTransaction} transactions={transactions} />} />
            <Route path="/salida" element={<OutputForm reagents={reagents} analysts={analysts} onTransaction={handleTransaction} />} />
            <Route path="/historial" element={<HistoryView transactions={transactions} />} />
            <Route path="/alertas" element={role === 'GERENTE' ? <AlertsView reagents={reagents} markAsOrdered={markAsOrdered} onUpdateMinStock={updateMinStock} notifications={notifications} /> : <Navigate to="/" />} />
            <Route path="/nube" element={role === 'GERENTE' ? <CloudSyncView cloudUrl={cloudUrl} setCloudUrl={setCloudUrl} transactions={transactions} showToast={showToast} /> : <Navigate to="/" />} />
            <Route path="/config" element={role === 'GERENTE' ? <ConfigView updateMgSettings={updateMgSettings} analysts={analysts} onAddAnalyst={addAnalyst} onRemoveAnalyst={removeAnalyst} currentMg={mgPassword} currentEmail={managerEmail} /> : <Navigate to="/" />} />
          </Routes>
        </main>
        <MobileNav />
      </div>
    </Router>
  );
};

export default App;

import React, { useState } from 'react';
import { CloudIcon, TableCellsIcon, ArrowPathIcon, CheckCircleIcon, InformationCircleIcon, CommandLineIcon } from '@heroicons/react/24/outline';
import { Transaction } from '../types';

interface Props {
  cloudUrl: string;
  setCloudUrl: (url: string) => void;
  transactions: Transaction[];
  showToast: (msg: string, type: any) => void;
}

const CloudSyncView: React.FC<Props> = ({ cloudUrl, setCloudUrl, transactions, showToast }) => {
  const [urlInput, setUrlInput] = useState(cloudUrl);
  const [isSyncing, setIsSyncing] = useState(false);

  const handleSaveUrl = (e: React.FormEvent) => {
    e.preventDefault();
    setCloudUrl(urlInput);
    showToast("URL de Nube guardada correctamente", "success");
  };

  const handleManualSyncAll = async () => {
    if (!cloudUrl) {
      alert("Primero configure la URL de su Google Apps Script.");
      return;
    }

    if (!confirm(`¿Desea enviar los ${transactions.length} movimientos actuales a su Excel?`)) return;

    setIsSyncing(true);
    try {
      // Enviamos el lote completo de transacciones
      // Para evitar timeouts, enviamos los datos procesados con fechas legibles
      const dataToSync = transactions.map(t => ({
        ...t,
        timestamp: new Date(t.timestamp).toLocaleString('es-PY'),
        action: 'EXPORTACION_MASIVA'
      }));

      await fetch(cloudUrl, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(dataToSync)
      });

      showToast("Sincronización masiva completada", "success");
    } catch (e) {
      console.error(e);
      showToast("Error al sincronizar con la nube", "error");
    } finally {
      setIsSyncing(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8 pb-10">
      <div className="bg-indigo-600 rounded-3xl p-8 text-white shadow-xl relative overflow-hidden">
        <div className="relative z-10">
          <div className="flex items-center gap-3 mb-4">
            <CloudIcon className="w-10 h-10 text-indigo-200" />
            <h1 className="text-3xl font-black uppercase tracking-tighter">Sincronización Nube</h1>
          </div>
          <p className="text-indigo-100 font-medium max-w-xl">
            Conecte su inventario con Google Sheets para mantener un respaldo en tiempo real y generar reportes avanzados en Excel.
          </p>
        </div>
        <TableCellsIcon className="absolute -bottom-8 -right-8 w-64 h-64 text-indigo-500 opacity-20 rotate-12" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Configuración de URL */}
        <div className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
          <div className="p-6 border-b border-slate-100 bg-slate-50 flex items-center gap-3">
