                  </p>

                  <h3 className="text-sm font-black text-slate-800 uppercase border-l-4 border-indigo-600 pl-3">2. Pegar el Código</h3>
                  <p className="text-xs text-slate-500 leading-relaxed font-medium">
                    Borre cualquier código existente en el editor de Google y pegue el bloque de código que aparece a la derecha.
                  </p>

                  <h3 className="text-sm font-black text-slate-800 uppercase border-l-4 border-indigo-600 pl-3">3. Implementar Web App</h3>
                  <p className="text-xs text-slate-500 leading-relaxed font-medium">
                    Clic en <span className="font-bold text-slate-700">Implementar &gt; Nueva implementación</span>. Seleccione "Aplicación Web". En "Quién tiene acceso", elija <span className="font-bold text-indigo-600">Cualquiera</span>.
                  </p>

                  <h3 className="text-sm font-black text-slate-800 uppercase border-l-4 border-indigo-600 pl-3">4. Autorizar y Vincular</h3>
                  <p className="text-xs text-slate-500 leading-relaxed font-medium">
                    Copie la <span className="font-bold text-slate-700">URL de la aplicación web</span> que termina en <span className="font-mono">/exec</span> y péguela en el formulario de arriba.
                  </p>
                </div>

                <div className="relative group">
                  <div className="absolute top-4 right-4 z-10">
                    <button 
                      onClick={copyToClipboard}
                      className="p-3 bg-white/10 backdrop-blur-md hover:bg-white/20 text-white rounded-xl border border-white/20 transition-all flex items-center gap-2"
                    >
                      {copied ? <ClipboardDocumentCheckIcon className="w-5 h-5 text-emerald-400" /> : <DocumentDuplicateIcon className="w-5 h-5" />}
                      <span className="text-[10px] font-black uppercase">{copied ? 'Copiado' : 'Copiar Script'}</span>
                    </button>
                  </div>
                  <div className="bg-slate-900 rounded-3xl p-6 h-full max-h-[400px] overflow-y-auto border border-slate-800 scrollbar-hide">
                    <pre className="text-[10px] font-mono text-indigo-300 leading-relaxed">
                      {SCRIPT_CODE}
                    </pre>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Lado Derecho: Acciones y Estado */}
        <div className="space-y-8">
          <div className="bg-white rounded-[2rem] shadow-sm border border-slate-200 overflow-hidden sticky top-24">
            <div className="p-6 border-b border-slate-100 bg-slate-50 flex items-center gap-3">
              <ArrowPathIcon className="w-6 h-6 text-emerald-600" />
              <h2 className="font-bold text-slate-800 uppercase text-xs tracking-widest">Sincronización Masiva</h2>
            </div>
            <div className="p-8 space-y-6">
              <div className="text-center space-y-2 mb-4">
                <p className="text-4xl font-black text-slate-900">{transactions.length}</p>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Movimientos Registrados</p>
              </div>

              <div className="bg-amber-50 p-4 rounded-2xl border border-amber-100 flex gap-3">
                 <InformationCircleIcon className="w-5 h-5 text-amber-500 shrink-0" />
                 <p className="text-[10px] text-amber-800 font-bold leading-tight uppercase">
                   Use este botón para inicializar su Excel con todos los datos existentes actualmente.
                 </p>
              </div>

              <button 
                onClick={handleManualSyncAll}
                disabled={isSyncing || !cloudUrl}
                className="w-full bg-emerald-600 hover:bg-emerald-700 disabled:bg-slate-100 disabled:text-slate-400 text-white font-black py-6 rounded-2xl shadow-xl transition-all flex flex-col items-center justify-center gap-2 uppercase tracking-widest text-xs"
              >
                {isSyncing ? <ArrowPathIcon className="w-6 h-6 animate-spin" /> : <TableCellsIcon className="w-6 h-6" />}
                <span>Exportar Historial</span>
              </button>

              <div className="pt-4 border-t border-slate-100 space-y-4">
                 <div className="flex justify-between items-center text-[10px] font-bold">
                    <span className="text-slate-400 uppercase">Auto-Sincronización:</span>
                    <span className={cloudUrl ? "text-emerald-600" : "text-rose-500"}>{cloudUrl ? "ACTIVADA" : "DESACTIVADA"}</span>
                 </div>
                 <div className="flex justify-between items-center text-[10px] font-bold">
                    <span className="text-slate-400 uppercase">Destinatario Alertas:</span>
                    <span className="text-indigo-600 truncate max-w-[120px]">Activo</span>
                 </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default CloudSyncView;

import React, { useState, useEffect, useMemo } from 'react';
import { HashRouter as Router, Routes, Route, Link, Navigate, useLocation } from 'react-router-dom';
import emailjs from '@emailjs/browser';
import { createClient } from '@supabase/supabase-js';
import { 
  BeakerIcon, 
  QueueListIcon, 
  BellAlertIcon, 
  PlusCircleIcon, 
  MinusCircleIcon,
  UserCircleIcon,
  ArrowRightOnRectangleIcon,
  HomeIcon,
  ChevronRightIcon,
  LockClosedIcon,
  Cog6ToothIcon,
  ClockIcon,
  CheckBadgeIcon,
  EnvelopeIcon,
  CloudIcon,
  TableCellsIcon,
  CircleStackIcon
} from '@heroicons/react/24/outline';

import { Reagent, Transaction, UserRole, Department } from './types';
import InventoryView from './components/InventoryView';
import InputForm from './components/InputForm';
import OutputForm from './components/OutputForm';
import HistoryView from './components/HistoryView';
import AlertsView from './components/AlertsView';
import ConfigView from './components/ConfigView';
import CloudSyncView from './components/CloudSyncView';
import { generateId } from './utils';

const STORAGE_KEY_REAGENTS = 'reagentflow_inventory';
const STORAGE_KEY_TRANSACTIONS = 'reagentflow_transactions';
const STORAGE_KEY_NOTIFICATIONS = 'reagentflow_notifications';
const STORAGE_KEY_ANALYSTS = 'reagentflow_analysts';
const STORAGE_KEY_MG_PASSWORD = 'reagentflow_mg_pwd';
const STORAGE_KEY_MG_EMAIL = 'reagentflow_mg_email';
const STORAGE_KEY_CLOUD_URL = 'reagentflow_cloud_url';
const STORAGE_KEY_SUPA_URL = 'reagentflow_supa_url';
const STORAGE_KEY_SUPA_KEY = 'reagentflow_supa_key';

const EMAILJS_SERVICE_ID = "controlreactivo_lab";
const EMAILJS_TEMPLATE_ID = "template_czefw4r";
const EMAILJS_PUBLIC_KEY = "aMH7yh-WaX5jjiRUm";

interface NotificationLog {
  id: string;
  reagentName: string;
  timestamp: string;
  targetEmail: string;
  stockLevel: string;
  status: 'SENT' | 'FAILED' | 'PENDING';
}

const App: React.FC = () => {
  const [role, setRole] = useState<UserRole | null>(null);
  const [reagents, setReagents] = useState<Reagent[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [notifications, setNotifications] = useState<NotificationLog[]>([]);
  const [analysts, setAnalysts] = useState<string[]>(JSON.parse(localStorage.getItem(STORAGE_KEY_ANALYSTS) || '[]'));
  const [managerEmail, setManagerEmail] = useState<string>(localStorage.getItem(STORAGE_KEY_MG_EMAIL) || '');
  const [cloudUrl, setCloudUrl] = useState<string>(localStorage.getItem(STORAGE_KEY_CLOUD_URL) || '');
  const [supaUrl, setSupaUrl] = useState<string>(localStorage.getItem(STORAGE_KEY_SUPA_URL) || '');
  const [supaKey, setSupaKey] = useState<string>(localStorage.getItem(STORAGE_KEY_SUPA_KEY) || '');
  const [toast, setToast] = useState<{message: string, type: 'success' | 'alert' | 'error'} | null>(null);

  const [showAuthModal, setShowAuthModal] = useState(false);
  const [mgPassword, setMgPassword] = useState<string | null>(localStorage.getItem(STORAGE_KEY_MG_PASSWORD));
  const [authInput, setAuthInput] = useState('');
  const [authError, setAuthError] = useState('');

  // Cliente Supabase reactivo
  const supabase = useMemo(() => {
    if (supaUrl && supaKey) return createClient(supaUrl, supaKey);
    return null;
  }, [supaUrl, supaKey]);

  useEffect(() => {
    if (EMAILJS_PUBLIC_KEY) emailjs.init(EMAILJS_PUBLIC_KEY);
  }, []);

  useEffect(() => {
    const savedReagents = localStorage.getItem(STORAGE_KEY_REAGENTS);
    const savedTransactions = localStorage.getItem(STORAGE_KEY_TRANSACTIONS);
    const savedNotifs = localStorage.getItem(STORAGE_KEY_NOTIFICATIONS);
    if (savedReagents) setReagents(JSON.parse(savedReagents));
    if (savedTransactions) setTransactions(JSON.parse(savedTransactions));
    if (savedNotifs) setNotifications(JSON.parse(savedNotifs));
  }, []);

  useEffect(() => { localStorage.setItem(STORAGE_KEY_REAGENTS, JSON.stringify(reagents)); }, [reagents]);
  useEffect(() => { localStorage.setItem(STORAGE_KEY_TRANSACTIONS, JSON.stringify(transactions)); }, [transactions]);
  useEffect(() => { localStorage.setItem(STORAGE_KEY_NOTIFICATIONS, JSON.stringify(notifications)); }, [notifications]);
  useEffect(() => { localStorage.setItem(STORAGE_KEY_ANALYSTS, JSON.stringify(analysts)); }, [analysts]);
  useEffect(() => { localStorage.setItem(STORAGE_KEY_CLOUD_URL, cloudUrl); }, [cloudUrl]);
  useEffect(() => { localStorage.setItem(STORAGE_KEY_SUPA_URL, supaUrl); }, [supaUrl]);
  useEffect(() => { localStorage.setItem(STORAGE_KEY_SUPA_KEY, supaKey); }, [supaKey]);

  const showToast = (message: string, type: 'success' | 'alert' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 4000);
  };

  const syncToCloud = async (data: any) => {
    if (!cloudUrl) return;
    try {
      await fetch(cloudUrl, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(data)
      });
    } catch (e) { console.error("Cloud Error:", e); }
  };

  const syncToSupabase = async (trans: Transaction) => {
    if (!supabase) return;
    try {
      const { error } = await supabase.from('transactions').insert([
        {
          id: trans.id,
          reagent_id: trans.reagentId,
          reagent_name: trans.reagentName,
          type: trans.type,
          quantity: trans.quantity,
          display_quantity: trans.displayQuantity,
          display_unit: trans.displayUnit,
          analyst: trans.analyst,
          timestamp: trans.timestamp
        }
      ]);
      if (error) console.error("Supabase Error:", error);
    } catch (e) { console.error("Supabase Connection Error:", e); }
  };

  const handleTransaction = async (reagent: Partial<Reagent>, transactionData: Omit<Transaction, 'id' | 'timestamp' | 'reagentName'>) => {
    const timestamp = new Date().toISOString();
    let updatedReagents = [...reagents];
    let reagentId = transactionData.reagentId;

    if (transactionData.type === 'IN') {
      const existingIdx = updatedReagents.findIndex(r => r.id === reagentId);
      if (existingIdx > -1) {
        const existing = updatedReagents[existingIdx];
        updatedReagents = updatedReagents.map(r => 
          r.name.toLowerCase() === existing.name.toLowerCase() 
            ? { ...r, isOrdered: false, ...(r.id === reagentId ? { 
                brand: reagent.brand || r.brand, 
                currentStock: r.currentStock + transactionData.quantity,
                lastUpdated: timestamp 
              } : {}) }
            : r
        );
      } else {
        const newReagent: Reagent = {
          id: reagentId || generateId(),
          name: reagent.name!,
          brand: reagent.brand!,
          presentation: reagent.presentation!,
          currentStock: transactionData.quantity,
          minStock: reagent.minStock || 0,
          department: reagent.department!,
          baseUnit: reagent.baseUnit || 'ud',
          containerType: reagent.containerType || 'Frasco',
          quantityPerContainer: reagent.quantityPerContainer || 1,
          expiryDate: reagent.expiryDate || 'N/A',
          isOrdered: false,
          lastUpdated: timestamp
        };
        updatedReagents.push(newReagent);
        reagentId = newReagent.id;
      }
      showToast("Ingreso registrado correctamente", "success");
    } else {
      const existingIdx = updatedReagents.findIndex(r => r.id === reagentId);
      if (existingIdx > -1) {
        const existing = updatedReagents[existingIdx];
        const newStock = Math.max(0, existing.currentStock - transactionData.quantity);
        updatedReagents[existingIdx] = { ...existing, currentStock: newStock, lastUpdated: timestamp };

        const consolidatedStock = updatedReagents
          .filter(r => r.name.toLowerCase() === existing.name.toLowerCase())
          .reduce((sum, r) => sum + r.currentStock, 0);

        if (consolidatedStock <= existing.minStock && managerEmail && !existing.isOrdered) {
          const lastNotif = notifications.find(n => n.reagentName === existing.name);
          const minsSince = lastNotif ? (new Date().getTime() - new Date(lastNotif.timestamp).getTime()) / 60000 : 999;
          if (minsSince > 15) {
            showToast(`Enviando alerta a ${managerEmail}...`, 'alert');
            const emailStatus = await (async () => {
              if (!managerEmail) return 'PENDING' as const;
              try {
                const templateParams = {
                  to_email: managerEmail,
                  reagent_name: existing.name,
                  brand: existing.brand,
                  current_stock: `${consolidatedStock} ${existing.baseUnit}`,
                  min_stock: `${existing.minStock} ${existing.baseUnit}`,
                  department: existing.department,
                  timestamp: new Date().toLocaleString()
                };
                await emailjs.send(EMAILJS_SERVICE_ID, EMAILJS_TEMPLATE_ID, templateParams);
                return 'SENT' as const;
              } catch (error) { return 'FAILED' as const; }
            })();
            const newNotif: NotificationLog = {
              id: generateId(), reagentName: existing.name, timestamp, targetEmail: managerEmail,
              stockLevel: `${consolidatedStock} ${existing.baseUnit}`, status: emailStatus
            };
            setNotifications(prev => [newNotif, ...prev].slice(0, 50));
            if (emailStatus === 'SENT') showToast("Alerta enviada exitosamente", "success");
          }
        }
      }
      showToast("Salida registrada", "success");
    }

    setReagents(updatedReagents);
    const newTransaction: Transaction = {
      ...transactionData,
      id: generateId(),
      reagentId: reagentId!,
      reagentName: updatedReagents.find(r => r.id === reagentId)?.name || 'Desconocido',
      timestamp
    };
    setTransactions([newTransaction, ...transactions]);

    // Sincronización Automática Dual
    if (cloudUrl) {
      syncToCloud({ ...newTransaction, timestamp: new Date(newTransaction.timestamp).toLocaleString('es-PY'), action: 'NUEVO_MOVIMIENTO' });
    }
    if (supabase) {
      syncToSupabase(newTransaction);
    }
  };

  const updateMinStock = (reagentId: string, newMinStock: number) => {
    setReagents(prev => prev.map(r => r.id === reagentId ? { ...r, minStock: newMinStock } : r));
  };

  const markAsOrdered = (reagentId: string) => {
    const reagentToMark = reagents.find(r => r.id === reagentId);
    if (!reagentToMark) return;
    const rName = reagentToMark.name.toLowerCase();
    setReagents(prev => prev.map(r => r.name.toLowerCase() === rName ? { ...r, isOrdered: true } : r));
    showToast("Pedido registrado");
  };

  const updateMgSettings = (pwd?: string, email?: string) => {
    if (pwd) { localStorage.setItem(STORAGE_KEY_MG_PASSWORD, pwd); setMgPassword(pwd); }
    if (email !== undefined) { localStorage.setItem(STORAGE_KEY_MG_EMAIL, email); setManagerEmail(email); }
  };

  const addAnalyst = (name: string) => {
    if (!name || analysts.includes(name)) return;
    setAnalysts(prev => [...prev, name]);
  };

  const removeAnalyst = (name: string) => {
    setAnalysts(prev => prev.filter(a => a !== name));
  };

  const MobileNav = () => {
    const location = useLocation();
    const navItems = [
      { path: '/', icon: HomeIcon, label: 'Inicio' },
      { path: '/ingreso', icon: PlusCircleIcon, label: 'Entra' },
      { path: '/salida', icon: MinusCircleIcon, label: 'Sale' },
      { path: '/historial', icon: ClockIcon, label: 'Histo' },
      ...(role === 'GERENTE' ? [
        { path: '/alertas', icon: BellAlertIcon, label: 'Alertas' },
        { path: '/nube', icon: CloudIcon, label: 'Nube' }
      ] : [])
    ];
    return (
      <div className="md:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-slate-200 flex justify-around items-center h-16 px-2 z-50">
        {navItems.map((item) => (
          <Link key={item.path} to={item.path} className={`flex flex-col items-center justify-center w-full h-full transition-colors ${location.pathname === item.path ? 'text-indigo-600' : 'text-slate-400'}`}>
            <item.icon className="w-6 h-6" />
            <span className="text-[10px] font-bold mt-1 uppercase tracking-tighter">{item.label}</span>
          </Link>
        ))}
      </div>
    );
  };

  if (!role) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-600 to-indigo-900 flex items-center justify-center p-4">
        <div className="bg-white rounded-3xl shadow-2xl p-6 md:p-10 w-full max-w-md text-center relative overflow-hidden">
          <BeakerIcon className="w-16 h-16 text-indigo-600 mx-auto mb-4" />
          <h1 className="text-3xl font-bold text-slate-800 mb-2">ReagentFlow</h1>
          <p className="text-slate-500 mb-8 font-medium italic">Gestión de Stock Profesional</p>
          <div className="space-y-4">
            <button onClick={() => setRole('ANALISTA')} className="w-full bg-slate-50 border-2 border-slate-200 hover:border-indigo-600 hover:text-indigo-600 text-slate-700 font-bold py-5 px-6 rounded-2xl transition-all flex items-center justify-between group">
              <div className="flex items-center gap-3"><QueueListIcon className="w-6 h-6" /><span>Analista</span></div>
              <ChevronRightIcon className="w-5 h-5 opacity-50 group-hover:opacity-100" />
            </button>
            <button onClick={() => { setAuthInput(''); setAuthError(''); setShowAuthModal(true); }} className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-5 px-6 rounded-2xl transition-all flex items-center justify-between group shadow-xl">
              <div className="flex items-center gap-3"><BellAlertIcon className="w-6 h-6" /><span>Gerente</span></div>
              <ChevronRightIcon className="w-5 h-5 opacity-50 group-hover:opacity-100" />
            </button>
          </div>
        </div>
        {showAuthModal && (
          <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/70 backdrop-blur-sm">
            <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm overflow-hidden animate-in fade-in zoom-in-95 duration-200">
              <div className="bg-slate-50 p-6 border-b border-slate-100 flex items-center gap-3">
                <div className="p-2 bg-indigo-100 rounded-lg"><LockClosedIcon className="w-6 h-6 text-indigo-600" /></div>
                <div><h3 className="font-bold text-slate-800">Acceso Seguro</h3><p className="text-xs text-slate-500">Módulo Gerencial</p></div>
              </div>
              <form onSubmit={(e) => {
                e.preventDefault();
                if (!mgPassword) {
                  if (authInput.length < 4) { setAuthError('Mínimo 4 caracteres'); return; }
                  updateMgSettings(authInput); setRole('GERENTE'); setShowAuthModal(false);
                } else if (authInput === mgPassword) {
                  setRole('GERENTE'); setShowAuthModal(false);
                } else { setAuthError('Clave incorrecta'); }
              }} className="p-6 space-y-4">
                <input autoFocus type="password" placeholder="****" className="w-full px-4 py-4 bg-slate-50 border-2 border-slate-200 rounded-xl outline-none focus:border-indigo-500 transition-all text-center text-2xl tracking-widest font-bold" value={authInput} onChange={(e) => setAuthInput(e.target.value)} />
                {authError && <p className="text-red-600 text-xs font-bold text-center">{authError}</p>}
                <div className="flex gap-3 pt-2">
                  <button type="button" onClick={() => setShowAuthModal(false)} className="flex-1 py-3 text-slate-500 font-bold hover:bg-slate-100 rounded-xl">Cerrar</button>
                  <button type="submit" className="flex-[2] bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 rounded-xl shadow-lg">Entrar</button>
                </div>
              </form>
            </div>
          </div>
        )}
      </div>
    );
  }

  return (
    <Router>
      <div className="flex flex-col min-h-screen bg-slate-50 pb-20 md:pb-0">
        {toast && (
          <div className={`fixed top-4 left-1/2 -translate-x-1/2 z-[100] px-6 py-3 rounded-2xl shadow-2xl flex items-center gap-3 animate-in slide-in-from-top-4 duration-300 ${toast.type === 'alert' ? 'bg-amber-600 text-white' : toast.type === 'error' ? 'bg-red-600 text-white' : 'bg-slate-900 text-white'}`}>
            {toast.type === 'alert' ? <EnvelopeIcon className="w-6 h-6 animate-bounce" /> : <CheckBadgeIcon className="w-6 h-6" />}
            <span className="font-bold text-sm">{toast.message}</span>
          </div>
        )}

        <nav className="bg-white border-b border-slate-200 sticky top-0 z-30 shadow-sm hidden md:block">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 flex justify-between h-16">
            <div className="flex items-center gap-2"><BeakerIcon className="h-8 w-8 text-indigo-600" /><span className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-indigo-600 to-blue-500">ReagentFlow</span></div>
            <div className="flex items-center gap-6">
              <Link to="/" className="text-slate-600 hover:text-indigo-600 font-bold text-sm">Inventario</Link>
              <Link to="/ingreso" className="text-slate-600 hover:text-indigo-600 font-bold text-sm">Ingresos</Link>
              <Link to="/salida" className="text-slate-600 hover:text-indigo-600 font-bold text-sm">Salidas</Link>
              <Link to="/historial" className="text-slate-600 hover:text-indigo-600 font-bold text-sm">Historial</Link>
              {role === 'GERENTE' && (
                <>
                  <Link to="/alertas" className="text-slate-600 hover:text-red-600 font-bold text-sm">Alertas</Link>
                  <Link to="/nube" className="text-slate-600 hover:text-indigo-600 font-bold text-sm">Nube y DB</Link>
                  <Link to="/config" className="text-slate-400 hover:text-indigo-600"><Cog6ToothIcon className="w-6 h-6" /></Link>
                </>
              )}
              <div className="h-6 w-[1px] bg-slate-200 mx-2"></div>
              <div className="flex items-center gap-2 bg-slate-100 px-3 py-1 rounded-full border border-slate-200">
                <UserCircleIcon className="w-4 h-4 text-slate-500" />
                <span className="text-[10px] font-black text-slate-700 uppercase">{role}</span>
              </div>
              <button onClick={() => setRole(null)} className="text-slate-400 hover:text-red-600"><ArrowRightOnRectangleIcon className="w-6 h-6" /></button>
            </div>
          </div>
        </nav>

        <div className="md:hidden bg-white px-4 py-4 border-b border-slate-200 sticky top-0 z-40 flex justify-between items-center shadow-sm">
           <div className="flex items-center gap-2"><BeakerIcon className="h-6 w-6 text-indigo-600" /><span className="font-bold text-slate-800">ReagentFlow</span></div>
           <div className="flex items-center gap-4">
              {role === 'GERENTE' && <Link to="/config" className="text-slate-400"><Cog6ToothIcon className="w-6 h-6" /></Link>}
              <button onClick={() => setRole(null)} className="text-slate-400"><ArrowRightOnRectangleIcon className="w-6 h-6" /></button>
           </div>
        </div>

        <main className="flex-grow max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
          <Routes>
            <Route path="/" element={<InventoryView reagents={reagents} />} />
            <Route path="/ingreso" element={<InputForm reagents={reagents} analysts={analysts} onTransaction={handleTransaction} transactions={transactions} />} />
            <Route path="/salida" element={<OutputForm reagents={reagents} analysts={analysts} onTransaction={handleTransaction} />} />
            <Route path="/historial" element={<HistoryView transactions={transactions} />} />
            <Route path="/alertas" element={role === 'GERENTE' ? <AlertsView reagents={reagents} markAsOrdered={markAsOrdered} onUpdateMinStock={updateMinStock} notifications={notifications} /> : <Navigate to="/" />} />
            <Route path="/nube" element={role === 'GERENTE' ? <CloudSyncView cloudUrl={cloudUrl} setCloudUrl={setCloudUrl} supaUrl={supaUrl} setSupaUrl={setSupaUrl} supaKey={supaKey} setSupaKey={setSupaKey} transactions={transactions} showToast={showToast} /> : <Navigate to="/" />} />
            <Route path="/config" element={role === 'GERENTE' ? <ConfigView updateMgSettings={updateMgSettings} analysts={analysts} onAddAnalyst={addAnalyst} onRemoveAnalyst={removeAnalyst} currentMg={mgPassword} currentEmail={managerEmail} /> : <Navigate to="/" />} />
          </Routes>
        </main>
        <MobileNav />
      </div>
    </Router>
  );
};

