const SCRIPT_CODE_EXCEL = `function doPost(e) {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sheet = ss.getSheetByName('Movimientos') || ss.insertSheet('Movimientos');
  if (sheet.getLastRow() == 0) {
    sheet.appendRow(['ID', 'Fecha y Hora', 'Tipo', 'Reactivo', 'Cantidad Mov.', 'Unidad Envase', 'Analista Responsable', 'Cantidad Base (SI)']);
    sheet.getRange(1, 1, 1, 8).setFontWeight("bold").setBackground("#f3f4f6");
  }
  var data = JSON.parse(e.postData.contents);
  if (Array.isArray(data)) { data.reverse().forEach(function(item) { appendData(sheet, item); }); }
  else { appendData(sheet, data); }
  return ContentService.createTextOutput("OK").setMimeType(ContentService.MimeType.TEXT);
}

function appendData(sheet, item) {
  sheet.appendRow([item.id, item.timestamp, item.type === 'IN' ? 'ENTRADA' : 'SALIDA', item.reagentName, item.displayQuantity, item.displayUnit, item.analyst, item.quantity]);
}`;

const SQL_CODE_SUPABASE = `-- 1. Crea la tabla de movimientos
CREATE TABLE IF NOT EXISTS public.transactions (
    id TEXT PRIMARY KEY,
    reagent_id TEXT NOT NULL,
    reagent_name TEXT NOT NULL,
    type TEXT NOT NULL,
    quantity NUMERIC NOT NULL,
    display_quantity NUMERIC NOT NULL,
    display_unit TEXT NOT NULL,
    analyst TEXT NOT NULL,
    timestamp TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 2. Habilita acceso público (RLS) para demostración o configure sus políticas
ALTER TABLE public.transactions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Permitir inserciones públicas" ON public.transactions FOR INSERT WITH CHECK (true);
CREATE POLICY "Permitir lectura pública" ON public.transactions FOR SELECT USING (true);`;

