const SCRIPT_MASTER = `function doGet(e) {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var action = e.parameter.action;

  if (action === "readAll") {
    var configSheet = ss.getSheetByName('Config') || ss.insertSheet('Config');
    var invSheet = ss.getSheetByName('Inventario') || ss.insertSheet('Inventario');
    var moveSheet = ss.getSheetByName('Movimientos') || ss.insertSheet('Movimientos');

    // Leer Config
    var configData = configSheet.getDataRange().getValues();
    var config = { analysts: [], managerEmail: "", password: "" };
    for (var i = 0; i < configData.length; i++) {
      if (configData[i][0] === "analysts") config.analysts = JSON.parse(configData[i][1]);
      if (configData[i][0] === "managerEmail") config.managerEmail = configData[i][1];
      if (configData[i][0] === "password") config.password = configData[i][1];
    }

    // Leer Inventario
    var invData = invSheet.getDataRange().getValues();
    var reagents = [];
    if (invData.length > 1) {
      for (var j = 1; j < invData.length; j++) {
        reagents.push(JSON.parse(invData[j][0]));
      }
    }

    // Leer Movimientos (últimos 100)
    var moveData = moveSheet.getDataRange().getValues();
    var transactions = [];
    if (moveData.length > 1) {
      var start = Math.max(1, moveData.length - 100);
      for (var k = moveData.length - 1; k >= start; k--) {
        transactions.push({
          id: moveData[k][0],
          timestamp: moveData[k][1],
          type: moveData[k][2],
          reagentName: moveData[k][3],
          displayQuantity: moveData[k][4],
          displayUnit: moveData[k][5],
          analyst: moveData[k][6],
          quantity: moveData[k][7]
        });
      }
    }

    return ContentService.createTextOutput(JSON.stringify({ config: config, reagents: reagents, transactions: transactions }))
      .setMimeType(ContentService.MimeType.JSON);
  }
}

function doPost(e) {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var data = JSON.parse(e.postData.contents);
  var action = data.action;

  if (action === "SAVE_CONFIG") {
    var configSheet = ss.getSheetByName('Config') || ss.insertSheet('Config');
    configSheet.clear();
    configSheet.appendRow(["analysts", JSON.stringify(data.analysts)]);
    configSheet.appendRow(["managerEmail", data.managerEmail]);
    configSheet.appendRow(["password", data.password]);
  }

  if (action === "SYNC_ALL") {
    // Actualizar Inventario Maestro
    var invSheet = ss.getSheetByName('Inventario') || ss.insertSheet('Inventario');
    invSheet.clear();
    invSheet.appendRow(["ReagentJSON"]);
    data.reagents.forEach(function(r) {
      invSheet.appendRow([JSON.stringify(r)]);
    });

    // Si viene una transacción nueva, loguearla
    if (data.transaction) {
      var moveSheet = ss.getSheetByName('Movimientos') || ss.insertSheet('Movimientos');
      if (moveSheet.getLastRow() == 0) {
        moveSheet.appendRow(['ID', 'Fecha', 'Tipo', 'Reactivo', 'Cant.', 'Unidad', 'Analista', 'Base']);
      }
      var t = data.transaction;
      moveSheet.appendRow([t.id, t.timestamp, t.type, t.reagentName, t.displayQuantity, t.displayUnit, t.analyst, t.quantity]);
    }
  }

  return ContentService.createTextOutput("OK").setMimeType(ContentService.MimeType.TEXT);
}`;

