  const [supaUrl, setSupaUrl] = useState<string>(localStorage.getItem(STORAGE_KEY_SUPA_URL) || '');
  const [supaKey, setSupaKey] = useState<string>(localStorage.getItem(STORAGE_KEY_SUPA_KEY) || '');
  const [toast, setToast] = useState<{message: string, type: 'success' | 'alert' | 'error'} | null>(null);
  const [isSyncing, setIsSyncing] = useState(false);

  const [showAuthModal, setShowAuthModal] = useState(false);
  const [mgPassword, setMgPassword] = useState<string | null>(localStorage.getItem(STORAGE_KEY_MG_PASSWORD));
  const [authInput, setAuthInput] = useState('');
  const [authError, setAuthError] = useState('');

  // Cliente Supabase reactivo
  const supabase = useMemo(() => {
    if (supaUrl && supaKey) return createClient(supaUrl, supaKey);
    return null;
  }, [supaUrl, supaKey]);

  const showToast = (message: string, type: 'success' | 'alert' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 4000);
  };

  // --- LÓGICA DE DATOS SUPABASE ---

  const pullData = useCallback(async () => {
    if (!supabase) return;
    setIsSyncing(true);
    try {
      // 1. Cargar Configuración
      const { data: configData } = await supabase.from('config').select('*');
      if (configData) {
        const emailRow = configData.find(d => d.key === 'manager_email');
        const pwdRow = configData.find(d => d.key === 'manager_password');
        const analystsRow = configData.find(d => d.key === 'analysts');

        if (emailRow) setManagerEmail(emailRow.value);
        if (pwdRow) {
          setMgPassword(pwdRow.value);
          localStorage.setItem(STORAGE_KEY_MG_PASSWORD, pwdRow.value);
        }
        if (analystsRow) setAnalysts(JSON.parse(analystsRow.value));
      }

      // 2. Cargar Inventario
      const { data: reagentsData } = await supabase.from('reagents').select('*');
      if (reagentsData) {
        const formattedReagents = reagentsData.map(r => ({
          ...r,
          currentStock: parseFloat(r.current_stock),
          minStock: parseFloat(r.min_stock),
          quantityPerContainer: parseFloat(r.quantity_per_container),
          lastUpdated: r.last_updated,
          expiryDate: r.expiry_date,
          containerType: r.container_type,
          baseUnit: r.base_unit,
          isOrdered: r.is_ordered
        }));
        setReagents(formattedReagents);
      }

      // 3. Cargar Transacciones (últimas 100)
      const { data: transData } = await supabase.from('transactions')
        .select('*')
        .order('timestamp', { ascending: false })
        .limit(100);

      if (transData) {
        setTransactions(transData.map(t => ({
          ...t,
          reagentId: t.reagent_id,
          reagentName: t.reagent_name,
          displayQuantity: parseFloat(t.display_quantity),
          displayUnit: t.display_unit,
          quantity: parseFloat(t.quantity)
        })));
      }
    } catch (e) {
      console.error("Error cargando de Supabase:", e);
    } finally {
      setIsSyncing(false);
    }
  }, [supabase]);

  useEffect(() => {
    if (EMAILJS_PUBLIC_KEY) emailjs.init(EMAILJS_PUBLIC_KEY);
    if (supabase) pullData();
  }, [supabase, pullData]);

  // Funciones de actualización en Supabase
  const pushTransaction = async (reagent: Reagent, trans: Transaction) => {
    if (!supabase) return;
    try {
      // Upsert Reagent
      await supabase.from('reagents').upsert({
        id: reagent.id,
        name: reagent.name,
        brand: reagent.brand,
        presentation: reagent.presentation,
        current_stock: reagent.currentStock,
        min_stock: reagent.minStock,
        department: reagent.department,
        base_unit: reagent.baseUnit,
        container_type: reagent.containerType,
        quantity_per_container: reagent.quantityPerContainer,
        expiry_date: reagent.expiryDate,
        is_ordered: reagent.isOrdered,
        last_updated: reagent.lastUpdated
      });

      // Insert Transaction
      await supabase.from('transactions').insert({
        id: trans.id,
        reagent_id: trans.reagentId,
        reagent_name: trans.reagentName,
        type: trans.type,
        quantity: trans.quantity,
        display_quantity: trans.displayQuantity,
        display_unit: trans.displayUnit,
        analyst: trans.analyst,
        timestamp: trans.timestamp
      });
    } catch (e) { console.error("Error en push:", e); }
  };

  const saveConfigToSupa = async (key: string, value: string) => {
    if (!supabase) return;
    await supabase.from('config').upsert({ key, value });
  };

  // --- HANDLERS ---

  const handleTransaction = async (reagent: Partial<Reagent>, transactionData: Omit<Transaction, 'id' | 'timestamp' | 'reagentName'>) => {
    const timestamp = new Date().toISOString();
    let updatedReagents = [...reagents];
    let reagentId = transactionData.reagentId;
    let finalReagent: Reagent;

    if (transactionData.type === 'IN') {
      const existingIdx = updatedReagents.findIndex(r => r.id === reagentId);
      if (existingIdx > -1) {
        const existing = updatedReagents[existingIdx];
        finalReagent = { ...existing, currentStock: existing.currentStock + transactionData.quantity, lastUpdated: timestamp, isOrdered: false };
        updatedReagents[existingIdx] = finalReagent;
      } else {
        finalReagent = {
          id: reagentId || generateId(),
          name: reagent.name!,
          brand: reagent.brand!,
          presentation: reagent.presentation!,
          currentStock: transactionData.quantity,
          minStock: reagent.minStock || 0,
          department: reagent.department!,
          baseUnit: reagent.baseUnit || 'ud',
          containerType: reagent.containerType || 'Frasco',
          quantityPerContainer: reagent.quantityPerContainer || 1,
          expiryDate: reagent.expiryDate || 'N/A',
          isOrdered: false,
          lastUpdated: timestamp
        };
        updatedReagents.push(finalReagent);
        reagentId = finalReagent.id;
      }
      showToast("Ingreso registrado", "success");
    } else {
      const existingIdx = updatedReagents.findIndex(r => r.id === reagentId);
      const existing = updatedReagents[existingIdx];
      finalReagent = { ...existing, currentStock: Math.max(0, existing.currentStock - transactionData.quantity), lastUpdated: timestamp };
      updatedReagents[existingIdx] = finalReagent;
      showToast("Salida registrada", "success");

      // Lógica de Alerta EmailJS (abreviada)
      const consolidatedStock = updatedReagents.filter(r => r.name.toLowerCase() === existing.name.toLowerCase()).reduce((sum, r) => sum + r.currentStock, 0);
      if (consolidatedStock <= existing.minStock && managerEmail && !existing.isOrdered) {
        try {
          await emailjs.send(EMAILJS_SERVICE_ID, EMAILJS_TEMPLATE_ID, {
            to_email: managerEmail, reagent_name: existing.name, current_stock: `${consolidatedStock} ${existing.baseUnit}`
          });
          setNotifications(prev => [{ id: generateId(), reagentName: existing.name, timestamp, targetEmail: managerEmail, stockLevel: `${consolidatedStock}`, status: 'SENT' }, ...prev]);
        } catch(e) {}
      }
    }

    setReagents(updatedReagents);
    const newTransaction: Transaction = {
      ...transactionData,
      id: generateId(),
      reagentId: reagentId!,
      reagentName: finalReagent.name,
      timestamp
    };
    setTransactions([newTransaction, ...transactions]);
    if (supabase) pushTransaction(finalReagent, newTransaction);
  };

  const updateMgSettings = (pwd?: string, email?: string) => {
    if (pwd) { 
      setMgPassword(pwd); 
      localStorage.setItem(STORAGE_KEY_MG_PASSWORD, pwd); 
      saveConfigToSupa('manager_password', pwd);
    }
    if (email !== undefined) { 
      setManagerEmail(email); 
      saveConfigToSupa('manager_email', email);
    }
    showToast("Ajustes sincronizados");
  };

  const addAnalyst = (name: string) => {
    if (!name || analysts.includes(name)) return;
    const newAnalysts = [...analysts, name];
    setAnalysts(newAnalysts);
    saveConfigToSupa('analysts', JSON.stringify(newAnalysts));
  };

  const removeAnalyst = (name: string) => {
    const newAnalysts = analysts.filter(a => a !== name);
    setAnalysts(newAnalysts);
    saveConfigToSupa('analysts', JSON.stringify(newAnalysts));
  };

  const markAsOrdered = (reagentId: string) => {
    const reagent = reagents.find(r => r.id === reagentId);
    if (!reagent) return;
    const updated = { ...reagent, isOrdered: true };
    setReagents(reagents.map(r => r.id === reagentId ? updated : r));
    if (supabase) pushTransaction(updated, {} as any); // Upsert solo reagent
    showToast("Pedido marcado");
  };

  const updateMinStock = (reagentId: string, newMinStock: number) => {
    const reagent = reagents.find(r => r.id === reagentId);
    if (!reagent) return;
    const updated = { ...reagent, minStock: newMinStock };
    setReagents(reagents.map(r => r.id === reagentId ? updated : r));
    if (supabase) pushTransaction(updated, {} as any);
  };

  // Nav y Modals... (omito para brevedad pero se mantienen iguales)
  const MobileNav = () => {
    const location = useLocation();
    const navItems = [
      { path: '/', icon: HomeIcon, label: 'Inicio' },
      { path: '/ingreso', icon: PlusCircleIcon, label: 'Entra' },
      { path: '/salida', icon: MinusCircleIcon, label: 'Sale' },
      { path: '/historial', icon: ClockIcon, label: 'Histo' },
      ...(role === 'GERENTE' ? [{ path: '/alertas', icon: BellAlertIcon, label: 'Alertas' }, { path: '/nube', icon: CloudIcon, label: 'Nube' }] : [])
    ];
    return (
      <div className="md:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-slate-200 flex justify-around items-center h-16 px-2 z-50">
        {navItems.map((item) => (
          <Link key={item.path} to={item.path} className={`flex flex-col items-center justify-center w-full h-full transition-colors ${location.pathname === item.path ? 'text-indigo-600' : 'text-slate-400'}`}>
            <item.icon className="w-6 h-6" />
            <span className="text-[10px] font-bold mt-1 uppercase tracking-tighter">{item.label}</span>
          </Link>
        ))}
      </div>
    );
  };

  if (!role) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-600 to-indigo-900 flex items-center justify-center p-4 text-center">
        <div className="bg-white rounded-3xl shadow-2xl p-6 md:p-10 w-full max-w-md relative overflow-hidden">
          <BeakerIcon className="w-16 h-16 text-indigo-600 mx-auto mb-4" />
          <h1 className="text-3xl font-bold text-slate-800 mb-2">ReagentFlow</h1>
          <p className="text-slate-500 mb-8 font-medium italic">Gestión Multi-Dispositivo</p>
          <div className="space-y-4">
            <button onClick={() => setRole('ANALISTA')} className="w-full bg-slate-50 border-2 border-slate-200 hover:border-indigo-600 hover:text-indigo-600 text-slate-700 font-bold py-5 px-6 rounded-2xl transition-all flex items-center justify-between group">
              <div className="flex items-center gap-3"><QueueListIcon className="w-6 h-6" /><span>Analista</span></div>
              <ChevronRightIcon className="w-5 h-5 opacity-50 group-hover:opacity-100" />
            </button>
            <button onClick={() => { setAuthInput(''); setAuthError(''); setShowAuthModal(true); }} className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-5 px-6 rounded-2xl transition-all flex items-center justify-between group shadow-xl">
              <div className="flex items-center gap-3"><BellAlertIcon className="w-6 h-6" /><span>Gerente</span></div>
              <ChevronRightIcon className="w-5 h-5 opacity-50 group-hover:opacity-100" />
            </button>
          </div>
          {isSyncing && <div className="mt-6 flex items-center justify-center gap-2 text-xs font-black text-indigo-600"><ArrowPathIcon className="w-4 h-4 animate-spin"/> CONECTANDO A DB...</div>}
        </div>
        {showAuthModal && (
          <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/70 backdrop-blur-sm">
            <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm overflow-hidden animate-in fade-in zoom-in-95 duration-200">
              <div className="bg-slate-50 p-6 border-b border-slate-100 flex items-center gap-3 text-left">
                <div className="p-2 bg-indigo-100 rounded-lg"><LockClosedIcon className="w-6 h-6 text-indigo-600" /></div>
                <div><h3 className="font-bold text-slate-800">Acceso Seguro</h3><p className="text-xs text-slate-500">Módulo Gerencial</p></div>
              </div>
              <form onSubmit={(e) => {
                e.preventDefault();
                if (!mgPassword) {
                  if (authInput.length < 4) { setAuthError('Mínimo 4 caracteres'); return; }
                  updateMgSettings(authInput); setRole('GERENTE'); setShowAuthModal(false);
                } else if (authInput === mgPassword) {
                  setRole('GERENTE'); setShowAuthModal(false);
                } else { setAuthError('Clave incorrecta'); }
              }} className="p-6 space-y-4">
                <input autoFocus type="password" placeholder="****" className="w-full px-4 py-4 bg-slate-50 border-2 border-slate-200 rounded-xl outline-none focus:border-indigo-500 transition-all text-center text-2xl tracking-widest font-bold" value={authInput} onChange={(e) => setAuthInput(e.target.value)} />
                {authError && <p className="text-red-600 text-xs font-bold text-center">{authError}</p>}
                <div className="flex gap-3 pt-2">
                  <button type="button" onClick={() => setShowAuthModal(false)} className="flex-1 py-3 text-slate-500 font-bold hover:bg-slate-100 rounded-xl">Cerrar</button>
                  <button type="submit" className="flex-[2] bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 rounded-xl shadow-lg">Entrar</button>
                </div>
              </form>
            </div>
          </div>
        )}
      </div>
    );
  }

  return (
    <Router>
      <div className="flex flex-col min-h-screen bg-slate-50 pb-20 md:pb-0">
        {toast && (
          <div className={`fixed top-4 left-1/2 -translate-x-1/2 z-[100] px-6 py-3 rounded-2xl shadow-2xl flex items-center gap-3 animate-in slide-in-from-top-4 duration-300 ${toast.type === 'alert' ? 'bg-amber-600 text-white' : toast.type === 'error' ? 'bg-red-600 text-white' : 'bg-slate-900 text-white'}`}>
            {toast.type === 'alert' ? <EnvelopeIcon className="w-6 h-6 animate-bounce" /> : <CheckBadgeIcon className="w-6 h-6" />}
            <span className="font-bold text-sm">{toast.message}</span>
          </div>
        )}

        <nav className="bg-white border-b border-slate-200 sticky top-0 z-30 shadow-sm hidden md:block">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 flex justify-between h-16">
            <div className="flex items-center gap-2"><BeakerIcon className="h-8 w-8 text-indigo-600" /><span className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-indigo-600 to-blue-500">ReagentFlow</span></div>
            <div className="flex items-center gap-6">
              <Link to="/" className="text-slate-600 hover:text-indigo-600 font-bold text-sm">Inventario</Link>
              <Link to="/ingreso" className="text-slate-600 hover:text-indigo-600 font-bold text-sm">Ingresos</Link>
              <Link to="/salida" className="text-slate-600 hover:text-indigo-600 font-bold text-sm">Salidas</Link>
              <Link to="/historial" className="text-slate-600 hover:text-indigo-600 font-bold text-sm">Historial</Link>
              {role === 'GERENTE' && (
                <>
                  <Link to="/alertas" className="text-slate-600 hover:text-red-600 font-bold text-sm">Alertas</Link>
                  <Link to="/nube" className="text-slate-600 hover:text-indigo-600 font-bold text-sm">Sincronización DB</Link>
                  <Link to="/config" className="text-slate-400 hover:text-indigo-600"><Cog6ToothIcon className="w-6 h-6" /></Link>
                </>
              )}
              <div className="h-6 w-[1px] bg-slate-200 mx-2"></div>
              <button onClick={() => pullData()} className={`p-2 rounded-lg transition-all ${isSyncing ? 'text-indigo-600' : 'text-slate-400 hover:text-indigo-600'}`}>
                <ArrowPathIcon className={`w-5 h-5 ${isSyncing ? 'animate-spin' : ''}`} />
              </button>
              <div className="flex items-center gap-2 bg-slate-100 px-3 py-1 rounded-full border border-slate-200">
                <UserCircleIcon className="w-4 h-4 text-slate-500" />
                <span className="text-[10px] font-black text-slate-700 uppercase">{role}</span>
              </div>
              <button onClick={() => setRole(null)} className="text-slate-400 hover:text-red-600"><ArrowRightOnRectangleIcon className="w-6 h-6" /></button>
            </div>
          </div>
        </nav>

        <main className="flex-grow max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
          <Routes>
            <Route path="/" element={<InventoryView reagents={reagents} />} />
            <Route path="/ingreso" element={<InputForm reagents={reagents} analysts={analysts} onTransaction={handleTransaction} transactions={transactions} />} />
            <Route path="/salida" element={<OutputForm reagents={reagents} analysts={analysts} onTransaction={handleTransaction} />} />
            <Route path="/historial" element={<HistoryView transactions={transactions} />} />
            <Route path="/alertas" element={role === 'GERENTE' ? <AlertsView reagents={reagents} markAsOrdered={markAsOrdered} onUpdateMinStock={updateMinStock} notifications={notifications} /> : <Navigate to="/" />} />
            <Route path="/nube" element={role === 'GERENTE' ? <CloudSyncView supaUrl={supaUrl} setSupaUrl={(url) => { setSupaUrl(url); localStorage.setItem(STORAGE_KEY_SUPA_URL, url); }} supaKey={supaKey} setSupaKey={(key) => { setSupaKey(key); localStorage.setItem(STORAGE_KEY_SUPA_KEY, key); }} transactions={transactions} reagents={reagents} analysts={analysts} managerEmail={managerEmail} mgPassword={mgPassword || ''} showToast={showToast} onSync={pullData} /> : <Navigate to="/" />} />
            <Route path="/config" element={role === 'GERENTE' ? <ConfigView updateMgSettings={updateMgSettings} analysts={analysts} onAddAnalyst={addAnalyst} onRemoveAnalyst={removeAnalyst} currentMg={mgPassword} currentEmail={managerEmail} /> : <Navigate to="/" />} />
          </Routes>
        </main>
        <MobileNav />
      </div>
    </Router>
  );
};

export default App;

import React, { useState } from 'react';
import { 
  CircleStackIcon, 
  KeyIcon, 
  ArrowPathIcon, 
  CheckCircleIcon, 
  InformationCircleIcon, 
  CommandLineIcon,
  ClipboardDocumentCheckIcon,
  DocumentDuplicateIcon,
  GlobeAltIcon
} from '@heroicons/react/24/outline';
import { Transaction, Reagent } from '../types';

interface Props {
  supaUrl: string;
  setSupaUrl: (url: string) => void;
  supaKey: string;
  setSupaKey: (key: string) => void;
  transactions: Transaction[];
  reagents: Reagent[];
  analysts: string[];
  managerEmail: string;
  mgPassword: string;
  showToast: (msg: string, type: any) => void;
  onSync: () => void;
}

const SQL_SCHEMA = `-- 1. Tabla de Configuración (Analistas, Password, Email)
CREATE TABLE IF NOT EXISTS public.config (
    key TEXT PRIMARY KEY,
    value TEXT NOT NULL
);

-- 2. Tabla de Inventario
CREATE TABLE IF NOT EXISTS public.reagents (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    brand TEXT NOT NULL,
    presentation TEXT NOT NULL,
    current_stock NUMERIC NOT NULL,
    min_stock NUMERIC NOT NULL,
    department TEXT NOT NULL,
    base_unit TEXT NOT NULL,
    container_type TEXT NOT NULL,
    quantity_per_container NUMERIC NOT NULL,
    expiry_date TEXT NOT NULL,
    is_ordered BOOLEAN DEFAULT FALSE,
    last_updated TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 3. Tabla de Transacciones (Historial)
CREATE TABLE IF NOT EXISTS public.transactions (
    id TEXT PRIMARY KEY,
    reagent_id TEXT REFERENCES public.reagents(id),
    reagent_name TEXT NOT NULL,
    type TEXT NOT NULL,
    quantity NUMERIC NOT NULL,
    display_quantity NUMERIC NOT NULL,
    display_unit TEXT NOT NULL,
    analyst TEXT NOT NULL,
    timestamp TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Habilitar RLS básico para acceso público (solo para demo, configurar políticas en prod)
ALTER TABLE public.config ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.reagents ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.transactions ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Public full access" ON public.config FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Public full access" ON public.reagents FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Public full access" ON public.transactions FOR ALL USING (true) WITH CHECK (true);`;

const CloudSyncView: React.FC<Props> = ({ 
  supaUrl, setSupaUrl, supaKey, setSupaKey, showToast, onSync 
}) => {
  const [urlInput, setUrlInput] = useState(supaUrl);
  const [keyInput, setKeyInput] = useState(supaKey);
  const [copied, setCopied] = useState(false);

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    setSupaUrl(urlInput);
    setSupaKey(keyInput);
    showToast("Credenciales de base de datos guardadas", "success");
    setTimeout(() => onSync(), 500);
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(SQL_SCHEMA);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
    showToast("Esquema SQL copiado", "success");
  };

  return (
    <div className="max-w-5xl mx-auto space-y-8 pb-16">
      <div className="bg-slate-900 rounded-[2.5rem] p-10 text-white shadow-2xl relative overflow-hidden border border-slate-800">
        <div className="relative z-10 flex flex-col md:flex-row md:items-center justify-between gap-6">
          <div className="space-y-4">
            <div className="flex items-center gap-4">
              <div className="p-3 bg-indigo-500/20 rounded-2xl backdrop-blur-md border border-indigo-500/30">
                <CircleStackIcon className="w-10 h-10 text-indigo-400" />
              </div>
              <h1 className="text-4xl font-black uppercase tracking-tighter italic">Base de Datos Supabase</h1>
            </div>
            <p className="text-slate-400 font-medium max-w-xl text-lg leading-relaxed">
              Sincronización profesional en tiempo real. Esta es la única forma de garantizar que todos los dispositivos vean los mismos datos al instante.
            </p>
          </div>
          <div className="bg-slate-800/50 backdrop-blur-md p-6 rounded-3xl border border-slate-700 text-center">
             <p className="text-[10px] font-black uppercase tracking-widest text-slate-500 mb-1">Estado DB</p>
             {supaUrl ? <div className="text-emerald-400 font-bold flex items-center gap-2"><CheckCircleIcon className="w-5 h-5"/>VINCULADO</div> : <div className="text-rose-400 font-bold animate-pulse">DESCONECTADO</div>}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-8">
          <div className="bg-white rounded-[2rem] shadow-sm border border-slate-200 overflow-hidden">
            <div className="p-6 border-b border-slate-100 bg-slate-50">
              <h2 className="font-bold text-slate-800 uppercase text-xs tracking-widest flex items-center gap-2">
                <GlobeAltIcon className="w-5 h-5 text-indigo-600" /> Conectar con el Proyecto Supabase
              </h2>
            </div>
            <form onSubmit={handleSave} className="p-8 space-y-6">
              <div className="space-y-4">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Supabase URL (API)</label>
                  <input 
                    type="url" required placeholder="https://xyz.supabase.co"
                    className="w-full px-6 py-5 bg-slate-50 border-2 border-slate-200 rounded-2xl focus:border-indigo-500 outline-none font-mono text-xs text-indigo-600"
                    value={urlInput} onChange={(e) => setUrlInput(e.target.value)}
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Supabase Anon Key</label>
                  <div className="relative">
                    <input 
                      type="password" required placeholder="eyJhbG..."
