import { createClient } from '@supabase/supabase-js';
import { 
  BeakerIcon, 
  QueueListIcon, 
  BellAlertIcon, 
  PlusCircleIcon, 
  MinusCircleIcon,
  UserCircleIcon,
  ArrowRightOnRectangleIcon,
  HomeIcon,
  ChevronRightIcon,
  LockClosedIcon,
  Cog6ToothIcon,
  ClockIcon,
  CheckBadgeIcon,
  EnvelopeIcon,
  CloudIcon,
  ArrowPathIcon,
  CircleStackIcon,
  TableCellsIcon,
  WifiIcon,
  ExclamationTriangleIcon
} from '@heroicons/react/24/outline';

