  const [supaUrl, setSupaUrlState] = useState<string>(() => localStorage.getItem(STORAGE_KEY_SUPA_URL) || VITE_URL);
  const [supaKey, setSupaKeyState] = useState<string>(() => localStorage.getItem(STORAGE_KEY_SUPA_KEY) || VITE_KEY);
  const [cloudUrl, setCloudUrl] = useState<string>(localStorage.getItem(STORAGE_KEY_CLOUD_URL) || '');

  const [toast, setToast] = useState<{message: string, type: 'success' | 'alert' | 'error'} | null>(null);
  const [isSyncing, setIsSyncing] = useState(false);
