        const emailRow = configData.find(d => d.key === 'manager_email');
        const pwdRow = configData.find(d => d.key === 'manager_password');
        const analystsRow = configData.find(d => d.key === 'analysts');
        if (emailRow) setManagerEmail(emailRow.value);
        if (pwdRow) {
          setMgPassword(pwdRow.value);
          localStorage.setItem(STORAGE_KEY_MG_PASSWORD, pwdRow.value);
        }
        if (analystsRow) {
          try { 
            const parsed = JSON.parse(analystsRow.value);
            // Migración simple si antes eran strings
            if (Array.isArray(parsed) && typeof parsed[0] === 'string') {
               setAnalysts(parsed.map((name: string) => ({ name, department: 'Fisicoquímico' })));
            } else {
               setAnalysts(parsed); 
            }
          } 
          catch { setAnalysts([]); }
        }
      }

      const { data: reagentsData } = await supabase.from('reagents').select('*');
      if (reagentsData) {
        setReagents(reagentsData.map(r => ({
          ...r,
          currentStock: parseFloat(r.current_stock),
          minStock: parseFloat(r.min_stock),
          quantityPerContainer: parseFloat(r.quantity_per_container),
          lastUpdated: r.last_updated,
          expiryDate: r.expiry_date,
          containerType: r.container_type,
          baseUnit: r.base_unit,
          isOrdered: r.is_ordered
        })));
      }

      const { data: transData } = await supabase.from('transactions').select('*').order('timestamp', { ascending: false }).limit(100);
      if (transData) {
        setTransactions(transData.map(t => ({
          ...t,
          reagentId: t.reagent_id,
          reagentName: t.reagent_name,
          displayQuantity: parseFloat(t.display_quantity),
          displayUnit: t.display_unit,
          quantity: parseFloat(t.quantity)
        })));
      }
    } catch (e) {
      console.error("Critical Sync Error:", e);
    } finally {
      setIsSyncing(false);
    }
  }, [supabase]);

  useEffect(() => {
    if (EMAILJS_PUBLIC_KEY) emailjs.init(EMAILJS_PUBLIC_KEY);
    if (supabase) pullData();
  }, [supabase, pullData]);

  // --- Persistencia de configuración ---
  const saveConfigKey = async (key: string, value: string) => {
    if (!supabase) return;
    const { error } = await supabase.from('config').upsert({ key, value });
    if (error) showToast("Error al guardar en la nube", "error");
  };

  const updateMgSettings = async (pwd?: string, email?: string) => {
    if (pwd) { setMgPassword(pwd); localStorage.setItem(STORAGE_KEY_MG_PASSWORD, pwd); await saveConfigKey('manager_password', pwd); }
    if (email) { setManagerEmail(email); await saveConfigKey('manager_email', email); }
    showToast("Ajustes sincronizados globalmente");
  };

  const addAnalyst = async (user: AnalystUser) => {
    const newAnalysts = [...analysts, user];
    setAnalysts(newAnalysts);
    await saveConfigKey('analysts', JSON.stringify(newAnalysts));
  };

  const removeAnalyst = async (name: string) => {
    const newAnalysts = analysts.filter(a => a.name !== name);
    setAnalysts(newAnalysts);
    await saveConfigKey('analysts', JSON.stringify(newAnalysts));
  };

  // --- Manejo de pedidos (Mark as Ordered) ---
  const handleMarkAsOrdered = async (id: string) => {
    const timestamp = new Date().toISOString();
    const updatedReagents = reagents.map(r => 
      r.id === id ? { ...r, isOrdered: true, lastUpdated: timestamp } : r
    );
    setReagents(updatedReagents);
    showToast("Marcado como pedido", "success");

    const targetReagent = updatedReagents.find(r => r.id === id);

    if (supabase && targetReagent) {
      await supabase.from('reagents').upsert({
        id: targetReagent.id, name: targetReagent.name, brand: targetReagent.brand, presentation: targetReagent.presentation,
        current_stock: targetReagent.currentStock, min_stock: targetReagent.minStock, department: targetReagent.department,
        base_unit: targetReagent.baseUnit, container_type: targetReagent.containerType, quantity_per_container: targetReagent.quantityPerContainer,
        expiry_date: targetReagent.expiryDate, is_ordered: true, last_updated: timestamp
      });
    }

    // Sync to cloud optional, usually transaction based, but can trigger full sync
    if (cloudUrl && targetReagent) {
       try {
        await fetch(cloudUrl, {
          method: 'POST',
          mode: 'no-cors',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ action: 'SYNC_ALL', reagents: updatedReagents })
        });
      } catch (e) { console.error("Cloud sync failed"); }
    }
  };

  // --- Manejo de transacciones ---
  const handleTransaction = async (reagent: Partial<Reagent>, transactionData: Omit<Transaction, 'id' | 'timestamp' | 'reagentName'>) => {
    const timestamp = new Date().toISOString();
    let updatedReagents = [...reagents];
    let reagentId = transactionData.reagentId;
    let finalReagent: Reagent;

    if (transactionData.type === 'IN') {
      const idx = updatedReagents.findIndex(r => r.id === reagentId);
      if (idx > -1) {
        finalReagent = { 
          ...updatedReagents[idx], 
          currentStock: updatedReagents[idx].currentStock + transactionData.quantity, 
          lastUpdated: timestamp,
          isOrdered: false
        };
        updatedReagents[idx] = finalReagent;
      } else {
        finalReagent = {
          id: reagentId || generateId(),
          name: reagent.name!,
          brand: reagent.brand!,
          presentation: reagent.presentation!,
          currentStock: transactionData.quantity,
          minStock: reagent.minStock || 0,
          department: reagent.department!,
          baseUnit: reagent.baseUnit || 'ud',
          containerType: reagent.containerType || 'Frasco',
          quantityPerContainer: reagent.quantityPerContainer || 1,
          expiryDate: reagent.expiryDate || 'N/A',
          isOrdered: false,
          lastUpdated: timestamp
        };
        updatedReagents.push(finalReagent);
        reagentId = finalReagent.id;
      }
    } else {
      const idx = updatedReagents.findIndex(r => r.id === reagentId);
      if (idx === -1) return;
      finalReagent = { ...updatedReagents[idx], currentStock: Math.max(0, updatedReagents[idx].currentStock - transactionData.quantity), lastUpdated: timestamp };
      updatedReagents[idx] = finalReagent;
    }

    setReagents(updatedReagents);
    const newTransaction: Transaction = { ...transactionData, id: generateId(), reagentId: reagentId!, reagentName: finalReagent.name, timestamp };
    setTransactions([newTransaction, ...transactions]);
    showToast(`${transactionData.type === 'IN' ? 'Ingreso' : 'Salida'} registrada`);

    if (supabase) {
      await supabase.from('reagents').upsert({
        id: finalReagent.id, name: finalReagent.name, brand: finalReagent.brand, presentation: finalReagent.presentation,
        current_stock: finalReagent.currentStock, min_stock: finalReagent.minStock, department: finalReagent.department,
        base_unit: finalReagent.baseUnit, container_type: finalReagent.containerType, quantity_per_container: finalReagent.quantityPerContainer,
        expiry_date: finalReagent.expiryDate, is_ordered: finalReagent.isOrdered, last_updated: finalReagent.lastUpdated
      });
      await supabase.from('transactions').insert({
        id: newTransaction.id, reagent_id: newTransaction.reagentId, reagent_name: newTransaction.reagentName,
        type: newTransaction.type, quantity: newTransaction.quantity, display_quantity: newTransaction.displayQuantity,
        display_unit: newTransaction.displayUnit, analyst: newTransaction.analyst, timestamp: newTransaction.timestamp
      });
    }

    if (cloudUrl) {
      try {
        await fetch(cloudUrl, {
          method: 'POST',
          mode: 'no-cors',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ action: 'SYNC_ALL', reagents: updatedReagents, transaction: newTransaction })
        });
      } catch (e) { console.error("Cloud sync failed"); }
    }
  };

  const MobileNav = () => {
    const location = useLocation();
    const navItems = [
      { path: '/', icon: HomeIcon, label: 'Inicio' },
      { path: '/ingreso', icon: PlusCircleIcon, label: 'Entra' },
      { path: '/salida', icon: MinusCircleIcon, label: 'Sale' },
      { path: '/historial', icon: ClockIcon, label: 'Histo' },
      ...(role === 'GERENTE' ? [{ path: '/alertas', icon: BellAlertIcon, label: 'Alertas' }, { path: '/nube', icon: CloudIcon, label: 'Nube' }] : [])
    ];
    return (
      <div className="md:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-slate-200 flex justify-around items-center h-16 px-2 z-50">
        {navItems.map(item => (
          <Link key={item.path} to={item.path} className={`flex flex-col items-center justify-center w-full h-full transition-colors ${location.pathname === item.path ? 'text-indigo-600' : 'text-slate-400'}`}>
            <item.icon className="w-6 h-6" />
            <span className="text-[10px] font-bold mt-1 uppercase tracking-tighter">{item.label}</span>
          </Link>
        ))}
      </div>
    );
  };

  if (!role) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-600 to-indigo-900 flex items-center justify-center p-4 text-center">
        <div className="bg-white rounded-3xl shadow-2xl p-6 md:p-10 w-full max-w-md relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-1.5 flex">
            <div className={`flex-1 ${supabase ? 'bg-emerald-500' : 'bg-slate-200'}`}></div>
          </div>
          <BeakerIcon className="w-16 h-16 text-indigo-600 mx-auto mb-4" />
          <h1 className="text-3xl font-bold text-slate-800 mb-2">ReagentFlow</h1>
          <p className="text-slate-500 mb-8 font-medium italic">Gestión Laboratorial Centralizada</p>
          <div className="space-y-4">
            <button onClick={() => setShowAnalystSelection(true)} className="w-full bg-slate-50 border-2 border-slate-200 hover:border-indigo-600 hover:text-indigo-600 text-slate-700 font-bold py-5 px-6 rounded-2xl transition-all flex items-center justify-between group">
              <div className="flex items-center gap-3"><QueueListIcon className="w-6 h-6" /><span>Analista</span></div>
              <ChevronRightIcon className="w-5 h-5 opacity-50 group-hover:opacity-100" />
            </button>
            <button onClick={() => { setAuthInput(''); setAuthError(''); setShowManagerModal(true); }} className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-5 px-6 rounded-2xl transition-all flex items-center justify-between group shadow-xl">
              <div className="flex items-center gap-3"><BellAlertIcon className="w-6 h-6" /><span>Gerente</span></div>
              <ChevronRightIcon className="w-5 h-5 opacity-50 group-hover:opacity-100" />
            </button>
          </div>
          <div className="mt-8 flex flex-col items-center gap-2">
            {supabase ? (
              <div className="flex items-center gap-1.5 text-emerald-600 text-[10px] font-black uppercase tracking-widest"><WifiIcon className="w-3.5 h-3.5"/> Nube Conectada</div>
            ) : (
              <div className="flex flex-col items-center gap-2">
                <div className="flex items-center gap-1.5 text-slate-400 text-[10px] font-black uppercase tracking-widest"><ExclamationTriangleIcon className="w-3.5 h-3.5"/> Modo Local / Sin Config</div>
              </div>
            )}
          </div>
        </div>

        {/* Modal Selección Analista */}
        {showAnalystSelection && (
          <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/70 backdrop-blur-sm">
            <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm overflow-hidden animate-in fade-in zoom-in-95 duration-200">
              <div className="bg-slate-50 p-6 border-b border-slate-100 flex items-center gap-3 text-left">
                <div className="p-2 bg-indigo-100 rounded-lg"><UserIcon className="w-6 h-6 text-indigo-600" /></div>
                <div><h3 className="font-bold text-slate-800">Seleccionar Usuario</h3><p className="text-xs text-slate-500">Acceso como Analista</p></div>
              </div>
              <div className="p-4 max-h-[60vh] overflow-y-auto scrollbar-hide space-y-2">
                {analysts.length > 0 ? analysts.map((a, idx) => (
                  <button 
                    key={idx}
                    onClick={() => {
                      setCurrentUser(a);
                      setRole('ANALISTA');
                      setShowAnalystSelection(false);
                      showToast(`Bienvenido/a, ${a.name}`);
                    }}
                    className="w-full p-4 bg-slate-50 hover:bg-indigo-50 border border-slate-100 hover:border-indigo-200 rounded-xl flex justify-between items-center group transition-all"
                  >
                    <div className="text-left">
                      <p className="font-bold text-slate-700 group-hover:text-indigo-700">{a.name}</p>
                      <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{a.department}</p>
                    </div>
                    <ChevronRightIcon className="w-5 h-5 text-slate-300 group-hover:text-indigo-500" />
                  </button>
                )) : (
                   <p className="text-center text-slate-400 text-sm py-8 italic">No hay analistas registrados. Pida al gerente que los añada.</p>
                )}
              </div>
              <div className="p-4 border-t border-slate-100 bg-slate-50">
                 <button onClick={() => setShowAnalystSelection(false)} className="w-full py-3 text-slate-500 font-bold hover:bg-slate-200 rounded-xl transition-colors">Cancelar</button>
              </div>
            </div>
          </div>
        )}

        {/* Modal Auth Gerente */}
        {showManagerModal && (
          <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/70 backdrop-blur-sm">
            <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm overflow-hidden animate-in fade-in zoom-in-95 duration-200">
              <div className="bg-slate-50 p-6 border-b border-slate-100 flex items-center gap-3 text-left">
                <div className="p-2 bg-indigo-100 rounded-lg"><LockClosedIcon className="w-6 h-6 text-indigo-600" /></div>
                <div><h3 className="font-bold text-slate-800">Acceso Seguro</h3><p className="text-xs text-slate-500">Módulo Gerencial</p></div>
              </div>
              <form onSubmit={(e) => {
                e.preventDefault();
                if (!mgPassword) {
                  if (authInput.length < 4) { setAuthError('Mínimo 4 caracteres'); return; }
                  updateMgSettings(authInput); setRole('GERENTE'); setShowManagerModal(false);
                }
                else if (authInput === mgPassword) { setRole('GERENTE'); setShowManagerModal(false); }
                else { setAuthError('Clave incorrecta'); }
              }} className="p-6 space-y-4">
                <input autoFocus type="password" placeholder="****" className="w-full px-4 py-4 bg-slate-50 border-2 border-slate-200 rounded-xl outline-none focus:border-indigo-500 transition-all text-center text-2xl tracking-widest font-bold" value={authInput} onChange={(e) => setAuthInput(e.target.value)} />
                {authError && <p className="text-red-600 text-xs font-bold text-center">{authError}</p>}
                <div className="flex gap-3 pt-2">
                  <button type="button" onClick={() => setShowManagerModal(false)} className="flex-1 py-3 text-slate-500 font-bold hover:bg-slate-100 rounded-xl">Cerrar</button>
                  <button type="submit" className="flex-[2] bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 rounded-xl shadow-lg">Entrar</button>
                </div>
              </form>
            </div>
          </div>
        )}
      </div>
    );
  }

  return (
    <Router>
      <div className="flex flex-col min-h-screen bg-slate-50 pb-20 md:pb-0">
        {toast && (
          <div className={`fixed top-4 left-1/2 -translate-x-1/2 z-[100] px-6 py-3 rounded-2xl shadow-2xl flex items-center gap-3 animate-in slide-in-from-top-4 duration-300 ${toast.type === 'alert' ? 'bg-amber-600 text-white' : toast.type === 'error' ? 'bg-red-600 text-white' : 'bg-slate-900 text-white'}`}>
            <span className="font-bold text-sm">{toast.message}</span>
          </div>
        )}
        <nav className="bg-white border-b border-slate-200 sticky top-0 z-30 shadow-sm hidden md:block">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 flex justify-between h-16">
            <div className="flex items-center gap-2"><BeakerIcon className="h-8 w-8 text-indigo-600" /><span className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-indigo-600 to-blue-500">ReagentFlow</span></div>
            <div className="flex items-center gap-6">
              <Link to="/" className="text-slate-600 hover:text-indigo-600 font-bold text-sm">Inventario</Link>
              <Link to="/ingreso" className="text-slate-600 hover:text-indigo-600 font-bold text-sm">Ingresos</Link>
              <Link to="/salida" className="text-slate-600 hover:text-indigo-600 font-bold text-sm">Salidas</Link>
              <Link to="/historial" className="text-slate-600 hover:text-indigo-600 font-bold text-sm">Historial</Link>
              {role === 'GERENTE' && (
                <>
                  <Link to="/alertas" className="text-slate-600 hover:text-red-600 font-bold text-sm">Alertas</Link>
                  <Link to="/nube" className="text-slate-600 hover:text-indigo-600 font-bold text-sm">Nube Dual</Link>
                  <Link to="/config" className="text-slate-400 hover:text-indigo-600"><Cog6ToothIcon className="w-6 h-6" /></Link>
                </>
              )}
              {role === 'ANALISTA' && currentUser && (
                <div className="flex items-center gap-2 px-3 py-1 bg-slate-100 rounded-lg">
                   <UserIcon className="w-4 h-4 text-indigo-500"/>
                   <span className="text-xs font-bold text-slate-600">{currentUser.name}</span>
                </div>
              )}
              <div className="h-6 w-[1px] bg-slate-200 mx-2"></div>
              <button onClick={() => pullData()} className={`p-2 rounded-lg transition-all ${isSyncing ? 'text-indigo-600' : 'text-slate-400 hover:text-indigo-600'}`}>
                <ArrowPathIcon className={`w-5 h-5 ${isSyncing ? 'animate-spin' : ''}`} />
              </button>
              <div className={`flex items-center gap-2 px-3 py-1 rounded-full border ${supabase ? 'bg-emerald-50 border-emerald-200 text-emerald-700' : 'bg-amber-50 border-amber-200 text-amber-700'}`}>
                {supabase ? <WifiIcon className="w-3.5 h-3.5" /> : <ExclamationTriangleIcon className="w-3.5 h-3.5" />}
                <span className="text-[10px] font-black uppercase tracking-widest">{supabase ? 'Nube' : 'Sin Config'}</span>
              </div>
              <button onClick={() => { setRole(null); setCurrentUser(null); }} className="text-slate-400 hover:text-red-600"><ArrowRightOnRectangleIcon className="w-6 h-6" /></button>
            </div>
          </div>
        </nav>
        <main className="flex-grow max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
          <Routes>
            <Route path="/" element={<InventoryView reagents={reagents} />} />
            <Route path="/ingreso" element={<InputForm reagents={reagents} analysts={analysts} onTransaction={handleTransaction} transactions={transactions} currentUser={currentUser} />} />
            <Route path="/salida" element={<OutputForm reagents={reagents} analysts={analysts} onTransaction={handleTransaction} currentUser={currentUser} />} />
            <Route path="/historial" element={<HistoryView transactions={transactions} />} />
            <Route path="/alertas" element={role === 'GERENTE' ? <AlertsView reagents={reagents} markAsOrdered={handleMarkAsOrdered} onUpdateMinStock={() => {}} notifications={notifications} /> : <Navigate to="/" />} />
            <Route path="/nube" element={role === 'GERENTE' ? <CloudSyncView supaUrl={supaUrl} setSupaUrl={(url) => { setSupaUrl(url); localStorage.setItem(STORAGE_KEY_SUPA_URL, url); }} supaKey={supaKey} setSupaKey={(key) => { setSupaKey(key); localStorage.setItem(STORAGE_KEY_SUPA_KEY, key); }} cloudUrl={cloudUrl} setCloudUrl={(url) => { setCloudUrl(url); localStorage.setItem(STORAGE_KEY_CLOUD_URL, url); }} showToast={showToast} onSync={pullData} /> : <Navigate to="/" />} />
            <Route path="/config" element={role === 'GERENTE' ? <ConfigView updateMgSettings={updateMgSettings} analysts={analysts} onAddAnalyst={addAnalyst} onRemoveAnalyst={removeAnalyst} currentMg={mgPassword} currentEmail={managerEmail} /> : <Navigate to="/" />} />
          </Routes>
        </main>
        <MobileNav />
      </div>
    </Router>
  );
};

export default App;

import React, { useState, useRef, useMemo, useEffect } from 'react';
import { Reagent, Presentation, Department, Transaction, AnalystUser } from '../types';
import { analyzeReagentLabel } from '../services/geminiService';
import { fileToBase64, generateId } from '../utils';
import { 
  CameraIcon, 
  SparklesIcon, 
  ArrowPathIcon,
  PlusIcon,
  PencilSquareIcon,
  UserIcon,
  BuildingOfficeIcon,
  ExclamationTriangleIcon
} from '@heroicons/react/24/solid';

interface Props {
  reagents: Reagent[];
  analysts: AnalystUser[];
  transactions: Transaction[];
  onTransaction: (reagent: Partial<Reagent>, data: any) => void;
  currentUser: AnalystUser | null;
}

const BASE_UNITS_LIQUID = ['mL', 'L', 'uL'];
const BASE_UNITS_SOLID = ['g', 'kg', 'mg'];
const BASE_UNITS_PKG = ['unidades', 'Rx'];

const InputForm: React.FC<Props> = ({ reagents, analysts, transactions, onTransaction, currentUser }) => {
  const [loading, setLoading] = useState(false);
  const [isExisting, setIsExisting] = useState(false);
  const [selectedReagentId, setSelectedReagentId] = useState('');
  const [isCustomUnitMode, setIsCustomUnitMode] = useState(false);

  // Form State
  const [formData, setFormData] = useState({
    name: '',
    brand: '',
    presentation: 'Líquido' as Presentation,
    containerType: 'Frascos',
    quantityEntered: 0,
    quantityPerContainer: 1,
    baseUnit: 'mL',
    expiryDate: '',
    department: (currentUser?.department || 'Fisicoquímico') as Department,
    analystName: currentUser?.name || '',
    minStock: 0
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Determinar lista de unidades basada en presentación
  const unitsForPresentation = useMemo(() => {
    let units = [];
    if (formData.presentation === 'Líquido') units = [...BASE_UNITS_LIQUID];
    else if (formData.presentation === 'Sólido') units = [...BASE_UNITS_SOLID];
    else units = [...BASE_UNITS_PKG];

    return units;
  }, [formData.presentation]);

  // Resetear unidad y ajustar tipo de envase si cambia la presentación
  useEffect(() => {
    setFormData(prev => {
      const updates: any = {};

      // Lógica de Unidades
      if (!isCustomUnitMode) {
        if (formData.presentation === 'Líquido' && !BASE_UNITS_LIQUID.includes(prev.baseUnit)) {
          updates.baseUnit = 'mL';
        } else if (formData.presentation === 'Sólido' && !BASE_UNITS_SOLID.includes(prev.baseUnit)) {
          updates.baseUnit = 'g';
        } else if (formData.presentation === 'Paquete' && !BASE_UNITS_PKG.includes(prev.baseUnit)) {
          updates.baseUnit = 'unidades';
        }
      }

      // Lógica de Tipo de Envase (Solicitud Usuario)
      if (formData.presentation === 'Paquete') {
         updates.containerType = 'Paquete';
      } else if (prev.containerType === 'Paquete') {
         updates.containerType = 'Frascos';
      }

      return Object.keys(updates).length > 0 ? { ...prev, ...updates } : prev;
    });
  }, [formData.presentation, isCustomUnitMode]);

  // Calcular la frecuencia de uso para ordenar el dropdown
  const sortedReagents = useMemo(() => {
    // 1. Filtrar por departamento del usuario (si hay usuario logueado)
    let filtered = reagents;
    if (currentUser) {
        filtered = reagents.filter(r => r.department === currentUser.department);
    }

    // 2. Calcular frecuencia
    const usageCount: Record<string, number> = {};
    transactions.forEach(t => {
        usageCount[t.reagentId] = (usageCount[t.reagentId] || 0) + 1;
    });

    // 3. Ordenar (Mayor uso primero, luego alfabéticamente)
    return filtered.sort((a, b) => {
        const countA = usageCount[a.id] || 0;
        const countB = usageCount[b.id] || 0;
        if (countB !== countA) return countB - countA;
        return a.name.localeCompare(b.name);
    });
  }, [reagents, currentUser, transactions]);


  const totalBaseQuantity = useMemo(() => {
    return formData.quantityEntered * formData.quantityPerContainer;
  }, [formData.quantityEntered, formData.quantityPerContainer]);

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    try {
      const base64 = await fileToBase64(file);
      const analysis = await analyzeReagentLabel(base64);

      const newPresentation = (analysis.presentation === 'Líquido' || analysis.presentation === 'Sólido' || analysis.presentation === 'Paquete') 
        ? analysis.presentation 
        : 'Líquido';

      let newBaseUnit = 'mL';
      if (newPresentation === 'Sólido') newBaseUnit = 'g';
      if (newPresentation === 'Paquete') newBaseUnit = 'unidades';

      // Convertir a mayúsculas lo que viene de la IA
      const upperName = (analysis.name || '').toUpperCase();
      const upperBrand = (analysis.brand || '').toUpperCase();

      setFormData(prev => ({
        ...prev,
        name: upperName,
        brand: upperBrand,
        presentation: newPresentation,
        baseUnit: newBaseUnit
      }));

      const existing = reagents.find(r => 
        r.name.toUpperCase() === upperName && 
        r.brand.toUpperCase() === upperBrand
      );

      if (existing) {
        setIsExisting(true);
        setSelectedReagentId(existing.id);
        setIsCustomUnitMode(false); 
        setFormData(prev => ({ 
          ...prev, 
          baseUnit: existing.baseUnit, 
          containerType: existing.containerType,
          quantityPerContainer: existing.quantityPerContainer,
          minStock: existing.minStock,
          department: existing.department,
          presentation: existing.presentation
        }));
      } else {
        setIsExisting(false);
        setIsCustomUnitMode(false);
      }
    } catch (error) {
      console.error(error);
      alert("Error analizando la etiqueta. Por favor intente de nuevo o ingrese manualmente.");
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.analystName) {
      alert("Error de sesión: No hay analista asignado.");
      return;
    }

    // --- VALIDACIÓN DE DUPLICADOS (Solo para nuevos reactivos) ---
    if (!isExisting) {
      const normalizedName = formData.name.trim().toUpperCase();
      const normalizedBrand = formData.brand.trim().toUpperCase();

      const possibleDuplicate = reagents.find(r => {
        const rName = r.name.toUpperCase();
        const rBrand = r.brand.toUpperCase();

        // Coincidencia estricta de marca (porque es desplegable o tipificado con cuidado)
        // Y coincidencia parcial de nombre (uno contiene al otro)
        const brandMatch = rBrand === normalizedBrand;
        const nameOverlap = rName.includes(normalizedName) || normalizedName.includes(rName);

        return brandMatch && nameOverlap;
      });

      if (possibleDuplicate) {
        const confirmCreate = window.confirm(
          `⚠️ ¡POSIBLE DUPLICADO DETECTADO!\n\n` +
          `Ya existe un reactivo similar en el inventario:\n` +
          `Nombre: ${possibleDuplicate.name}\n` +
          `Marca: ${possibleDuplicate.brand}\n` +
          `Stock actual: ${possibleDuplicate.currentStock} ${possibleDuplicate.baseUnit}\n\n` +
          `Está intentando crear: "${normalizedName}" (${normalizedBrand}).\n\n` +
          `¿Está SEGURO de que desea crear uno nuevo en lugar de usar el existente?`
        );
        if (!confirmCreate) {
          return; // Cancelar el submit
        }
      }
    }
    // -----------------------------------------------------------

    const finalReagentId = (isExisting) ? selectedReagentId : undefined;

    onTransaction(
      {
        id: finalReagentId,
        name: formData.name.toUpperCase(), // Asegurar mayúsculas al guardar
        brand: formData.brand.toUpperCase(), // Asegurar mayúsculas al guardar
        presentation: formData.presentation,
        department: formData.department,
        expiryDate: formData.expiryDate || 'N/A',
        minStock: formData.minStock,
        containerType: formData.containerType,
        quantityPerContainer: formData.quantityPerContainer,
        baseUnit: formData.baseUnit
      },
      {
        reagentId: finalReagentId,
        type: 'IN',
        quantity: totalBaseQuantity,
        displayQuantity: formData.quantityEntered,
        displayUnit: formData.containerType,
        analyst: formData.analystName
      }
    );

    // Resetear formulario pero mantener usuario y depto
    setFormData(prev => ({
      ...prev,
      name: '', brand: '', presentation: 'Líquido', containerType: 'Frascos',
      quantityEntered: 0, quantityPerContainer: 1, baseUnit: 'mL', 
      expiryDate: '', minStock: 0
    }));
    setIsExisting(false);
    setSelectedReagentId('');
    setIsCustomUnitMode(false);
  };

  return (
    <div className="max-w-3xl mx-auto">
      <div className="bg-white rounded-3xl shadow-xl border border-slate-200 overflow-hidden">
        <div className="bg-indigo-600 p-6 text-white flex justify-between items-center">
          <div>
            <h2 className="text-xl font-bold">Registro de Ingreso</h2>
            <p className="text-indigo-100 text-sm">
                {currentUser ? `Analista: ${currentUser.name} | Dept: ${currentUser.department}` : 'Complete los datos'}
            </p>
          </div>
          <SparklesIcon className="w-8 h-8 opacity-40" />
        </div>

        <div className="p-8">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-8">
            <button 
              type="button"
              onClick={() => fileInputRef.current?.click()}
              disabled={loading}
              className="flex items-center justify-center gap-2 bg-indigo-50 hover:bg-indigo-100 text-indigo-700 py-4 px-4 rounded-2xl border border-indigo-200 font-bold transition-all"
            >
              {loading ? <ArrowPathIcon className="w-5 h-5 animate-spin" /> : <CameraIcon className="w-5 h-5" />}
              {loading ? "Escaneando..." : "Foto Cámara"}
            </button>
            <input type="file" ref={fileInputRef} className="hidden" capture="environment" accept="image/*" onChange={handleImageUpload} />

            <select 
              className="bg-slate-50 border-2 border-slate-200 py-4 px-4 rounded-2xl text-slate-700 font-bold outline-none focus:border-indigo-500"
              value={isExisting ? selectedReagentId : 'new'}
              onChange={(e) => {
                const val = e.target.value;
                if (val === 'new') {
                  setIsExisting(false);
                  setSelectedReagentId('');
                  setIsCustomUnitMode(false);
                  setFormData(prev => ({ ...prev, name: '', brand: '', minStock: 0 }));
                } else {
                  setIsExisting(true);
                  const r = reagents.find(x => x.id === val);
                  if(r) {
                    setSelectedReagentId(val);
                    setIsCustomUnitMode(false);
                    setFormData(prev => ({
                      ...prev, name: r.name, brand: r.brand, presentation: r.presentation,
                      baseUnit: r.baseUnit, containerType: r.containerType, 
                      quantityPerContainer: r.quantityPerContainer, minStock: r.minStock,
                      department: r.department
                    }));
                  }
                }
              }}
            >
              <option value="new">+ Nuevo Reactivo / Marca</option>
              {sortedReagents.map(r => <option key={r.id} value={r.id}>{r.name} - {r.brand}</option>)}
            </select>
          </div>

          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">

              {/* Sección Nombre y Marca */}
              <div className="space-y-2">
                <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Nombre (Mayúsculas)</label>
                <input 
                  type="text" 
                  required 
                  disabled={isExisting} 
                  className="w-full px-4 py-3 bg-slate-50 border-2 border-slate-200 rounded-xl focus:border-indigo-500 outline-none disabled:opacity-60 uppercase placeholder:normal-case" 
                  placeholder="EJ: METANOL ABSOLUTO"
                  value={formData.name} 
                  onChange={e => setFormData({...formData, name: e.target.value.toUpperCase()})} 
                />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Marca (Mayúsculas)</label>
                <input 
                  type="text" 
                  required 
                  className="w-full px-4 py-3 bg-slate-50 border-2 border-slate-200 rounded-xl focus:border-indigo-500 outline-none uppercase placeholder:normal-case" 
                  placeholder="EJ: CICARELLI"
                  value={formData.brand} 
                  onChange={e => setFormData({...formData, brand: e.target.value.toUpperCase()})} 
                />
              </div>

              {/* Sección Presentación y Envase */}
              <div className="space-y-2">
                <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Presentación</label>
                <select 
                  className="w-full px-4 py-3 bg-slate-50 border-2 border-slate-200 rounded-xl focus:border-indigo-500 outline-none font-bold"
                  value={formData.presentation}
                  disabled={isExisting}
                  onChange={e => setFormData({...formData, presentation: e.target.value as Presentation})}
                >
                  <option value="Líquido">Líquido (mL, L, uL...)</option>
                  <option value="Sólido">Sólido (g, kg, mg...)</option>
                  <option value="Paquete">Paquete / Unidad</option>
                </select>
              </div>

              <div className="space-y-2">
                <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Tipo de Envase</label>
                <input type="text" required placeholder="Frascos, Paquetes..." className="w-full px-4 py-3 bg-slate-50 border-2 border-slate-200 rounded-xl focus:border-indigo-500 outline-none" value={formData.containerType} onChange={e => setFormData({...formData, containerType: e.target.value})} />
              </div>

              {/* Sección Cantidades y Unidades */}
              <div className="space-y-2">
                <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Cant. Envases/Paquetes</label>
                <input type="number" required min="1" className="w-full px-4 py-3 bg-slate-50 border-2 border-slate-200 rounded-xl focus:border-indigo-500 outline-none" value={formData.quantityEntered || ''} onChange={e => setFormData({...formData, quantityEntered: parseInt(e.target.value) || 0})} />
              </div>

              <div className="space-y-2">
                <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Contenido Envase/Paquete</label>
                <div className="flex gap-2">
                  <input type="number" required step="0.01" className="flex-grow px-4 py-3 bg-slate-50 border-2 border-slate-200 rounded-xl focus:border-indigo-500 outline-none" value={formData.quantityPerContainer || ''} onChange={e => setFormData({...formData, quantityPerContainer: parseFloat(e.target.value) || 0})} />

                  {isCustomUnitMode ? (
                    <div className="relative w-32">
                      <input 
                        type="text" 
                        autoFocus
                        placeholder="Unidad" 
                        className="w-full px-3 py-3 bg-white border-2 border-indigo-500 rounded-xl outline-none font-bold text-center"
                        value={formData.baseUnit} 
                        onChange={e => setFormData({...formData, baseUnit: e.target.value})} 
                      />
                      <button 
                        type="button" 
                        onClick={() => { setIsCustomUnitMode(false); setFormData(prev => ({...prev, baseUnit: unitsForPresentation[0] || 'mL'})); }}
                        className="absolute -top-2 -right-2 bg-slate-200 rounded-full p-1 hover:bg-slate-300"
                      >
                        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-3 h-3 text-slate-600">
                          <path d="M6.28 5.22a.75.75 0 00-1.06 1.06L8.94 10l-3.72 3.72a.75.75 0 101.06 1.06L10 11.06l3.72 3.72a.75.75 0 101.06-1.06L11.06 10l3.72-3.72a.75.75 0 00-1.06-1.06L10 8.94 6.28 5.22z" />
                        </svg>
                      </button>
                    </div>
                  ) : (
                    <select 
                      className="w-24 border-2 border-slate-200 rounded-xl bg-slate-100 px-2 outline-none font-bold" 
                      value={formData.baseUnit} 
                      onChange={e => {
                        if (e.target.value === 'CUSTOM') setIsCustomUnitMode(true);
                        else setFormData({...formData, baseUnit: e.target.value});
                      }}
                    >
                      {unitsForPresentation.map(u => <option key={u} value={u}>{u}</option>)}
                      <option value="CUSTOM" className="font-bold text-indigo-600">OTRO...</option>
                    </select>
                  )}
                </div>
              </div>

              {/* Sección Otros Datos */}
              <div className="space-y-2">
                <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Stock Mínimo ({formData.baseUnit})</label>
                <input type="number" required min="0" step="0.01" className="w-full px-4 py-3 bg-slate-50 border-2 border-slate-200 rounded-xl focus:border-indigo-500 outline-none" value={formData.minStock || ''} onChange={e => setFormData({...formData, minStock: parseFloat(e.target.value) || 0})} />
              </div>

              {/* Campos Bloqueados: Departamento y Analista */}
              <div className="space-y-2">
                <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Departamento (Auto)</label>
                <div className="flex items-center gap-2 px-4 py-3 bg-slate-100 border-2 border-slate-200 rounded-xl text-slate-500 font-bold">
                    <BuildingOfficeIcon className="w-5 h-5"/>
                    {formData.department}
                </div>
              </div>

              <div className="space-y-2 col-span-full md:col-span-1">
                <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Analista Responsable (Auto)</label>
                <div className="flex items-center gap-2 px-4 py-3 bg-slate-100 border-2 border-slate-200 rounded-xl text-slate-500 font-bold">
                    <UserIcon className="w-5 h-5"/>
                    {formData.analystName}
                </div>
              </div>
            </div>

            <button type="submit" className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-black py-5 rounded-2xl shadow-xl transition-all active:scale-[0.98] uppercase tracking-widest">
              Confirmar Ingreso
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

