const App: React.FC = () => {
  const getEnv = (key: string) => {
    // @ts-ignore
    return (import.meta.env?.[key]) || (typeof process !== 'undefined' ? process.env?.[key] : '') || '';
  };

  const VITE_URL = getEnv('VITE_SUPABASE_URL');
  const VITE_KEY = getEnv('VITE_SUPABASE_KEY');

  // --- Inicialización de Estado ---
