                    <ChevronRightIcon className="w-5 h-5 text-slate-300 group-hover:text-indigo-500" />
                  </button>
                )) : (
                   <p className="text-center text-slate-400 text-sm py-8 italic">No hay analistas registrados. Pida al gerente que los añada.</p>
